// مولّدة آلياً بواسطة scripts/split-history.mjs — لا تُعدَّل يدوياً.
export default [{"id":3982,"title":"استعادة العثمانيين لبعض المواقع التي خسروها مثل بلغراد وغيرها .","date":["العام الهجري :1101","العام الميلادي :1689"],"text":"بعد أن تتالت الهزائم على الدولة العثمانية بفترة الصدر الأعظم مصطفى باشا، تم عزله وتولية مصطفى بن محمد كوبريلي مكانه، فكان كأبيه وأخيه من قبل، فسمح للنصارى في إستانبول ببناء ما تهدم من كنائسهم، وأحسن إليهم وعاقب بأشد العقاب كل من عرض لهم في إقامة شعائر دينهم، حتى استمال جميع نصارى الدولة، وكانت نتيجة معاملة النصارى الأرثوذكس بالعدل أن ثار أهالي مورة الأورام على البنادقة الكاثوليك، وطردوا جيشها من بلادهم بسبب اضطهادهم وإجبارهم على المذهب الكاثوليكي، ودخلوا في حماية الدولة العثمانية مختارين طائعين؛ لعدم تعرضها لديانتهم مطلقًا، ثم اتجه مصطفى كوبريلي نحو النمسا، فاستعاد بعض المواقع التي أُخذت مثل بلغراد، كما أخضع القائد القرمي سليم كراي ثوارَ الصرب، وفي الوقت نفسه أعاد تيكلي المجري إقليم ترانسلفانيا إلى الدولة العثمانية، وبهذا استعاد العثمانيون شيئًا من هيبتهم."},{"id":3983,"title":"رفع القائد البندقي موروسيني حصاره عن جزيرة \"آغري بوز\" .","date":["العام الهجري :1101","الشهر القمري : محرم","العام الميلادي :1689"],"text":"رفع القائد البندقي الشهير موروسيني حصاره عن جزيرة \"آغري بوز\" الخاضعة للحكم العثماني بعد 106 يومًا من الحصار والقتال الشرس، وقُتل خلال ذلك 23 ألفًا من البنادقة، وقد أطلق البنادقة على القلعة 182 ألف طلقة مدفعية، لكن القلعة ظلت صامدة"},{"id":3984,"title":"سقوط قلعة كانيجة في أيدي الألمان ثم استعادت العثمانيين لها .","date":["العام الهجري :1101","الشهر القمري : شوال","العام الميلادي :1690"],"text":"تمكن الألمان من إسقاط قلعة كانيجة في أيديهم، وذلك بعد 158 سنة من سيطرة الدولة العثمانية عليها، لكن العثمانيين تمكنوا من استردادها بعد ذلك بوقت قليل."},{"id":3985,"title":"استسلام قلعة بنفشه للبندقية .","date":["العام الهجري :1101","الشهر القمري : ذي القعدة","العام الميلادي :1690"],"text":"استسلمت قلعة بنفشه للبندقية بعد مقاومة استمرت 14 شهرًا، وتعد قلعة بنفشه هذه آخر قلاع الدولة العثمانية في جزيرة المورة (اليونان)."},{"id":3986,"title":"انتصار العثمانيين على الجيش الألماني في معركة زرنيت .","date":["العام الهجري :1101","الشهر القمري : ذي القعدة","العام الميلادي :1690"],"text":"انتصر العثمانيون بقيادة جركس أحمد باشا على الجيش الألماني في معركة زرنيت، ولم ينجُ من الجيش الألماني المكون من 26 ألف جندي سوى 200 جندي فقط!!"},{"id":3987,"title":"استيلاء العثمانيين على قلعة نيش من الألمان .","date":["العام الهجري :1101","الشهر القمري : ذي الحجة","العام الميلادي :1690"],"text":"تمكن العثمانيون من الاستيلاء على قلعة نيش الواقعة جنوبي صربيا، انتزعوها من الألمان، وذلك بعد حصار استمر 23 يومًا."},{"id":3988,"title":"استعادة العثمانيين السيطرة على قلعة بلجراد .","date":["العام الهجري :1102","الشهر القمري : محرم","العام الميلادي :1690"],"text":"تمكن العثمانيون من نزع السيطرة على قلعة بلجراد عاصمة صربيا الآن من يد الألمان، وتعدُّ قلعة بلجراد من أحصن القلاع، وتتكون من 9 طوابق، و116 برجًا، وقد قُتل من العثمانيين في سبيل ذلك 5 آلاف جندي."},{"id":3989,"title":"استيلاء الجيش الألماني على الأراضي المجرية التابعة للعثمانيين .","date":["العام الهجري :1102","الشهر القمري : ربيع الأول","العام الميلادي :1690"],"text":"تمكن الجيش الألماني بقيادة ماركراف من الاستيلاء على أغلب الأراضي المجرية التابعة للدولة العثمانية، مُنهيًا بذلك الحكم العثماني للمجر، والذي استمر لمدة 165 عامًا."},{"id":3990,"title":"وفاة السلطان العثماني سليمان الثاني وتولي أخيه أحمد الثاني .","date":["العام الهجري :1102","الشهر القمري : رمضان","العام الميلادي :1691"],"text":"هو السلطان سليمان الثاني بن إبراهيم الأول بن أحمد الأول بن محمد الثالث بن مراد الثالث بن سليم الثاني بن سليمان القانوني, السلطان الثاني والعشرون من سلاطين بني عثمان، ولد عام 1052هـ وتولى الحكم بعد أخيه محمد الرابع عام 1099هـ واستمر التدهور في الدولة العثمانية في عهده، وازدادت شراسة الأعداء على عهده، فاغتصبت النمسا كثيرًا من المواقع والمدن، ومنها بلجراد عام 1099هـ، كما احتلت البندقية سواحل دالماسيا والسواحل الشرقية لبحر الأدرياتيك وبعض الأماكن في اليونان، وتوالت الهزائم على الدولة، وتمرد الجند فقتلوا الصدر الأعظم سياوس باشا, فقيَّض الله للدولة رجلًا لهذا الفترة هو الصدر الأعظم مصطفى بن محمد كوبريلي الذي أعاد قوة الدولة وهيبتها. توفي سليمان الثاني في 26 رمضان عن غير عقب وعمره 50 سنة، بعد أن حكم ثلاث سنوات وثمانية أشهر، ودُفن في تربة جده السلطان سليمان الأول وتولى بعده أخوه أحمد الثاني."},{"id":3991,"title":"وفاة فاضل مصطفى باشا كوبريلي رئيس وزراء الدولة العثمانية .","date":["العام الهجري :1102","الشهر القمري : ذي القعدة","العام الميلادي :1691"],"text":"هو الصدر الأعظم فاضل مصطفى باشا ابن الصدر الأعظم محمد علي باشا كوبريلي، رئيس وزراء الدولة العثمانية، وسليل عائلة كوبريلي الشهيرة وأخو الصدر الأعظم أحمد كوبريلي، كان عظيم النفع للدولة العثمانية. لما رأى السلطان إبراهيم الأول توالي المصائب على الدولة عزل الصدر الأعظم مصطفى باشا, وعيَّن مكانه مصطفى باشا بن محمد باشا كوبريلي الكبير, ولم يكن مصطفى أضعفَ همة من والده، بل كان يشبهه في علو المكانة ومَضاء العزيمة. استشهد أثناء الحرب مع ألمانيا، عن عمر يناهز 53 عامًا، وقد استمر في رئاسة الوزراء مدة 12 عامًا و9 أشهر أعاد خلالها هيبة الدولة وقوتها."},{"id":3992,"title":"وفاة السلطان العثماني محمد الرابع بن إبراهيم الأول .","date":["العام الهجري :1104","الشهر القمري : ربيع الآخر","العام الميلادي :1693"],"text":"هو السلطان العثماني محمد الرابع بن إبراهيم الأول بن أحمد الأول بن محمد الثالث بن مراد الثالث بن سليم الثاني بن سليمان القانوني بن سليم الأول بن يزيد الثاني بن محمد الفاتح. ولد السلطان محمد عام 1051هـ، وتولى السلطنة وهو ابن سبع سنوات، فتولت جدته كوسيم مهبيكر نيابة السلطنة وأصبحت مقاليد الأمور في يديها، وساءت أحوال الدولة وتدخل الانكشارية (وهم قوات مشاة وفرسان بالجيش العثماني) في شؤونها فازدادت سوءًا، وبعد مقتل السلطانة كوسيم تولت والدة السلطان محمد خديجة تورخان نيابة السلطنة، وعلى الرغم من صغر سنها إلا أنها اتصفت برجاحة العقل فبحثت عن رجل منقذ للدولة، فوجدت بغيتها في محمد باشا كوبريلي الذي قَبِل منصب الصدر الأعظم بشرط أن تُطلق يده في تصريف الدولة. فأعلن محمد كوبريلي سنة 1066 أن السلطان محمد قد بلغ سن الرشد وتمكن من تولي زمام أمور الدولة, وبهذا الإعلان انتهى دور السلطانة الوالدة خديجة فتفرغت هي لأعمال الخير والبر, وتفرغ الصدر الأعظم كوبريلي لتدبير شؤون الدولة ومعالجة إشكالاتها الداخلية ومواجهة الأخطار الخارجية المحدِقة بها. في عهد السلطان محمد الرابع كوَّنت أوروبا حِلفًا ضم: النمسا، وبولونيا، والبندقية، ورهبان مالطة، والبابا، وروسيا، وسَمَّوه (الحلف المقدس) وذلك للوقوف في وجه المد العثماني الإسلامي الذي أصبح قريبًا من كل بيت في أوربا الشرقية بسبب جهاد العثمانيين الأبطال. بدأ الهجوم الصليبي على ديار الدولة العثمانية، وقيض الله لهذه الفترةِ آل كوبريلي الذين ساهموا في رد هجمات الأعداء وتقوية الدولة؛ فالصدر الأعظم محمد كوبريلي المتوفي عام (1072هـ/661م) أعاد للدولة هيبتها، وسار على نهجه ابنه (أحمد كوبريلي) الذي رفض الصلح مع النمسا والبندقية, وبوفاة الصدر الأعظم \"أحمد كوبريلي\" ضعُف النظام العثماني، وهاجمت النمسا بلاد المجر، واغتصبت قلعة نوهزل ومدينة بست ومدينة بودا، وأغار ملك بولونيا على ولاية البغدان، وأغارت سفن البندقية على سواحل المورة واليونان، واحتلت أثينا وكورنثة عام 1097هـ وغيرها من المدن, وكان من نتائج الهزائم المتتابعة التي لحقت بالدولة العثمانية في أواخر عهده أن ثار الجيشُ في وجه السلطان محمد الرابع، فاتفق العلماءُ ورجال الدولة على عزله، فعُزل في محرم عام 1099هـ بعد أن دامت سلطنته نحو أربعين سنة وخمسة أشهر، تولى خلالها السلطان محمد الرابع بنفسه قيادة جيوش الدولة، وبعد عزله تولى مكانه أخوه سليمان الثاني، وكانت الدولة أثناء خلع السلطان محمد الرابع قد فقدت كثيرًا من أراضيها, وبقيَ السلطان محمد الرابع في العزلة إلى أن توفي في 8 ربيع الآخر من هذه السنة بالغًا من العمر 53 سنة، ودُفن في تربة والدته ترخان سلطان."},{"id":3993,"title":"نجاح العثمانيين في الدفاع عن قلعة خانيا .","date":["العام الهجري :1104","الشهر القمري : ذي الحجة","العام الميلادي :1693"],"text":"نجح العثمانيون في جزيرة كريت شمال إيطاليا في الدفاع عن قلعة خانيا لمدة 41 يومًا؛ مما أجبر أساطيل البندقية ومالطة وفلورانسا على الانسحاب بعد خسارتهم 4 آلاف جندي."},{"id":3994,"title":"رفع الجيش الألماني حصاره عن مدينة بلجراد .","date":["العام الهجري :1105","الشهر القمري : محرم","العام الميلادي :1693"],"text":"رفع الجيش الألماني حصاره عن مدينة بلجراد التي كانت خاضعة للدولة العثمانية، بعد خسارته 10 آلاف قتيل في هذا الحصار."},{"id":3995,"title":"وفاة السلطان العثماني أحمد الثاني وتولي ابن أخيه مصطفى الثاني .","date":["العام الهجري :1106","العام الميلادي :1694"],"text":"هو السلطان العثماني أحمد الثاني بن إبراهيم الأول بن أحمد الأول بن محمد الثالث بن مراد الثالث بن سليم الثاني بن سليمان القانوني. ولد في 6 ذي الحجة سنة 1052 تولى السلطنة بعد أخيه سليمان الثاني، وأبقى الصدر الأعظم مصطفى باشا كوبريلي اعتمادًا عليه في الحرب والسلم، لكن المنية لم تمهل هذا الوزير الشهير، فاستُشهد وهو في عنفوان شبابه في 24 ذي القعدة سنة 1102هـ في حروب الدولة العثمانية مع النمسا، فكان موت مصطفى كوبريلي باشا ضربة على الدولة؛ لعدم كفاءة الصدر الأعظم عربه جي علي باشا الذي خلف كوبريلي في منصب الصدارة, فاحتل سكان البندقية سنة 1694 جزيرة ساقز. توفي السلطان أحمد الثاني بعد أن بقي في الحكم أربع سنوات وثمانية أشهر، وتولى الحكم بعده ابن أخيه مصطفى الثاني بن محمد الرابع."},{"id":3996,"title":"وفاة أمير الدرعية محمد بن مقرن بن مرخان، جد آل سعود .","date":["العام الهجري :1106","العام الميلادي :1694"],"text":"هو الأمير محمد بن مقرن بن مرخان بن إبراهيم بن موسى بن ربيعة بن مانع المريدي بن ربيعة، وينتهي نسبه إلى بكر بن وائل من بني أسد بن ربيعة أمير الدرعية وجد آل سعود."},{"id":3997,"title":"اشتباك الأسطول العثماني مع الأسطول البندقي قرب جزر قويون .","date":["العام الهجري :1106","الشهر القمري : رجب","العام الميلادي :1695"],"text":"اشتبك الأسطول العثماني مع الأسطول البندقي في معركة بحرية قرب جزر قويون، وقد غرقت خلال هذه المعركة 9 سفن للبندقية دون أن تغرق أي سفينة من السفن العثمانية."},{"id":3998,"title":"نجاح العثمانيين في استعادة قلعة ساقيز من البنادقة والمالطيين .","date":["العام الهجري :1106","الشهر القمري : رجب","العام الميلادي :1695"],"text":"نجح العثمانيون في استعادة قلعة ساقيز- الواقعة في اليونان حاليًا- من البنادقة والمالطيين الذين احتلُّوها في محرَّم من هذا العام."},{"id":3999,"title":"بدء السلطان مصطفى الثاني حملة عسكرية على ألمانيا .","date":["العام الهجري :1106","الشهر القمري : شوال","العام الميلادي :1695"],"text":"ابتدأ السلطان العثماني مصطفى الثاني حملة عسكرية مكونة من 153 ألف جندي على ألمانيا، وقد استمرَّت هذه الحملة لمدة 4 أشهر."},{"id":4000,"title":"انتصار العثمانيين على البنادقة والمجريين بقيادة مصطفى الثاني .","date":["العام الهجري :1107","العام الميلادي :1695"],"text":"انطلق السلطان مصطفى الثاني بجيشه إلى بولونيا فانتصر عليهم في عدة معارك بمساعدة القوزاق، ثم انطلق إلى بلاد المجر بعد أن فك الحصار الروسي عن مدينة آزوف، فهزم جيوش المجر، ثم في عهد ولاية الصدر الأعظم حسين كوبريلي سارت الجيوش بالأساطيل على البندقية واستردَّ بعض الجزر في بحر إيجه."},{"id":4001,"title":"غزو شريف مكة سعد بن زيد بلاد نجد .","date":["العام الهجري :1107","الشهر القمري : رمضان","العام الميلادي :1696"],"text":"غزا شريف مكة سعد بن زيد بلاد نجد، ونزل في بلدة أُشيقر، وحاصر أهلها، وكان قد سار إليها من قبل حتى وصل إلى منطقة الحمادة ثم رجع عنها."},{"id":4002,"title":"قيام حملة السلطان العثماني السلطانية الثانية على أوربا .","date":["العام الهجري :1107","الشهر القمري : رمضان","العام الميلادي :1696"],"text":"قام السلطان العثماني مصطفى الثاني بحملته السلطانية الثانية على أوربا، والتي خاض فيها العثمانيون حربًا شرسة مع الجيش الألماني، وقد أسفرت عن انتصار العثمانيين. واستمرت هذه الحملة 6 أشهر."},{"id":4003,"title":"في العنوان مكتوب (وحصار الجيش الروسي لقلعة أزاك) لكن في تفاصيل الحدث لا يوجد ذكر للحصار الروسي ! ويوجد عنوان آخر مستقل بعنوان (الروس يستولون على قلعة أزاك العثمانية) ، رقم الحدث: 4018 .","date":["العام الهجري :1107","الشهر القمري : ذي القعدة","العام الميلادي :1696"],"text":"بعد الانتصارات البحرية التي حققها العثمانيون خرج السلطان مصطفى الثاني بنفسه في هذا العام, لمحاربة النمساويين، فاستولى على قلعة ليبا وانتصر في وقعة لوغوس وقُتل الجنرال فيتراني قائد جيوش النمسا في هذه الموقعة، ثم عاد السلطان إلى الآستانة (إسطنبول حاليا). ولكن النمساويين أعادوا الكرة في السنة التالية فحاصروا قلعة طمشوار، فتقدم إليهم السلطان العثماني بجنوده وردهم عن القلعة بعد أن دحرهم دحورًا فاحشًا، ثم عاد السلطان إلى أدرنة."},{"id":4004,"title":"(بطرس) قيصر روسيا يقاتل العثمانيين ويفتح أزوف (أزاق) .","date":["العام الهجري :1108","العام الميلادي :1696"],"text":"حاصر بطرس الأكبر القيصر الروسي مدينة آزوف التي كانت أصلًا قد استردها العثمانيون وأخضعوها للدولة العثمانية أيام ثورة القوزاق عليهم، ثم أُجبر القيصر الروسي على فك الحصار عام 1107هـ بعد أن قاومهم خان القرم والعثمانيون الذين هناك، فردوهم بعد أن قتلوا منهم نحوًا من ثلاثين ألف جندي، فلما انشغل العثمانيون بالحرب مع المجر استغل الروس هذا الانشغال، فعادوا إلى آزوف ودخلوها هذا العام."},{"id":4005,"title":"الروس يستولون على قلعة أزاك العثمانية .","date":["العام الهجري :1108","العام الميلادي :1696"],"text":"حاصر الجيش الروسي المكون من مائة ألف جندي قلعة أزاك العثمانية القريبة من البحر الأسود لمدة ثلاثة وستين يومًا حتى استسلمت القلعة, ولم يتمكن العثمانيون من استرجاعها إلا بعد خمسة عشرة عامًا، ثم استرجعها الروس فجأة عام 1148هـ مما تسبب في إعلان الحرب على روسيا."},{"id":4006,"title":"خوض الجيش العثماني معركة \"أولاز\" ضد الجيش الألماني .","date":["العام الهجري :1108","الشهر القمري : محرم","العام الميلادي :1696"],"text":"خاض الجيش العثماني معركة \"أولاز\" الشرسة ضد الجيش الألماني، والتي أسفرت عن مقتل 16 ألف ألماني، و1500 عثماني."},{"id":4007,"title":"خوض الأسطول العثماني معركة بحرية ضد الأسطول البندقي .","date":["العام الهجري :1108","الشهر القمري : صفر","العام الميلادي :1696"],"text":"خاض الأسطول العثماني بقيادة القبطان ميزو مورتا حسين باشا معركة بحرية ضد الأسطول البندقي (نسبة إلى مدينة البندقية) قرب جزر أندروز، أسفرت عن غرق 13 سفينة بندقية، ومقتل 5 آلاف بحار."},{"id":4008,"title":"النمساويون يهزمون العثمانيين ومقتل الصدر الأعظم محمد باشا .","date":["العام الهجري :1109","العام الميلادي :1697"],"text":"بعد أن استطاعت الجيوش العثمانية أن تفكَّ الحصار الروسي عن آزوف سارت إلى المجر، ولكن لم تستطع هزيمة الجيش النمساوي بقيادة أوجين دي سافوا على نهر تيس، فقُتل يومها الصدر الأعظم محمد باشا وغرق أعدادٌ من العثمانيين في النهر، ولاحقهم القائد النمساوي حتى دخل بلاد البوسنة، ثم تولى الصدارة العظمى حسين كوبريلي، فسار نحو النمسا فتقهقرت أمامه جيوشُها ودفعهم إلى ما بعد نهر السافا."},{"id":4009,"title":"تعرض الجيش العثماني لهزيمة في معركة \"زينتا\" أمام الجيش الألماني .","date":["العام الهجري :1109","الشهر القمري : صفر","العام الميلادي :1697"],"text":"تعرض الجيش العثماني لهزيمة قاسية في معركة زينتا، وهي قرية تقع جنوب المجر، أمام الجيش الألماني، وقد قُتل من العثمانيين 20 ألفًا، إضافة إلى غرق 10 آلاف آخرين، وترجع هذه الهزيمة إلى خيانة بعض القادة العثمانيين."},{"id":4010,"title":"معاهدة كارلوفتس بين العثمانيين وبعض دول أوربا .","date":["العام الهجري :1110","العام الميلادي :1698"],"text":"تعتبر معاهدة كارلوفتس (كارلوفجة) إحدى أقسى المعاهدات في تاريخ الدولة العثمانية، واعتبرت بداية انحسار المد الإسلامي في أوربا، وبداية مرحلة التفكك في الدولة العثمانية، وكان من الأسباب التي أدت إلى كارلوفتس ضعف الوازع الديني عند المسلمين وبرود همَّتهم الجهادية، واستمرار ثورات الانكشارية وتقاعسهم عن أداء واجبهم، وتعاقب الحملات الصليبية واشتدادها، واتحاد القوى الأوروبية على دولة الخلافة الوحيدة، فكانت الحروب تشتعل على ثلاث أو أربع جبهات في نفس الوقت. إضافة إلى ذلك انتشار الفساد بين قيادات الدولة، ووجود قيادات عديمة الكفاءة كلُّ همها السرقة والنهب؛ فقد تم توقيع معاهدة كارلوفتس جنوب غرب زغرب على نهر الدانوب بين الدولة العثمانية وبين كل من النمسا والبندقية وروسيا وبولونيا بجهود فرنسا، فقدت الدولة العثمانية بموجبها مدينة آزوف لروسيا، وبلاد أوكرانيا وكرواتيا وإقليم بودوليا وبعض المدن لبولونيا، مثل قلنج وساحل دالماسيا، وبعض الجزر للبندقية، مثل جزيرة مورة على البحر الإدرياتيكي، وبلاد المجر وإقليم ترانسلفانيا للنمسا، وهذا مؤشر سيئ في تاريخ بعض حكام الدولة العثمانية، وهو انسحابهم في المعارك تاركين المسلمين بين يدي عدو نُزِعت من قلبه الشفقة والرحمة! وأصبحت كل الدول التي كانت تدفع الجزية عن يدٍ وهي صاغرةٌ ممتنعةً من دفعها، بل أصبحت هذه الدول تقف في وجه العثمانيين، بعد أن اتفقت فيما بينها للوقوف في وجه المد العثماني، والعمل على تقسيمها؛ وذلك خوفًا من انتشار المد الإسلامي في أوربا, وكان تنازل العثمانيين عن أراضيها بداية الانسحاب العثماني من أوربا، كما أنه يسجل الانتقال إلى عصر التفكك والاضمحلال السريع!!"},{"id":4011,"title":"انتصار العثمانيين على البندقيين جنوب جزيرة ميديلي .","date":["العام الهجري :1110","الشهر القمري : ربيع الأول","العام الميلادي :1698"],"text":"انتصر الأسطول العثماني على الأسطول البندقي في معركة بحرية جنوب جزيرة ميديلي في البحر المتوسط، وأسفرت هذه المعركة عن مقتل 2500 بندقي."},{"id":4012,"title":"انتصار العمانيين على البرتغاليين في موقعة ممبسة البحرية .","date":["العام الهجري :1110","الشهر القمري : رجب","العام الميلادي :1699"],"text":"انتصر العمانيون على البرتغاليين في موقعة ممبسة البحرية، والتي استمرت ثلاثة أيام، هبت خلالها ريح شديدة كانت سببًا في جعل الأسطول البرتغالي ينسحب من المعركة."},{"id":4013,"title":"انتصار العثمانيين على سلطان فاس .","date":["العام الهجري :1111","الشهر القمري : ذي القعدة","العام الميلادي :1700"],"text":"انتصر العثمانيون بقيادة مصطفى دايي على السلطان \"إسماعيل الكبير\" سلطان فاس في معركة \"جدوية\" وقُتِل فيها من الفاسيين 30 ألفًا."},{"id":4014,"title":"شيخ الإسلام فيض الله أفندي يتدخل في تصريف الدولة العثمانية .","date":["العام الهجري :1112","العام الميلادي :1700"],"text":"كان فيض الله أفندي معلم السلطان قبل جلوسه على كرسي السلطنة، وكان السلطان ولَّاه مسند المشيخة الإسلامية وصار يستشيره في كل الأمور، فأغاظ ذلك الصدر الأعظم حسين باشا كوبريلي لتدخُّل شيخ الإسلام في الأحوال السياسية التي ليست من متعلقات وظيفته أصلًا، وكان القبودان ميزه مورتو حسين باشا مدة حياته يجتهد في التأليف بينه وبين الصدر ويزيل النفور من قلوبهما، إلا أنه بعد وفاة القبودان استبدَّ الشيخ فيض الله أفندي في آرائه وأظهر العظمة، فلم يتحمل الصدر ذلك وقدم استعفاءه من الصدارة سنة 1114هـ, ثم أقام حسين باشا كوبريلي في ضيعة له منفردًا حتى مات بعد سبعة عشر يومًا ونُقلت جثته إلى إستانبول، ودفن في مدرسته المشهورة. وبعد أن استقال الصدر حسين باشا كوبريلي وجه السلطان الصدارة إلى دال طبان مصطفى باشا الذي التزم السير على الخطة التي يرسمها له شيخ الإسلام أفندي، ولما كان هذا الصدر يميل للحرب والقتال في الوقت الذي كانت فيه الدولة في أشد الاحتياج للمسالمة والراحة بعد الحروب الطويلة لتلتفت لإصلاح أحوالها الداخلية اختلت بذلك أحوال السياسة، وارتبكت العلاقات الخارجية حتى خيف على روابط السلم أن تنقطع, فلما تحقق للسلطان وبقية الوزراء أن الصدر دال طبان بخطته هذه سيوقع الدولة فيما تخافه من الحروب, وبعد أن وقع اضطراب وشغب بين صفوف الجنود، تم عزل الصدر دال طبان مصطفى باشا ثم قُتل، وعُين للصدارة رامي محمد باشا، وكان عالِمًا بالأمور الإدارية والأحوال السياسية، وقد تمكن بمساعدة محاميه شيخ الإسلام من تحسين الأحوال وإصلاحها، إلا أن شيخ الإسلام كان يميل إلى التغلب والتحكم في كافة الأمور، والصدر يريد مراعاة حقوق مقام الصدارة العظمى، أخذ يفكر في منع تسلط الشيخ الذي لما أحس بذلك أشعل نار الفتنة حتى استفحل أمر الهياج بين الجنود، وكان السلطان في ذلك الوقت بأدرنة -مدينة في إقليم تراقيا شمال غرب تركيا- لتولعه بالقنص كأبيه، ثم انتهت الفتنة بقتل شيخ الإسلام فيض الله أفندي."},{"id":4015,"title":"عقد الدولة العثمانية معاهدة إستانبول مع روسيا .","date":["العام الهجري :1112","الشهر القمري : محرم","العام الميلادي :1700"],"text":"عقدت الدولة العثمانية معاهدة إستانبول مع روسيا بعد مفاوضات استمرت 5 أشهر، وتضمنت المعاهدة (14) بندًا، منها: أن يكون ذهاب وإياب السفير الروسي إلى إستانبول عن طريق البر، وليس عن طريق البحر؛ لأن البحر الأسود بحر عثماني مغلق."},{"id":4016,"title":"وفاة القائد البحري العثماني الشهير ميزو مورتا حسين باشا غرقا  .","date":["العام الهجري :1113","الشهر القمري : صفر","العام الميلادي :1701"],"text":"هو القائد البحري العثماني الشهير ميزو مورتا حسين باشا حاكم جزائري عثماني، كان أحد قادة رياس البحر الكبار عندما تفاوض الداي بابا حسن- حاكم جزائري- مع الفرنسيين على أن يدفع لهم جزية كبيرة وإطلاق جميع الأسرى الفرنسيين في الجزائر لم يُعجِب طائفة رياس البحر، فقتلوا الداي بابا حسن, وعينوا حسين ميزو مورتو دايا مكانه، وبعد توليه الحكم أرسل خطابًا شديد اللهجة إلى قائد الحملة الفرنسية دوكين ينذره إلا أن دوكين كان مغترًّا بقوته فرفض الاستماع لتهديد الداي الجديد لكنه بعد ذلك خضع له وانسحب من الجزائر, ويعدُّ هذا الرجل من أهم قادة البحر الذين أنجبتهم الدولة العثمانية، وحقق انتصارات كبيرة في 8 معارك بحرية، وقد أدخل إصلاحات أساسية في القوات البحرية التركية. وقيل إن ميزو مورتا حسين توفي غرقًا أثناء نومه في سفينة القيادة."},{"id":4017,"title":"أول مطبعة بالأحرف العربية .","date":["العام الهجري :1114","العام الميلادي :1702"],"text":"تم في هذه السنة إنشاء أول مطبعة بالحروف العربية؛ فقد أنشأ عبد الله الصائغ في حلب أول مطبعة تطبع بالحروف العربية، وأنشأ أيضًا مطبعة أخرى مثلها في لبنان، أما في إستانبول فكانت أول مطبعة أنشئت فيها عام 1139هـ بعد موافقة المفتي بذلك."},{"id":4018,"title":"بناء مدينة سانت بطرسبرغ  .","date":["العام الهجري :1114","الشهر القمري : ذي الحجة","العام الميلادي :1703"],"text":"سانت بطرسبرغ مدينة روسية تقع في شمال غرب روسيا في دلتا نهر نيفا، وتعتبر أحد أكبر مراكز أوربا الثقافية. عندما احتلت روسيا مصبَّ نهر نيفا وضع القيصر بطرس الأول أساسَ مدينة سانت بطرسبرج كنافذة مطلة على أوربا، ببناء قلعة ضخمة على نهر نيفا، ثم اتسعت رغم وعورة المنطقة وكثرة المستنقعات، وسرعان ما تحولت إلى ميناء عسكري تجاري كبير، وفتحت آفاق اتصال واسع مع الحضارة الأوروبية, كانت عاصمة الإمبراطورية الروسية نحو قرنين من الزمن، وقد تحول اسمها فيما بعد إلى مدينة ليننغراد، ثم عادت إلى اسمها الأول بعد انهيار الاتحاد السوفيتي تخليدًا لمؤسسها القيصر بطرس الأول."},{"id":4019,"title":"قتال بين الباي أحمد بن سليمان وإبراهيم الشريف آغة الصبايحية .","date":["العام الهجري :1115","الشهر القمري : محرم","العام الميلادي :1703"],"text":"ظهر أحمد بن سليمان باي بن رمضان باي بن مراد الأول قائمًا في البلاد فجمع أهل الفساد، فجهَّز له إبراهيم الشريف آغة الصبايحية، وخرج له في الرابع من محرم هذه السنة وقصده نحو السوس، فالتقى عسكر من عساكر إبراهيم الشريف بأحمد بن سليمان، فوقعت الهزيمة على جيش إبراهيم الشريف، فرحل أحمد بن سليمان نحو إفريقية بقرب جندوبة، وتبعه إبراهيم الشريف، والتقيا في الحادي عشر من محرم، فانهزم أحمد بن سليمان وتشتت جمعه، وكان ينيف على ثلاثين ألفًا، ولم يكن مع إبراهيم الشريف إلا نحو ثمانية آلاف، فقصَّ آذان القتلى وبعث بها إلى تونس، فكانت أزيد من ثلاثمائة زوج، ثم دخل جبال خمير وعمدون بنفسه، وقطع قطعة من محلته وأمر عليها حسن آغة الصبايحية، وبعث بها نحو القيروان حرسًا من العدو، فبلغ ذلك أحمد بن سليمان فقصدهم فجأة وصدمهم برئيس قومه جلال بن المسعي، فانتبه له حسن آغة ونصب لهم كمينًا، فلما وردوا ماء المنايا ضربوا جلالًا فسقط عن فرسه فقُطع رأسه وبُعث به إلى تونس، فاستراح الناسُ من بغيه."},{"id":4020,"title":"خلع السلطان العثماني مصطفى الثاني وتولية أخيه أحمد الثالث .","date":["العام الهجري :1115","الشهر القمري : ربيع الأول","العام الميلادي :1703"],"text":"بعد أن استقال الصدر الأعظم حسين كوبريلي عام 1114هـ ثار الانكشارية على خلفه فاستُبدل برامي محمد باشا الذي سار على خطى كوبريلي في الإصلاح وإبطال المنكر ومحاربة الرشوة والتضييق على المفسدين، فثاروا عليه أيضًا وطلبوا من الخليفة أن يعزله فرفض. وكان الغضب واسعًا من السلطان وشيخ الإسلام فيض الله أفندي الذي كان يستأثر أقاربه بالمناصب العلمية والقضائية, فثاروا عليه أيضًا وطلبوا بخلع شيخ الإسلام، لكن الخليفة لم يفعل فقاموا بالتآمر ضد الخليفة مصطفى الثاني بن محمد الرابع، فخلعوه في هذا العام بعد أن قضى ثماني سنوات وثمانية أشهر، ثم توفي بعد خلعه بأربعة أشهر، ثم قام الانكشاريون بتولية أخيه أحمد الثالث, وقيل إن السلطان مصطفى لما بلغه أنهم يريدون خلعه دخل على أخيه أحمد خان وأعلمه بالأمر وتنازل له عن كرسي السلطنة في 9 ربيع الأوَّل من هذا العام."},{"id":4021,"title":"وفاة السلطان العثماني مصطفى الثاني بن محمد الرابع .","date":["العام الهجري :1115","الشهر القمري : رجب","العام الميلادي :1703"],"text":"هو السلطان العثماني مصطفى الثاني ابن السلطان محمد الرابع بن إبراهيم الأول بن أحمد الأول بن محمد الثالث بن مراد الثالث بن سليم الثاني بن سليمان القانوني بن سليم الأول بن بايزيد الثاني بن محمد الفاتح بن مراد الثاني بن محمد الأول جلبي بن بايزيد الأول بن مراد الأول بن أورخان. وُلِدَ عام 1074هـ وتولى الخلافة عام 1106هـ/1694م وفي عهده بدأ تراجع المد الإسلامي عن ديار أوروبا الشرقية؛ بسبب ضعف روحِ الجهاد، وتسرُّب أسباب الهزيمة في كيان الأمة، وقسوة الهجمات الصليبية على الدولة العثمانية، وفي عهده تم توقيع معاهدة كار لوفتس مع روسيا وطبقًا لهذه المعاهدة انسحب العثمانيون من بلاد المجر، وإقليم ترانسلفانيا، وأصبحت كلُّ الدول التي كانت تدفع الجزية ممتنعةً من دفعها وتقِفُ في وجه المد العثمانيين. وبدأت الدولة العثمانية في الانتقال الى عصر التفكُّك والاضمحلال السريع, وعلى إثر تدخل الانكشارية صاروا يطالبون بعزل الصدورِ كما يحلو لهم، ثم قرَّروا عزل السلطان نفسه ونصبوا أخاه أحمد الثالث, ثم توفي السلطان مصطفى بعد عزله بأربعة أشهر، وكان عند وفاته في التاسعة والثلاثين من عُمره."},{"id":4022,"title":"قتال بين باي الجزائر وباي تونس .","date":["العام الهجري :1116","العام الميلادي :1704"],"text":"جهز إبراهيم الشريف باي تونس مراكب صغارًا للغزو في سبيل الله، فغَنِمت إحداها غنيمةً بها ثلاثون نصرانيًّا وعدة صناديق بها أموال جزيلة، فدخلوا طرابلس فأحضرها خليل باي الجزائر بين يديه واغتصب منها أحد عشر نصرانيًّا واحتاط على الأموال بأسرها، فلم يُبقِ منها ولم يذرْ، واغتصب عدة صناديق بها آلات حرب وطردهم، فلما علم بذلك إبراهيم الشريف ورأى تجرؤَ خليل جمع جموعه ونصب ديوانًا في شأن تعدي خليل، فكان اتفاق الديوان على المدافعة والذب عن المال، فتجهز إبراهيم الشريف للخروج على طرابلس لمقاتلة خليل باي، فقدم قهواجي عثمان من الجزائر يحرضه على النهوض لطرابلس، وأرسل عساكر الجزائر مركبين لإبراهيم الشريف يطلبون منه الميرة؛ لقحط بلادهم تلك السنة، فتعلل إبراهيم الشريف باشتغاله بالسفر وعدم حصول الذخيرة، وأرسل لهم مائتي قنطار بشماطا، فلما جاءهم ذلك جمعوا ديوانًا، وقال حاكمهم: ألا ترون إلى إبراهيم الشريف يعطي القمح للنصارى ويمنع المسلمين، فما يريد إلا توهين عساكر الجزائر ليتقوى عليها، فخرج إبراهيم الشريف إلى طرابلس في العشر الأواخر من جمادى الآخرة من هذه السنة، فالتقى الجمعان في الثاني عشر من شعبان, فلم تكن إلا ساعة وانهزم خليل باي وأُخِذ منه مِدفَعا نحاس وثماني رايات وبغلان محملان مالًا، ومات من قوم خليل أزيد من ألف نفس وأُسر منه مثلُها، وفر خليل هاربًا فتبعته خيول إبراهيم الشريف فتنكر ودخل المدينة خائفًا من قومه حيث أوردهم هذه الموارد وما فعل بأهاليهم، ومكث إبراهيم محاصرًا لهم فضايق البلد أشدَّ مضايقة فطلبوا العفوَ وبذلوا المال، فأبى وامتنع، فتجدَّدت الحرب بين الفريقين ولم يزل متماديًا حتى قام الطاعون في المحلة ومات منها خلق كثير وفرَّ عنه العرب."},{"id":4023,"title":"وفاة إبراهيم الشريف باي تونس .","date":["العام الهجري :1117","العام الميلادي :1705"],"text":"هو إبراهيم الشريف أحد بايات وولاة تونس من الأسرة المرادية، تولى الحكم من عام 1702 حتى 1705 وهي الفترة المتأزمة التي تلت نهاية حكم المراديين وبداية حكم الحسينيين على يد حسين بن علي. كان أمير جند البايات المراديين بتونس وآغا الصبايحية. قتل مراد باي الثالث عام 1702م بأمر من العثمانيين كما قضى على كافة أبناء وأحفاد حمودة باشا، منهيًا بذلك فترة حكم المراديين بتونس. عيَّنه جند الصبايحية بايا، ثم عُيِّن باشا من قبل السلطان العثماني، ثم صار دايا، فشغل بذلك كافة المناصب على رأس الإيالة التونسية، ولكنه فشل في استعادة النظام نظرًا لأعمال الشغب والاضطرابات التي قامت منذ رحيل آخر البايات المراديين. عُزل إبراهيم الشريف من الحكم ثم أُسِر بعد هجوم جزائري على تونس, بعد أن حكم تونس ثلاث سنوات باسم العثمانيين، ومات بعد إطلاقه من الأسر خلال هذه السنة."},{"id":4024,"title":"مبايعة حسين بن علي وقيام الدولة الحسينية .","date":["العام الهجري :1117","العام الميلادي :1705"],"text":"بعد عزل باي تونس إبراهيم الشريف اجتمع أهل الحل والعقد من العلماء وأكابر العسكر بتونس، فنصبوا ديوانًا لتولية من يصلح للقيام بأمر الخلق، فلم يجدوا أصلح من حسين باي بن علي الحسيني، فجددوا بيعته وأبقوه على ما هو عليه من ولايته؛ لِما يعلمون من شفقته وعطفه وحسن عهده وسلامة صدره من المكر والحقد والغدر، ولِما جبله الله عليه من اللين والرفق وحسن التدبير والسياسة، ففرح الخلقُ عامة من أهل تونس وأوطانها وعجمها وعربها وبلدانها بتوليته، وسُقِط في يد أهل الفساد ما كانوا يتمنون، وازداد أهل الخير فرحًا به؛ لِما كانوا منه يرتقبون، وكان عفيف البطن من المسكرات، والفرج من الفواحش والمنكرات، فاستقامت أحواله وانتظمت آماله، وسَعِدت رعيته بسعده، ودافع عنهم بجِدِّه وجهده، وبتوليه انتهى عهد المراديين في تونس، وبدأ عهد البايات الحسينيين، والذي استمر إلى عهد الاستعمار الحديث وتمكين الحبيب أبي رقيبة من رئاسة تونس."},{"id":4025,"title":"وفاة العلامة النوري الصفاقسي .","date":["العام الهجري :1118","العام الميلادي :1706"],"text":"هو المقرئ الفقيه المالكي الأشعري الصوفي: أبو الحسن علي بن محمد النوري الصفاقسي، صاحب كتاب \"غيث النفع في القراءات السبع\" ولد بصفاقس سنة 1053 ونشأ بها، ورحل إلى تونس فأخذ عن أهلها، ثم رحل إلى مصر فكمل بها علومه، ثم عاد إلى مسقط رأسه وانقطع لبثِّ العلم والإرشاد. كان يأكل من كسبه فيتَّجِر ويشتغل بالقماش يتعيش منه طلبًا للحلال وتوكُّلًا على الله، ولا يأخذ عن تعليمه شيئًا. كان الشيخ النوري يدعو إلى جهاد قراصنة مالطة -فرسان القديس يوحنا- فعندما صار الناس يشكون بصفاقس من عدوانهم على سواحلهم، ينهبون السفن الراسية ويخطفون الغافلين الآمنين من البحارة، ومن يقدرون على الوصول إليه من الناس، دعا إلى الجهاد في سبيل الله تعالى، وتشاور مع أهل الفضلِ من أهل صفاقس في إنشاء سفن لهذا الغرض، فوافقه أكثرُ الناس على ذلك، وقام بجمع المال لإنشاء السفن، وأنفق هو من ماله الشيء الكثير، وأصدر فتوى بوجوب الجهاد لرد هذا العدوان، واعتبره واجبًا عينيًّا على كل مكلَّف. وقام بتنظيم شؤون المجاهدين بنفسه, وجعل لهم مقدَّمًا يأتمرون بأمره ويصلِّي بهم إمامًا, وهو تلميذه الشيخ أبو عبد الله قوبعة، فانقطع اعتداء الكفار وغنم المجاهدون منهم خيرًا كثيرًا، ويعتبر النوري هو الجد الأكبر ومؤسس عائلة النوري بصفاقس ومِن عَقِبه الشيخ محمود النوري الصفاقسي التونسي المصري."},{"id":4026,"title":"وفاة العلامة القاضي التاجموعتي .","date":["العام الهجري :1118","العام الميلادي :1706"],"text":"هو العلامة الأديب المحدِّث الخطيب النوازلي المسنِد أبو الوليد عبد الملك بن محمد التاجموعتي، قاضي سجلماسة، كان خطيباً حاد اللسان عالِمًا بالحديث عارفًا بالمخاطبات السلطانية، ينظِم الشعر، له فهرسة نسبها له تلميذه الشيخ المسناوي في إجازته لابن عاشر الحافي السلوي، وحج وجاور هناك سنوات، ودرَّس وألف بالحرمين الشريفين، وأجازه الحافظ البابلي والزرقاتي والخرشي وعمر الفكروني السوسي. كان إمامًا محدِّثًا، وكان له وجاهة عند السلطان في الهيبة وتوقير يناسِبُ منصب العلم، يصدع له بالحق في مَواطنه. له من التصانيف في السنَّة وعلومها رسالة في العلم النبوي سماها \"ملاك الطلب في جواب أستاذ حلب\"."},{"id":4027,"title":"قتال عتوب الزبارة مع عتوب الكويت ضد عرب بني كعب .","date":["العام الهجري :1119","العام الميلادي :1707"],"text":"اشترك عتوب الزبارة (آل خليفة) في قطر مع عتوب الكويت (أُسرة الصباح) في الحرب ضد عرب بني كعب، وهي من القبائل العربية القاطنة في الشاطئ الفارسي للخليج العربي. وكانت العلاقة بين آل خليفة وأسرة الصباح تقوم على أساس الصداقة والتعاون، وبخاصة في المجالات العسكرية والتجارية."},{"id":4028,"title":"استعادة الأتراك مدينة وهران من أيدي النصارى الأسبان .","date":["العام الهجري :1120","العام الميلادي :1708"],"text":"نجح الأتراك في استعادة مدينة وهران من أيدي النصارى الأسبان الذين أخذوها سنة 1114هـ  فنكبوا أهلها، فكانوا ما بين أسير وقتيل إلى أن أعادها الله عز وجل للإسلام والمسلمين على يد الأتراك هذه السنة."},{"id":4029,"title":"سعود الأول بن محمد بن مقرن يتولى إمارة الدرعية .","date":["العام الهجري :1121","العام الميلادي :1709"],"text":"كان موسى بن ربيعة بن وطبان بن ربيعة بن مرخان بن إبراهيم أميرًا للدرعية إلى أن خلعه أهلُ الدرعية، فتوجَّه إلى العيينة وتولى الإمارة مكانَه ابنُ عمه سعود الأول بن محمد بن مقرن بن مرخان بن إبراهيم الذي يلتقي مع موسى في جدهما مرخان بن إبراهيم."},{"id":4030,"title":"وفاة الزرقاني محدث الديار المصرية .","date":["العام الهجري :1122","العام الميلادي :1710"],"text":"هو الفقيه العلامة الإمام محدث الديار المصرية أبو عبد الله محمد بن عبد الباقي بن يوسف الأزهري، المالكي الناسك النحرير الشهير بالزرقاني نسبة إلى زرقان من قرى المنوفية، المصري الأزهري خاتِمة الحفاظ والمحدِّثين. ولد سنة 1055. كان شغوفًا بالعلم والعلماء منذ صِغَر سنه. أخذ عن والده وعن النور علي الشبراملسي. له مصنفات منها: شرح الزرقاني على موطأ الإمام مالك، ومختصر المقاصد الحسنة في بيان الأحاديث المشتهرة على الألسنة، والأسئلة المحيرة حول الدنيا والآخرة، وغيرها."},{"id":4031,"title":"أحمد قره مانلي يؤسس حكمًا مستقلًّا في ليبيا تابعا للعثمانيين .","date":["العام الهجري :1123","العام الميلادي :1711"],"text":"لَمَّا دخلت الدَّولةُ العُثمانيةُ في عِدَّةِ حُروبٍ في آنٍ واحدٍ مع الروسِ واليونانيِّين والبلغار والرومان والأرمن واليوغسلاف، أصبحت عاجزةً عن حمايةِ ولاياتِها وفَرْضِ النظامِ والتحَكُّمِ في الولاةِ الذين صاروا يَنصِبون ويَعزِلون حسَبَ نزواتِ الجُندِ في جوٍّ مشحون بالمؤامراتِ والعُنفِ. وفي كثيرٍ مِن الأحيان لم يبقَ الوالي في منصِبِه أكثَرَ مِن عام واحد، حتى إنه في الفترة ما بين سنة (1672 م-1711 م) تولى الحُكمَ أربعة وعشرون واليًا في ليبيا! ولقد مرَّت ليبيا بأوقاتٍ عصيبة عانى الليبيُّون فيها الويلاتِ نتيجةً لاضطراب الأمنِ وعدم الاستقرار، وفي هذه السَّنةِ قاد أحمد القره مانلي ثورةً شعبيةً أطاحت بالوالي العثماني، وكان أحمدُ هذا ضابطًا في الجيش العثماني، فقَرَّر تخليصَ ليبيا من الحكَّامِ الفاسدين ووضْعَ حدٍّ للفوضى، ولَمَّا كان شعب ليبيا قد ضاق ذَرعًا بالحُكمِ الصارمِ المستَبِدِّ، فقد رحَّب بأحمد القره مانلي الذي تعهَّد بحُكمٍ أفضَلَ، وقد وافق السلطانُ على تعيينه باشا على ليبيا، ومنحه قدرًا كبيرًا مِن الحُكمِ الذاتي، ولكِنَّ القره مانليين كانوا يعتبرون حتى الشؤون الخارجيَّة من اختصاصاتِهم."},{"id":4032,"title":"العثمانيون يحاصرون قيصر الروس ثم يوقعون معاهدة فلكزن .","date":["العام الهجري :1123","الشهر القمري : جمادى الآخرة","العام الميلادي :1711"],"text":"بعد أن تولى بلطجي محمد باشا الصدارة العظمى أعلن الحرب ضد روسيا وقاد الجيوش، فتمكن من حصار القيصر ومعه خليلته كاترينا الأولى، ومعه قرابة 200 ألف جندي، ولكن كاترينا التي قامت بإغراء الصدر الأعظم بالمال استطاعت أن تفكَّ الحصار، فنجا القيصرُ ومن معه من الإبادة أو الأسر، ووقعت معاهدة (فلكزن) في جمادى الآخرة من هذا العام بين الطرفين, تعهد فيها القيصر بعدم التدخل في شؤون القوزاق والتخلي عن ميناء آزوف."},{"id":4033,"title":"معاهدة أدرنة بين العثمانيين والروس .","date":["العام الهجري :1125","العام الميلادي :1713"],"text":"بعد توقيع المعاهدة فلكزن سنة 1123هـ بين الروس والعثمانيين والتي كانت السبب في عزل الصدر الأعظم بلطجي محمد باشا بجهود خان القرم ودعم ملك السويد، ونفيه إلى جزيرة لمنوس في بحر إيجة، وتولي يوسف باشا المنصب؛ قام بعقد معاهدةٍ جديدة مع روسيا تنصُّ على هدنة بين الطرفين مدتها خمس وعشرون سنة، غير أن الحرب كادت تتجدَّد لإخلال القيصر بالشروط، فرأت هولندا وإنجلترا أن مصلحتها إيقاف الحرب؛ ولذلك تدخلتا، ووُقِّعت معاهدة أدرنة في هذه السنة, وتنازلت فيها روسيا عن كل ما استولت عليه من سواحل البحر الأسود، ولكنها تخلت في الوقت نفسه عما كانت تدفعه إلى حكام القرم."},{"id":4034,"title":"الأسرة القرمانية في ليبيا تستقل ذاتيًّا عن الدولة العثمانية .","date":["العام الهجري :1125","العام الميلادي :1713"],"text":"أصبح أحمد القرة مانلي الداي والباشا معًا في ليبيا لصالح العثمانيين، وأسس الأسرة القرة مانلي التي حكمت طرابلس وفزان أكثر من مائة سنة، فقضى أحمد القرة مانلي مدعومًا من الانكشارية والسكان المحليين على مقاومة كبار الضباط والموظفين الأتراك؛ إذ دعاهم إلى الاجتماع وذبح ثلاثمائة شخص منهم، وفشلت الحملة العسكرية التي وُجِّهت ضده من قِبَل الدولة العثمانية."},{"id":4035,"title":"العثمانيون يهزمون البنادقة ويستردون الجزر في بحر إيجة .","date":["العام الهجري :1126","العام الميلادي :1714"],"text":"انتصر العثمانيون على البنادقة وأخذوا منهم ما بقي بأيديهم من جزيرة كريت وبعض الجزر الأخرى، فاستنجد البنادقة بالنمسا التي ارتاحت من الحروب بينها وبين فرنسا، فطلب إمبراطور النمسا من الدولة العثمانية إرجاعَ ما أُخذ من البنادقة إليهم، فرفضت الدولة العثمانية وقامت الحرب من جديد بين الطرفين وانتصرت النمسا وقُتِل الصدر الأعظم علي باشا."},{"id":4036,"title":"تغلب الألمان على الجيش العثماني في معركة بترفارادين .","date":["العام الهجري :1128","الشهر القمري : شعبان","العام الميلادي :1716"],"text":"تمكَّن القائد الألماني الشهير \" أوجين\" من هزيمة الجيش العثماني في معركة بترفارادين، وكان سبب هزيمة العثمانيين هو تشتُّت الجيش العثماني بعد مقتل قائده الوزير تورك أحمد بك حاكم الأناضول."},{"id":4037,"title":"استيلاء الأمير الألماني أوجين على قلعة \"تامشوار\" الخاضعة للعثمانيين .","date":["العام الهجري :1128","الشهر القمري : ذي القعدة","العام الميلادي :1716"],"text":"تمكَّن الأمير الألماني أوجين من الاستيلاء على قلعة \"تامشوار\" التي كانت خاضعة للعثمانيين، وهي مدينة مجرية، وتسببت سيطرة الألمان على هذه القلعة في انقطاع صلة العثمانيين بالمجر."},{"id":4038,"title":"سيطرة الألمان على مدينة بلغراد من الدولة العثمانية .","date":["العام الهجري :1129","الشهر القمري : رمضان","العام الميلادي :1717"],"text":"سيطر الأمير الألماني أوجين على مدينة بلغراد من الدولة العثمانية بعد 42 يومًا من الحصار، وقد سقط من العثمانيين 20 ألفًا قُتِلوا أثناء محاولة فك الحصار عن المدينة، ودام الاحتلالُ الألماني لبلغراد 22 عامًا."},{"id":4039,"title":"معاهدة (بساروفتس) وتخلي الدولة العثمانية عن الصرب وبلغراد .","date":["العام الهجري :1130","العام الميلادي :1717"],"text":"بعد أن انتصرت النمسا على العثمانيين وجاء الصدر الأعظم الجديد خليل باشا الذي جاء مددًا للعثمانيين، فهُزم أيضًا أمام النمسا وسقطت بلغراد عام 1129هـ ثم جرى الصلح، ووقعت معاهدة بساروفتس بجهود إنكلترا، فأخذت بموجبها النمسا مدينة بلغراد وأكثر بلاد الصرب وجزءًا من الأفلاق، ولكن تبقى سواحل دالماسيا للبندقية، وترجع بلاد المورة للعثمانيين."},{"id":4040,"title":"توقيع الدولة العثمانية معاهدة \"بساروفيتش\" مع النمسا والبندقية .","date":["العام الهجري :1130","الشهر القمري : شعبان","العام الميلادي :1718"],"text":"بدأت مساعي الصلح بين الدولة العثمانية وكل من النمسا والبندقية بعد (12) يومًا من صدارة إبراهيم باشا- أي من بدء توليه رئاسة الوزراء- وانتهت هذه المساعي بتوقيع معاهدة وصلح \"بساروفيتش\" في 22 شعبان من هذه السنة، وقد تكونت هذه المعاهدة من (20) مادة خاصة بالنمسا، و(26) مادة خاصة بالبندقية، وقد أنهت حالة الحرب مع البندقية، والتي استمرت ثلاث سنوات وسبعة أشهر، ومع النمسا التي استمرت سنتين وشهرين، وتقضي هذه المعاهدة بإعادة المورة إلى الدولة العثمانية لقاء تنازلها عن مقاطعة تمسوار وبلجراد وصربيا الشمالية وبلاد الفلاخ، وأن تبقى جمهورية البندقية محتلة ثغور شاطئ دلماسيا، وأن يستعيد رجال الدين الكاثوليك مزاياهم القديمة في الدولة العثمانية!"},{"id":4041,"title":"تعديل معاهدة بساروفيتش .","date":["العام الهجري :1133","الشهر القمري : محرم","العام الميلادي :1720"],"text":"طلبت روسيا من الدولة العثمانية تعديل معاهدة بساروفيتش، وذلك بما يتيح لتجَّارها المرور من أراضي الدولة العثمانية وبيع سِلَعِهم فيها، وأن يتوجَّه الحجاج الروس إلى بيت المقدس وغيره من الأماكن والأديرة المقدسة بدون دفعِ خراج أو رسوم أثناء إقامتهم أو على جوازات سفرهم. وأضيف إلى هذه المعاهدة شرط آخر ذو أهمية سياسية كبيرة؛ حيث تعهدت الدولة العثمانية وروسيا بموجِبه بمنع زيادة نفوذ الملك المنتخب ببولونيا على نفوذ الإشراف، وعدم تمكينه من جعْل منصبه وراثيًّا في عائلته، ومنْع وصول هذين الأمرين بكل الوسائل الممكنة، بما فيها الحرب. وقصد الإمبراطور الروسي بطرس الأكبر بهذا الشرط إيجاد النفور والعداوة بين البولونيين والعثمانيين؛ حتى لا يتشكَّلَ حِلفٌ بين مجاوريه الأقوياء (السويد وبولونيا والدولة العثمانية) فيقوموا بمحاربته، وهذا يعني إضعاف مجاوريه الواحد بعد الآخر؛ لتزيد قوة روسيا بازدياد ضعف جيرانها الأقوياء، وقد نجح فيما يتعلق بالسويد، ثم شرع في تنفيذ خطته ضد بولونيا والدولة العثمانية، ووضع الإمبراطور الروسي بهذه المعاهد أولَ حجر في مشروعه لإضعاف بولونيا مع الدولة العثمانية."},{"id":4042,"title":"ارتكاب الثوار اليونانيين مذبحة كبيرة ضد الأتراك .","date":["العام الهجري :1133","الشهر القمري : ذي الحجة","العام الميلادي :1721"],"text":"ارتكب الثوار اليونانيون مذبحة كبيرة ضد الأتراك في مدينة تريبوليجة، وذلك في الرابع والعشرين من شهر ذي الحجة من هذه السنة، وقد راح ضحية تلك المذبحة 8 آلاف مدني (غير عسكري)، وقد حدث ذلك في أثناء الثورة اليونانية ضد الدولة العثمانية."},{"id":4043,"title":"هجوم القاجاريين في إيران على الأناضول الشرقية وحصارهم لبغداد .","date":["العام الهجري :1134","الشهر القمري : محرم","العام الميلادي :1721"],"text":"استغل القاجاريون في إيران انشغال الدولة العثمانية بإخماد ثورة اليونان، وقاموا بمهاجمة الأناضول الشرقية وحاصروا بغداد، وقد عُقد بعد سنتين صلحٌ بين الجانبين لإنهاء الحرب بينهما، وكانت تلك آخِرَ حرب بين إيران وتركيا."},{"id":4044,"title":"إعلان الثوار اليونانيين تأسيس اليونان .","date":["العام الهجري :1134","الشهر القمري : ربيع الآخر","العام الميلادي :1722"],"text":"أعلن الثوار اليونانيون ضِدَّ الدولة العثمانية تأسيسَ دولة اليونان التي تضم المورة وجزر كيكلاد، وجزيرة أغرى بوز."},{"id":4045,"title":"سيطرة العثمانيين على ميناء وقلعة ساقيز في اليونان .","date":["العام الهجري :1134","الشهر القمري : جمادى الآخرة","العام الميلادي :1722"],"text":"تمكن العثمانيون بقيادة القائد البحري العثماني نصوح زاده علي باشا من السيطرة على ميناء وقلعة ساقيز في اليونان إبَّان الثورة اليونانية ضد الدولة العثمانية، وذلك بعد 19 يومًا من بدء العصيان ضد العثمانيين."},{"id":4046,"title":"الاتفاق بين روسيا وتركيا على اقتسام بلاد فارس .","date":["العام الهجري :1137","العام الميلادي :1724"],"text":"ضعُفت الدولة الصفوية وتنازل الشاه حسين عن السلطة لمير محمد أمير بلاد أفغانستان، فأسرع الصدر الأعظم إبراهيم باشا واحتل بلاد أرمينيا وبلاد الكرج وأسرع قيصر روسيا بطرس الأكبر واحتلَّ بلاد داغستان وساحل بحر الخزر الغربية، واصطدمت الجيوشُ العثمانية والروسية، وكادت الحرب أن تقع بين الطرفين لولا وساطةُ فرنسا بناءً على طلب من روسيا التي وجَدت نفسها عاجزة عن القتال، فبقي كل فريق في المناطق التي دخلها دون معارضةِ الفريق الآخر."},{"id":4047,"title":"وفاة الأمير سعود بن محمد الأول أمير الدرعية .","date":["العام الهجري :1137","الشهر القمري : رمضان","العام الميلادي :1725"],"text":"هو الأميرُ سعود بن محمد بن مقرن بن مرخان، أمير الدرعية جدُّ آل سعود حكَّام المملكة العربية السعودية، كان مسكنُه الدرعية بنجد، وهي كانت أساس المُلك."},{"id":4048,"title":"الأفغان يستولون على بلاد فارس .","date":["العام الهجري :1138","العام الميلادي :1725"],"text":"كان كركين خان قد تقدم بجيشه إلى أفغانستان وأخضعهم تحت نفوذه، ثم إنَّهم استغاثوا من ظُلمِه بملك الصفويين، ولكن كركين كان قد سبقهم وأعلمه أنهم عبارة عن عصاة، ثم برز أويس الذي كان يحكم قندهار فأرسله كركين إلى الشاه الصفوي على أنه زعيم العصاة، لكنه حظِيَ بالقرب من الشاه وفكَّر في الاستقلال، لكنه رأى أن يتريَّث وخاصة أن الدولة الصفوية أخذت في الهَرَم والضعف، ثم رجع إلى بلاده ليكون رقيبًا على كركين، وأراد كركين أن يذِلَّه بتزوجه من ابنته فدبَّر له مكيدة وقتله، ثم بدأ بقتل الفرس الموجودين في قندهار وانسلخت أفغانستان عن إيران، ثم فكَّروا بضم إيران لهم، وكان قد استصدر فتاوى بحل قتال الشيعة الروافض، ولما رأى الشاه الصفوي أنه لا بدَّ من القتال صدع بالأمر، لكنه لقيَ ما لم يكن في حسابه، فكُسِر في الموقعة التي جرت بينهما، ثم عاود الكَرَّة بجيش بقيادة خسرو خان ابن أخي كركين المقتول، ولكنهم هُزِموا كسَلَفِهم بعد أن استطاعوا الوصولَ إلى قندهار وحصارها، وقتلوا خسرو أيضًا، ثم أرسل الشاه جيشًا ثالثًا فأصيب كما أصيب سابقاه، واستقل الأفغان، ثم تولى محمود ابن أويس بعد موته، فأرسل الشاه جيشًا ليُخضِعَه، لكنه أيضًا هُزم أمام الأفغان، ثم قدم محمود ابن أويس بجيشِه عن طريق الصحراء فوصل إلى كرمان وحاصرها، لكنه اضطر للعودة لمجيء القوات المغيثة، ثم عاد مرة أخرى ووصل الخبر إلى إيران وفزع الناسُ حتى خرج الشاه من المدينة، وقَبْل وصول جيش محمود إلى أصفهان عرض عليه الشاه المصالحة والمال لكنه أبى وحاصر أصفهان، ثم هجمت جيوشُ الشاه عليهم بعد أن انقسموا فرقتين، فاستطاع الأفغان دحْرَ الجيش الأول واستولوا على مَدافِعِه واستعملوها ضد الجيش، ففُتِحت المدينة بعد القتال الشديد، وأصبحت في يد محمود ووقعت العاصمة بيده، واستسلم الشاه واعتلى محمودٌ على عرش إيران، وانتهت دولة الصفويين."},{"id":4049,"title":"ظهور وباء في العيينة ووفاة أميرها عبد الله بن معمر .","date":["العام الهجري :1138","العام الميلادي :1725"],"text":"وقع وباء كبير في مدينة العيينة أقوى إمارات نجد، وأودى بحياةِ عدد كبير من رجالها، ومن بينهم أميرُها عبد الله بن معمر الذي حكمها لمدة 41 عامًا من (1096هـ ـ 1138هـ) ولم يكن في زمانه في نجد من يضاهيه في الرئاسة وقوة الملك والعدة."},{"id":4050,"title":"روسيا القيصرية تسيطر على بحر قزوين التابع لبلاد فارس الإسلامية .","date":["العام الهجري :1138","العام الميلادي :1725"],"text":"لَمَّا رأى بطرس الأكبر قيصر روسيا أن الدولة الصفوية بدأت تضعُف، قام باحتلال بلاد داغستان وسواحل بحر الخزر (قزوين) الغربية، وقام الصفويون بالرد وكادت الحرب أن تستمر لولا تواسط فرنسا بناء على طلب روسيا، فتم الصلح بين الدولتين، ولكِنْ على أن يبقى مع كل طرف ما أخذه."},{"id":4051,"title":"وفاة الإمام العلامة نور الدين السندي .","date":["العام الهجري :1138","الشهر القمري : شوال","العام الميلادي :1726"],"text":"هو الشيخُ الإمام العلَّامة المحقِّق المدقِّق نور الدين أبو الحسن بن عبد الهادي السندي، من فقهاء الأحناف المشهورين. ولِدَ ببته قرية من بلاد السند ونشأ بها ثم ارتحل إلى تستر، وأخذ بها عن جملة من الشيوخ، كالسيد محمد البرزنجي، والملا إبراهيم الكوراني، وغيرهما، ودرَّس بالحرم الشريف النبوي، واشتهر بالفضل والذكاء والصلاح. استوطن المدينةَ المنورة، برع في علم الحديث، وألَّف مؤلفات نافعة من الحواشي، منها: حاشية على كل من سنن أبي داود والنسائي وابن ماجه، وعلى مسند أحمد، وعلى صحيحي البخاري ومسلم، وعلى البيضاوي، وغيرها من المؤلفات التي سارت بها الركبان، وكان شيخًا جليلًا عالِمًا عاملًا ورعًا زاهدًا، ماهرًا محققًا بالحديث والتفسير والفقه والأصول والمعاني والمنطق والعربية، وغيرها، أخذ عنه جملةٍ من الشيوخ، منهم: الشيخ محمد حياة السندي وغيره. كانت وفاته بالمدينة المنورة ثاني عشري شوال، وكان لوفاته مشهد عظيم حضره جمٌّ غفير من الناس حتى النساء، وغُلِّقت الدكاكين، وحمل الولاة نعشَه إلى المسجد النبوي الشريف، وصلِّي عليه به، ودُفِن بالبقيع، وكُثَر البكاءُ والأسفُ عليه."},{"id":4052,"title":"وفاة الملك إسماعيل بن محمد ملك العلويين في مراكش وتولي ابنه أحمد .","date":["العام الهجري :1139","العام الميلادي :1726"],"text":"هو الملك أبو النصر إسماعيل بن محمد بن علي المراكشي، الملك الثاني لدولة العلويين في مراكش. ولد سنة 1057 بتافيلات التي تقع جنوب شرقي المغرب. كانت الدولة العلوية في عهده أزهى أيامها، وقد نقل عاصمته من مراكش إلى مكناسة، توفِّي بعد أن أمضى في الحكم سبعة وخمسين عامًا، وخلفه ابنُه أحمد."},{"id":4053,"title":"تولي الأمير محمد بن سعود بن محمد بن مقرن إمارة الدرعية .","date":["العام الهجري :1139","العام الميلادي :1726"],"text":"توالى أبناء مانع المريدي وأحفادُه على حُكم إمارة الدرعية والقرى التي حولها، ولم يتجاوزوها إلى أن آلت الإمارة إلى الأمير محمد بن سعود بن محمد بن مقرن بن مرخان هذه السنة, والذي تمَّت في عهده سنة 1157هـ المعاهدة التاريخية بينه وبين الإمام المجدد محمد بن عبد الوهاب. ومنها بدأت دولةُ الدرعية بالتوسُّعِ والحركة، حيث آزروا الشيخ محمد بن عبدالوهاب على تبليغ الدعوة، وانتشرت حتى ضَمَّت كل بلاد العارض عدا الرياض وأغلب منطقة الخرج وحائر والوشم والمحمل وسدير."},{"id":4054,"title":"توقيع الدولة العثمانية معاهدة \"آينا قاياق\" مع روسيا .","date":["العام الهجري :1139","الشهر القمري : ربيع الأول","العام الميلادي :1726"],"text":"وقَّعت الدولة العثمانية معاهدة \"آينا قاياق\" مع روسيا، حول جزيرة القرم، وكانت هذه المعاهدة ضدَّ مصالحِ الدَّولةِ العُثمانيَّةِ."},{"id":4055,"title":"استيلاء  العثمانيين على بعض أراضي الصفويين .","date":["العام الهجري :1140","العام الميلادي :1727"],"text":"لما ضعُف الصفويون استولى العثمانيون على كثيرٍ مِن مناطقهم، ثم ما لبث الصفويون أن هبُّوا وقاتلوا العثمانيين، ولكنهم هُزموا وفقدوا تبريز وهمدان وعددًا من القلاع، ثم جرى الصلح, ومات الشاه، وبقي الشاه طهماسب فطلب من العثمانيين أن يتخلَّوا عما أخذوه فلم يقبلوا فغزاهم، ولم تكن عند الخليفة حرارة القتال، فثار الانكشارية عليه وقتلوا الصدر الأعظم وأمير البحر، ثم امتد أذاهم وعصيانهم إلى الخليفة."},{"id":4056,"title":"توقيع الدولة العثمانية معاهدة مع إيران حول الحدود بين الجانبين .","date":["العام الهجري :1140","الشهر القمري : صفر","العام الميلادي :1727"],"text":"بعد فتح العثمانيين عدة مدن وقلاع إيرانية، أهمها مدائن همدان وأريوان وتبريز؛ وذلك نتيجة لتسلط الفوضى داخل إيران، وتنازع كل من الشاه أشرف الذي قتل مير محمد أمير أفغانستان، والشاه طهماسب ملك ساسان. انتهت هذه الحرب بالصلح مع الشاه أشرف في 25 صفر سنة 1140هـ"},{"id":4057,"title":"وفاة الملك أحمد الذهبي ملك العلويين في المغرب وقيام أخيه عبدالله .","date":["العام الهجري :1141","العام الميلادي :1728"],"text":"هو الملك أحمد الذهبي بن إسماعيل بن محمد بن علي: ملك العَلويين الحسنيين في المغرب الأقصى، وعُرف بالذهبي لبسط يده بالعطاء، وبعد توليته قتَل كثيرًا من عمال أبيه وأركان دولته, وكان ضعيف الإرادة، يستشير عبيدَه في أغلب شؤونه، فتسلَّطوا على الناس حتى ضجَّ أهل فاس وثاروا على السلطان سنة 1140 فنقَضوا بيعته، وتبِعَهم أهل مكناسة فقبضوا عليه، وبايعوا أخاه عبد الملك بن إسماعيل. قام عبد الملك بنفي أخيه أحمد إلى سجلماسة، ولكن العبيدَ أتباع أحمد انقضُّوا على عبد الملك ففرَّ إلى فاس، وأُعيد إلى الحكم وجُدِّدت له البيعة، فقَبَض على أخيه ثم قتله، ولم يلبث بعده أكثر من ثلاثة أيام حتى توفِّي هو أيضًا، وتولى الأمر بعده أخوه عبد الله بن إسماعيل."},{"id":4058,"title":"الدولة العثمانية والتأثر بالحضارة الغربية .","date":["العام الهجري :1141","العام الميلادي :1728"],"text":"كان عددٌ قليل من العثمانيين قد نادى بالإصلاح للوصول إلى الوسائل التي حققت بها أوروبا قوَّتها خاصة في التنظيم العسكري والأسلحة الحديثة, وكان الداماد إبراهيم باشا الذي تولى الصدارة العظمى في عهد السلطان أحمد الثالث هو أول مسؤول عثماني يعترف بأهمية التعرف على الإصلاحات الأوربية؛ لذا فإنه أقام اتصالاتٍ منتظمةً بالسفراء الأوربيين المقيمين بالآستانة، وأرسل السفراءَ العثمانيين إلى العواصم الأوروبية، وبخاصة فيينا وباريس للمرة الأولى, وكانت مهمة هؤلاء السفراء لا تقتصر على توقيع الاتفاقات التجارية والدبلوماسية الخاصة بالمعاهدات التي سبق توقيعها، بل إنه طلب منهم تزويد الدولة بمعلومات عن الدبلوماسية الأوروبية وقوة أوربا العسكرية. وكان معنى ذلك فتح ثغرة في الستار الحديدي العثماني والاعتراف بالأمر الواقع الخاص بأنه لم يعُد بإمكان العثمانيين تجاهل التطورات الداخلية التي كانت تحدُث في أوروبا. وقد بدأ التأثر بأوروبا في مجال بناء القصور والإسراف والبذخ اللذين شارك فيهما السلطان أحمد ذاته بنصيب كبير؛ مما جعل الأغنياء وعلية القوم يسعون الى اقتباس العادات الأوروبية الخاصة بالأثاث وتزيين الدور وبناء القصور وإنشاء الحدائق، حتى بدا ظهور تقليد الغرب في شهواتهم وإسرافهم للعِيان"},{"id":4059,"title":"خلع السلطان العثماني أحمد الثالث وتولية ابن أخيه محمود الأول .","date":["العام الهجري :1143","العام الميلادي :1730"],"text":"ثار الانكشارية على السلطان أحمد الثالث لعدم ميله إلى الحربِ مع الدولة الصفوية ورغبته في الصلح معهم، فقتلوا الصدرَ الأعظم والمفتي وأمير البحر، حتى امتد أذاهم وعصيانهم وعزلوا الخليفة أحمد الثالث بن مصطفى الثاني بعد أن دام في الخلافة سبعة وعشرين سنة وأحد عشر شهرًا، وبقي معزولًا حتى توفي عام 1149هـ، وقام الانكشارية بتولية ابن أخيه محمود الأول بن مصطفى الثاني."},{"id":4060,"title":"معركة كوريجان بين الدولة العثمانية والإيرانيين .","date":["العام الهجري :1143","الشهر القمري : ربيع الأول","العام الميلادي :1730"],"text":"وهي المعركة التي استرجعت فيها الدولة العثمانية مدينة همدان بعد انتصارها على الإيرانيين في معركة \"كوريجان\"، التي قُتل فيها ثلاثة أرباع الجيش الصفوي المكوَّن من 40 ألف جندي."},{"id":4061,"title":"وفاة الشاعر عبد الغني النابلسي .","date":["العام الهجري :1143","الشهر القمري : شعبان","العام الميلادي :1731"],"text":"هو الشاعر عبد الغني بن إسماعيل النابلسي الشاعر المتصوف، وهو عالم بالأدب والتاريخ، ولد سنة 1050 بدمشق ونشأ بها، ثم رحل إلى بغداد، ثم تنقل بين سوريا وفلسطين ومصر ولبنان، ثم عاد واستقر في دمشق وبها توفي، له مصنفات عديدة، أشهرها: (تعطير الأنام في تعبير المنام)، وله (الحقيقة والمجاز في الرحلة إلى بلاد الشام ومصر والحجاز)، وله (التحفة النابلسية في الرحلة الطرابلسية)، وله (كنز الحقائق المبين في أحاديث سيد المرسلين)، وغيرها من الكتب."},{"id":4062,"title":"قتال العثمانيين مع الصفويين واسترجاع الصفويين ممتلكاتهم .","date":["العام الهجري :1144","العام الميلادي :1731"],"text":"اتجهت الدولة العثمانية إلى قتال الشيعة الصفوية، فتغلبت على طهماسب الذي طلب الصلح في هذا العام, وتخلى العثمانيون عن تبريز، وهمدان، ولورستان، غير أنَّ والي الشاه على خراسان وهو نادر شاه لم يقبل بهذه المعاهدة. فسار إلى أصفهان، وعزل الشاه طهماسب، وولى مكانه ابنه عباسًا، وعيَّنَ عليه مجلس وصاية، ثم سار نادر شاه لحرب العثمانيين فانتصر عليهم، وحاصر بغداد، فطلبت الدولة العثمانية الصلحَ، وجرى الاتفاق عام 1149هـ/1736م في مدينة تفليس، حيث أعلن نادر شاه نفسه ملكًا على الفرس، واتفقوا على أن يرد العثمانيون كل ما أخذوه إلى الشيعة الإيرانية."},{"id":4063,"title":"استعادة الأسبان السيطرة على ميناء ومدينة \"وهران\" من العثمانيين .","date":["العام الهجري :1145","الشهر القمري : محرم","العام الميلادي :1732"],"text":"تمكَّنَ الأسبان من استعادة السيطرة على ميناء ومدينة \"وهران\" الجزائرية من العثمانيين. وكان العثمانيون قد فتحوا وهران قبل 24 عامًا، وخلصوها من الاحتلال الأسباني."},{"id":4064,"title":"حصار الشاه الإيراني لبغداد .","date":["العام الهجري :1145","الشهر القمري : رجب","العام الميلادي :1733"],"text":"حاصر الشاه الإيراني نادر شاه- بعد هزيمته العسكرية الكبيرة أمام العثمانيين- مدينة بغداد التي كانت خاضعة للدولة العثمانية، واستمرَّ هذا الحصار 7 أشهر و8 أيام."},{"id":4065,"title":"الفرس بقيادة نادر شاه يطردون الأفغان من بلادهم .","date":["العام الهجري :1146","العام الميلادي :1733"],"text":"كان نادر شاه في أول أمره من قطَّاع الطرق، ثم برز اسمه أيام الفوضى فجمع حوله الرجال ورأى من المصلحة العمل باسم الشاه الصفوي، فانتصر على الأفغان عام 1141هـ ولاحقهم، فاعتصم سلطانهم في مدينة أصفهان، فحاصره نادر شاه واستطاع أشرف سلطان الأفغان أن ينسحب نحو شيراز، وتابع نادر شاه الأفغانَ حتى أخرجهم من منطقة فارس عام 1142هـ، ولما أصبح الأمر لنادر شاه بعد موت الشاه عباس الثالث حارب الأفغان واستولى على قندهار وبلخ، وقاتَلَ الأوزبك، ودخل كابل وبيشاور ودهلي عام 1151هـ."},{"id":4066,"title":"هزيمة الشاه الإيراني على يد الدولة العثمانية .","date":["العام الهجري :1146","الشهر القمري : صفر","العام الميلادي :1733"],"text":"تلقى الشاه الإيراني نادر شاه هزيمةً قاسية من الدولة العثمانية أمام مدينة بغداد، في حرب استمَرَّت 9 ساعات، خَسِر خلالها نادر شاه 30 ألف جندي تقريبًا."},{"id":4067,"title":"افتتاح مدرسة الهندسة الإمبراطورية في الدولة العثمانية .","date":["العام الهجري :1147","الشهر القمري : شعبان","العام الميلادي :1735"],"text":"تم افتتاح مدرسة الهندسة الإمبراطورية في الدولة العثمانية، وكان الهدف الأول من إنشائها هو تخريج ضباط الاستحكامات والمهندسين العسكريين للجيش العثماني."},{"id":4068,"title":"قيام دولة الأفشار بقيادة نادر شاه خلفا لدولة الصفويين .","date":["العام الهجري :1148","العام الميلادي :1735"],"text":"استطاع محمود بن أويس الأفغاني أن ينهي دولة الصفويين في إيران، ثم عقبه أشرف بن عبد العزيز  ابن عمه، وكان طهماسب بن حسين الصفوي الذي فرَّ من أصفهان يريد استرجاعَ الملك، وكان قد تعاقد مع الروس على أن يُعينوه ضدَّ الأفغان على أن يتخلى لهم عن البلاد الشمالية من إيران، وكان نادر شاه قائد جيوشه فزحفوا إلى أصفهان لطرد أشرف الأفغاني الذي تولى بعد محمود الأفغاني، وكان السكان الإيرانيون الذين بقوا في إيران قد ساعدوا في القتال وانضموا لجيش طهماسب ونادر شاه، واستطاع نادر بعد حروب شديدة أن يستردَّ أصفهان، فصارت القوةُ كلُّها لنادر شاه، مع أن المُلك لطهماسب، ولكن الأمر لم يدُمْ طويلًا حتى أصبح نادر شاه حاكمًا على خراسان وكرمان وخوارزم وسيستان، ثم تمَّ له الأمر بواسطة الحرب مع العثمانيين الذين كانوا يغيرون على البلاد الغربية لإيران، ثم عاد نادر إلى خراسان لثورة الأفغان فيها، وتقدَّم طهماسب إلى جهة الأتراك ليكمل القتال عن نادر، لكنه كُسِر كسرة عنيفة فعقد الصلح مع الأتراك، فلما سمِعَ نادر بذلك خلعه وعيَّن مكانه ابنه عباسًا الطفل، وصار هو الوصيَّ عليه، ثم مات هذا الطفل فصار هو الملك باسم حِفظِ البلاد من الفوضى والأعداء، ويُذكر أن أصل نادر هو من الأفشار من خراسان، وبذلك بدأت دولة الأفشار وانتهت تمامًا دولة الصفويين."},{"id":4069,"title":"استيلاء الروس على قلعة \"أزاك\" من الدولة العثمانية .","date":["العام الهجري :1148","الشهر القمري : ذي الحجة","العام الميلادي :1736"],"text":"استطاع الروسُ الاستيلاءَ بشكلٍ مفاجئ على قلعة \"أزاك\" من الدولة العثمانية؛ مما تسبب في إعلان استانبول الحربَ على روسيا في 7 صفر 1149هـ."},{"id":4070,"title":"الحرب بين العثمانيين وبين الروس ومعهم النمسا .","date":["العام الهجري :1148","الشهر القمري : ذي الحجة","العام الميلادي :1736"],"text":"اتحدت النمسا مع روسيا لمحاربة تركيا، وكانت الدولة خارجة من حرب إيران فساقت روسيا جيوشها تحت قيادة الفلد مارشال مونيخ، حاصرت فرقةٌ منه قلعةَ أزوف (آزاق). ودخلت فرقةٌ أخرى من برزخ أورقبو، وهددت بلاد القرم، وهاجمت فرقةٌ ثالثة قلعةَ كيلبرون فاضطرت تركيا لإعلان الحرب عليها، وسار الصدر الأعظم على رأس الجيوش، وساقت النمسا جيوشها على قلعة شهر كوي، ودخلت عساكرُها بلاد البوسنة، ثمَّ تقدَّمت الجيوش التركية وقاتلت النمسا، وانتصرت عليها، وشتَّتت جيوشها في الوقائع التي حدثت في خلال سنة (1149) و (1150) و (1151) هـ، واستردَّت تركيا جهات نيش وشهر كوي، ثم هزم جيش عوض محمد باشا جيشًا ثالثًا للنمساويين، وكان يتقدَّم على ويدوين، وأحرق العثمانيون لهم سبع سفن حربية، ثم عبرت الجيوش التركية نهر الدانوب، واستولوا على أراضي باجوه وحوالي مهاديا وإقليم طمشوار، واغتنموا جميع ذخائر ومدافع النمساويين. وفتح الصدر الأعظم قلعة أوسوفا وقلعة أطه وسمندرة، فاضطرت النمسا بإزاء هذه الهزائم المتوالية أن تطلُب الصلحَ، وتدخَّلت دول فرنسا وهولندا والسويد في الأمر، وفي أثناء ذلك انتصرت الجيوشُ العثمانية في واقعة كروسكا على الجيوش النمساوية. أمَّا جيوش روسيا فقد لاقت مثلَ ما لاقت جيوش النمسا من الاندحار، وذلك في الوقائع التي حدثت بقرب شاطئ نهر بروت وجهة أورقيو، ودخل الأسطول العثماني إلى البحر الأسود تحت قيادة القبودان سليمان باشا وسحَقَ الأسطول الروسي في بحر أزوف (آزاق). فطلبت الدولتان المتحدتان الصلحَ، فعقد على أن تسلم النمسا بلغراد وجميع البلاد الواقعة على الضفة اليمنى من نهري صاوه والدانوب، وهي التي كانت استولت عليها بانتصاراتها السابقة، وأن ترُدَّ إلى الدولة العثمانية أراضي أرسوه والبلاد المسماة بالأفلاق النمساوية، وأن تترك الدولة للنمسا المواقع التي استولت عليها في هذه الحرب، وهي يانجوه وطمشوار، وأن تكون الهدنة لمدة (27) سنة. أما الصلح مع روسيا فقضى عليها بهدم قلعة أزوف وألَّا يكون لها فيما بعد مراكب حربية ولا تجارية بالبحر الأسود، وبحر أزوف معًا، وأن تعيدَ للدولة كلَّ ما فتحته من البلاد، وأن تنقل تجارتها على سفن أجنبية. وبعد هذا الصلح أبرمت الدولة معاهدة هجومية دفاعية مع السويد ضد روسيا."},{"id":4071,"title":"وفاة السلطان العثماني أحمد الثالث\n  .","date":["العام الهجري :1149","العام الميلادي :1736"],"text":"هو السلطانُ أحمد الثالث بن السلطان محمد الرابع بن إبراهيم الأول بن أحمد الأول بن محمد الثالث بن مراد الثالث بن سليم الثاني بن سليمان القانوني بن سليم الأول، المولود في 3 رمضان سنة 1083/ 23 ديسمبر سنة 1673 وعند تعيينه سلطانًا للدولة وزع أموالًا طائلة على الانكشارية، وسلم لهم في قتل المفتي فيض الله أفندي لمقاومته لهم في أعمالهم, فلما استقرَّت الأحوال وعادت السكينة اقتصَّ السلطان أحمد من رؤوس الانكشارية، فقتل منهم عددًا ليس بقليل، وعزل في 6 رجب سنة 1115 الصدرَ الأعظم نشانجي أحمد باشا الذي انتخبه الانكشارية وقت ثورتهم، وعين بدلًا عنه زوج أخته داماد حسن باشا, وعلى الرغم من مصاهرته للسلطان وما أتاه من الأعمال النافعة كتجديد الترسانة وإنشاء كثير من المدارس من أن يكون هدفًا لدسائس المفسدين أرباب الغايات الذين لا يروق في أعينهم وجود أعنَّة الأمور في قبضة رجل حازم يحول بينهم وبين ما يشتهون، فأعملوا فكرهم وبذلوا جهدَهم حتى تحصلوا على عزله في 28 جمادى الأولى 1116 وكثُر من بعده تغييرُ الصدور تبعًا للأهواء, ومما يُذكر في تاريخ السلطان أحمد الثالث أنه أدخل المطبعة في بلاده، وأسس دار طباعة في الآستانة بعد إقرار المفتي وإصداره الفتوى بذلك، مشترطًا عدم طبع القرآن الشريف خوفا من التحريف؛ واسترجاع إقليم المورة وقلعة آزاق، وفتح عدة ولاياتٍ مِن مملكة العجم, ولَمَّا ظهر من السلطان أحمد عدم الميل لحرب دولة الفرس والرغبة في الصلح معهم ثار عليه الانكشارية، فقتلوا الصدر الأعظم والمفتي وأمير البحر، ثم عزلوا السلطان ونصبوا ابن أخيه محمود الأول بن مصطفى الثاني, وبقي السلطان أحمد معزولًا إلى أن توفِّيَ هذه السنة."},{"id":4072,"title":"الدولة العثمانية توقف تقدم روسيا في إقليم البغدان .","date":["العام الهجري :1149","العام الميلادي :1736"],"text":"أعلنت روسيا والنمسا الحرب على بولندا، واحتلَّتها روسيا، ورغبت فرنسا في التحالف مع الدولة العثمانية لإنقاذ بولندا من كلٍّ مِن النمسا وروسيا, فأرضت النمسا فرنسا بمعاهدة فيينا, واتفقت من جهة ثانية لقتال الدولة العثمانية، وبدأت روسيا القتالَ ضد الدولة العثمانية، فتمكَّن العثمانيون من وقفِ تقدُّم الروس في إقليم البغدان."},{"id":4073,"title":"توقيع الدولة العثمانية معاهدة استانبول مع إيران  .","date":["العام الهجري :1149","الشهر القمري : جمادى الآخرة","العام الميلادي :1736"],"text":"بعد حرب دامت ست سنوات بين الإيرانيين والدولة العثمانية، طلبت الدولة العثمانية توقيع معاهدة استانبول مع إيران بقيادة نادر شاه، وكانت المعاهدة في مدينة تفليس حيث نودي في حينه بنادر شاه ملكًا على إيران، على أن تردَّ الدولة العثمانية إلى إيران كلَّ ما أخذته منها، وأن تكون حدود الدولتين كما تقرر بمعاهدة سنة 1639م المبرمة في زمن السلطان الغازي مراد الرابع."},{"id":4074,"title":"إعلان ألمانيا الحرب على الدولة العثمانية .","date":["العام الهجري :1150","الشهر القمري : ربيع الأول","العام الميلادي :1737"],"text":"أعلنت ألمانيا الحربَ على الدولة العثمانية بعد هزيمة حليفتها روسيا أمام العثمانيين في شبه جزيرة القرم، ووقوع مائة ألف روسي في الأسر."},{"id":4075,"title":"نادر شاه حاكم إيران يفتح (كابل) و(غزنة) ويهزم قوات المغول .","date":["العام الهجري :1152","العام الميلادي :1739"],"text":"بعد أن استطاع نادر شاه السُّني اعتلاء عرش إيران بعد أن أنهى حُكمَ الصفويين فيها، أراد أول شيء أن يُخضِع الأفغان؛ لعلمه أنَّهم ربما يثورون عليه كما ثاروا على الصفويين قبله، بل هو الذي استطاع أن يستردَّ إيران من أيديهم، فاستعان بقطاع الطرق البختياريين الذين استطاع أن يلاحِقَهم حتى ألحقهم بجيشِه، واستطاع أن يفتحَ قندهار الحصينة، وكابل وغزنة, وكان رضا قلي ميرزا ابن نادر شاه على رأس جيشٍ أخذ يتقدَّم نحو بلاد التتار (المغول) ويستولي على مواقِعِهم، بينما كان والده نادر شاه محاصِرًا لقندهار, فنهاه والده عن الاستمرار حتى يكسِبَ وُدَّهم, وليتفرغ هو لإخضاع بقية البلاد التي في مملكته."},{"id":4076,"title":"توقيع الدولة العثمانية معاهدة \"بلغراد\" مع ألمانيا وروسيا .","date":["العام الهجري :1152","الشهر القمري : جمادى الآخرة","العام الميلادي :1739"],"text":"أوقفت الدولةُ العثمانيةُ تقدُّمَ الروس في بلاد البغدان والألمان في البوسنة والصرب والأفلاق، فانسحب الألمانُ من الحرب، وطلبوا الصلحَ عن طريق فرنسا، وتم توقيع معاهدة بلغراد بين الدولة العثمانية مع كلٍّ من ألمانيا من جهة، وروسيا من جهة أخرى، تعهَّد فيها الألمان بتسليم بلغراد للدولة العثمانية بعد احتلالٍ دام 22 سنة، وتعهدت روسيا بهدم قلاعِ ميناء آزوف وتسليم أرضِها للعثمانيين، وألَّا تُبحِرَ أيةُ سفينة روسية في البحر الأسود."},{"id":4077,"title":"وفاة الشيخ عبد الوهاب بن سليمان التميمي والد الإمام المجدد  .","date":["العام الهجري :1153","العام الميلادي :1740"],"text":"هو عبد الوهاب بن سليمان بن علي بن مشرف التميمي النجدي، فقيه حنبلي، والد الشيخ المجدد محمَّد بن عبد الوهَّاب. من أهل العُيينة بنجدٍ، من علماء نجد وفقهائها، تولى القضاء في العُيينة, ثم انتقل منها ليتولى قضاء حريملاء. له كتابات في بعض المسائل الفقهية."},{"id":4078,"title":"طرد الشيخ محمد بن عبد الوهاب من حريملاء وانتقاله إلى العيينة .","date":["العام الهجري :1153","العام الميلادي :1740"],"text":"كان الشيخ عبد الوهاب بن سليمان والد الشيخ محمد بن عبد الوهاب قد انتقل إلى حريملاء وتولى القضاء فيها, فلما قَدِم الشيخ من رحلاته العلمية على والدِه في حريملاء أخذ يقرأُ عليه, ويُنكِرُ ما يفعلُه الجهَّال من البدع والشرك في الأقوال والأفعال، وكثُرَ منه الإنكار لذلك ولجميع المحظورات، حتى وقع بينه وبين أبيه كلام، وكذلك وقع بينه وبين الناس في البلد, فأقام على ذلك مدة سنين، حتى توفي والده في هذه السنة، فأعلن بالدعوة والإنكار، والأمر بالمعروف والنهي عن المنكر, وتبعه أناسٌ مِن أهل حريملاء ومالوا معه واشتهر بذلك، وكان رؤساء أهل بلد حريملاء قبيلتين وقع بينهما خلاف ولم يكن للبلد رئيس يزع الجميع إليه. وكان في البلد عبيدٌ لإحدى القبلتين، كثيرٌ تعدِّيهم وفسقهم, فأراد الشيخ أن يُمنَعوا عن الفساد, فهمَّ العبيد أن يفتكوا بالشيخ ويقتلوه بالليل سرًّا. فلما تسوَّروا عليه الجدار عَلِم بهم أناس فصاحوا بهم فهربوا. فانتقل الشيخ بعدها إلى العُيينة, ورئيسُها يومئذ عثمان بن حمد بن معمر،  فتلقاه بالقبول وأكرمه, وتزوج الشيخُ فيها من عمة ابن معمر: الجوهرة بنت عبد الله بن معمر, ثم عرض الشيخُ على ابن معمر ما قام به ودعا إليه، وقال له: إني أرجو إنْ أنت قمتَ بنصر لا إله إلا الله أن يُظهِرَك الله وتَملِكَ نجدًا وأعرابها, فساعده عثمان على ذلك."},{"id":4079,"title":"حدوث شغب العبيد على السلطان مولاي عبد الله بالمغرب .","date":["العام الهجري :1154","الشهر القمري : ربيع الأول","العام الميلادي :1741"],"text":"لما كان شهر ربيع الأول من هذه السنة، شغَّب العبيد على السلطان مولاي عبد الله بن إسماعيل بن مولاي علي الشريف العلوي, وهمُّوا بخلعه والإيقاع به، فنذرت بذلك أمه الحرة خناثى بنت بكار، ففرت من مكناسة إلى فاس الجديد، ومن الغد تبِعَها ابنها السلطان المولى عبد الله، ونزل برأس الماء فخرج إليه الودايا وأهل فاس وأجَلُّوا مَقدَمَه واهتزُّوا له، فاستعطفهم السلطان وقال لهم: أنتم جيشي وعدتي، ويميني وشمالي، وأريد منكم أن تكونوا معي على كلمة واحدة، وعاهدهم وعاهدوه ورجعوا، وفي أثناء ذلك بلغه أن أحمد بن علي الريفي قد كاتب عبيد مشرع الرملة وكاتبوه واتفق معهم على خلع السلطان مولاي عبد الله وبيعة أخيه مولاي زين العابدين، وكان يومئذ عنده بطنجة وأنهم وافقوه، فوجم لها السلطان مولاي عبد الله، ثم استعجل أمر المولى زين العابدين ففرَّ مولاي عبد الله إلى بلاد البربر."},{"id":4080,"title":"مبايعة مولاي زين العابدين بن إسماعيل سلطانًا على المغرب .","date":["العام الهجري :1154","الشهر القمري : ربيع الأول","العام الميلادي :1741"],"text":"كان ابتداءُ أمر السلطان مولاي زين العابدين بن إسماعيل العلوي أنَّه قَدِم مكناسة في أيام أخيه مولاي المستضيء، فلما سمع به أمَرَ بسجنه وضربه، فضُرب وهو في قيده ضربًا وجيعًا أشرف منه على الموت، ثم أمر ببعثه مقيَّدًا إلى سجلماسة؛ كي يُسجَن بها مع بعض الأشراف المسجونين هنالك، فلما سمع بذلك قوَّاد رؤوسهم من العبيد، بعثوا مَن رَدَّه من صفرو إلى فاس، ثم بعثوا به إلى القائد أبي العباس أحمد الكعيدي ببني يازغة وأمروه أن يحتفظَ به مكرَّمًا مُبجَّلًا, ثم لَمَّا فَرَّ المستضيء عن مكناسة وراجع العبيد طاعةَ السلطان مولاي عبد الله بن إسماعيل، دخل مولاي زين العابدين مدينة فاس فاطمأنَّ بها وسُرَّ بولاية أخيه مولاي عبد الله، ثم سار إلى طنجة فقَدِمَ على صاحبها الباشا أحمد بن علي الريفي، فأكرم وفادتَه وأحسن مثواه واستمر مقيمًا عنده إلى أن كاتب عبيدُ الديوان في شأن زين العابدين  ووافقوه على خلعِ مولاي عبد الله وبيعته، فبايعه الباشا أحمد وبايعه أهل طنجة وتطاوين والفحص والجبال، وخطبوا به على منابرهم، ثم هيأ له الباشا أحمد كتيبةً من الخيل من عبيد الديوان وغيرهم، وبعثهم معه إلى مكناسة، فدخلها وبُويع بها البيعةَ العامة، وقَدِمت عليه وفودُ القبائل والأمصار، فقابلهم بما يجِبُ وتمَّ أمره, وفرَّ السلطان مولاي عبد الله من رأس الماء ودخل بلاد البربر ولم يقدم على مولاي زين العابدين أحدٌ من الودايا ولا من أهل فاس، وكان فيه أناة وحلم لم يظهر منه عَسفٌ ولا امتدت يده إلى مالِ أحد إلَّا أنه لقلة ذات يده نقص العبيدَ من راتبهم فكان ذلك سببَ انحرافِهم عنه."},{"id":4081,"title":"طرد الشيخ محمد بن عبد الوهاب من العيينة  .","date":["العام الهجري :1157","العام الميلادي :1744"],"text":"بعد أن طلب أميرُ الأحساءِ وزعيمُ بني خالد: سليمان بن محمد بن غرير آل حميد الخالدي من حاكِمِ العُيينة التخلُّصَ مِن الشيخ محمد بن عبد الوهاب, فكتب إلى عثمان يتوعَّدُه ويأمُرُه أن يقتُلَ هذا المطَوَّع الذي عنده في العُيينة, وقال: إن المطوع الذي عندكم بلغنا عنه كذا وكذا، فإما أن تقتُلَه، وإما أن نقطَعَ عنك خراجَك الذي عندنا!! وكان عنده للأمير عثمان خراجٌ من الذهب، فعظم على عثمانَ أمرُ هذا الأمير، وخاف إن عصاه أن يقطَعَ عنه خراجه أو يحارِبَه، فقال للشيخ: إنَّ هذا الأمير كتب إلينا كذا وكذا، وإنه لا يحسن منا أن نقتُلَك، وإنا نخاف هذا الأمير ولا نستطيع محاربتَه، فإذا رأيتَ أن تخرُجَ عنا فعلْتَ، فقال له الشيخ: إن الذي أدعو إليه هو دينُ الله وتحقيقُ كلمة لا إله إلا الله، وتحقيقُ شهادة أنَّ محمدًا رسول الله، فمن تمسَّك بهذا الدين ونصره وصَدَق في ذلك نصره الله وأيَّدَه وولَّاه على بلاد أعدائه، فإن صبَرْتَ واستقمْتَ وقَبِلْتَ هذا الخير، فأبشِرْ فسينصرُك الله ويحميك من هذا البدوي وغيره، وسوف يولِّيك الله بلادَه وعشيرته, فقال: أيُّها الشيخُ، إنَّا لا نستطيعُ محاربته، ولا صبرَ لنا على مخالفتِه، فخرج الشيخ عند ذلك وتحوَّل من العُيينة إلى بلاد الدرعية، جاء إليها ماشيًا- فيما ذكروا- حتى وصل إليها في آخر النهار، وقد خرجَ من العيينة في أوَّلِ النهار ماشيًا على الأقدام لم يَرحَلْه عثمان، فدخل على شخصٍ مِن خيارها في أعلى البلد يقال له محمد بن سويلم العريني، فنزل عليه."},{"id":4082,"title":"تحالف الأمير محمد بن سعود مع الشيخ محمد بن عبد الوهاب .","date":["العام الهجري :1157","العام الميلادي :1744"],"text":"خرج الإمامُ محمد بن عبد الوهاب من العُيينة بنجدٍ يدعو إلى دينِ الله القويم، وقد كانت منطقةُ نجد في هذه الفترة انتشر فيها الشِّركُ والبِدَع، فلقي الشيخُ صعوبات كثيرة إلى أن يسَّرَ الله له الأميرَ محمد بن سعود أمير الدرعية، فتم بينهما اتفاقٌ تاريخي في هذا العام عُرِف \"باتفاق الدرعية\" لَمَّا وصل الشيخ محمد بن عبد الوهاب إلى الدرعية دخل على شخصٍ مِن خيارها في أعلى البلد يقال له: محمد بن سويلم العريني، فنزل عليه, ويقالُ إنَّ هذا الرجل خاف من نزوله عليه وضاقت به الأرضُ بما رَحُبت، وخاف من أميرِ الدرعية محمد بن سعود، فطمأَنَه الشيخ وقال له: أبشِرْ بخير، وهذا الذي أدعو الناسَ إليه دينُ الله، وسوف يُظهِرُه الله، فبلغ محمَّدَ بن سعود خبرُ الشيخ محمد، ويقال: إن الذي أخبره به زوجتُه، جاء إليها بعضُ الصالحين وقال لها: أخبري زوجَك الأمير محمدًا بهذا الرجل، وشجِّعيه على قَبولِ دعوته، وحَرِّضيه على مؤازرته ومساعدتِه، وكانت امرأةً صالحةً طَيِّبةً، فلما دخل عليها محمد بن سعود أمير الدرعية وملحقاتها قالت له: أبشر بهذه الغنيمة العظيمة! هذه غنيمة ساقها الله إليك، رجلٌ داعية يدعو إلى دينِ الله، ويدعو إلى كتاب الله، يدعو إلى سنَّةِ رَسولِ الله عليه الصلاة والسلام، يا لها من غنيمة! بادِرْ بقَبوله وبادر بنُصرته، ولا تقف في ذلك أبدًا، فقبل الأمير مشورتَها، ثم تردد هل يذهب إليه أو يدعوه إليه؟! فأشير عليه، ويقال: إن المرأة أيضًا هي التي أشارت عليه مع جماعة من الصالحين، وقالوا له: لا ينبغي أن تدعوه إليك، بل ينبغي أن تقصِدَه في منزله، وأن تقصِدَه أنت وأن تعظِّمَ العلم والداعيَ إلى الخير، فأجاب إلى ذلك لما كتب الله له من السعادةِ والخيرِ- رحمةُ الله عليه، وأكرم الله مثواه- فذهب إلى الشيخ في بيت محمد بن سويلم العريني، ورحب به قائلًا: \"أبشر ببلاد خيرٍ مِن بلادك، وأبشر بالعِزِّ والمنعة، فقال الشيخ محمد: وأنا أبشِّرُك بالعز والتمكين، وهذه كلمةُ لا إله إلا الله، من تمسَّك بها وعمل بها ونصرها، مَلك بها البلادَ والعباد، وهي كلمةُ التوحيد، وأوَّلُ ما دعت إليه الرسل، من أوَّلهم إلى آخرهم, ثم بين الشيخ محمد بن عبد الوهاب للأمير محمد بن سعود حقيقةَ الإسلام والإيمان، وأخبره ببطلان ما عليه أهل نجد من عبادة الأوثان والأصنام والأشجار، فقال الأمير له: يا شيخ، لاشك عندي أنَّ ما دعوتَ إليه أنَّه دين الله الذي أرسل به رسُلَه وأنزل به كتُبَه، وأنَّ ما عليه اليوم أهلُ نجد من هذه العبادات الباطلة هو كما ذكرت نفسُ ما كان عليه المشركون الأولون من الكُفرِ باللهِ والإشراك، فأبشِرْ بنُصرتِك وحمايتك والقيام بدعوتِك، ولكن أريد أن أشتَرِطَ عليك شرطين: نحن إذا قمنا بنصرتك وجاهدنا معك ودان أهلُ نجد بالإسلام وقَبِلوا دعوة التوحيد، أخاف أن ترتحِلَ عنا وتستبدل بنا غيرَنا، والثاني: أن لي على أهل الدرعية قانونًا آخذُه منهم وقت حصاد الثمارِ، وأخاف أن تقول: لا تأخذ منهم شيئًا، فقال الشيخ: أما الشرط الأول فابسُطْ يدك أعاهِدْك: الدَّمُ بالدَّمِ، والهدمُ بالهدم، وأما الثاني فلعل الله أن يفتحَ عليك الفتوحاتِ فيُعَوِّضَك من الغنائِمِ والزكوات ما هو خيرٌ منه. فتمَّ التعاهد والاتفاق بينهما\"، فقام الأمير محمد بن سعود بمؤازرة الشيخ ودَعْمِه وحمايته؛ ليقوم بتبليغ الدعوة، فانطلق الشيخ محمد يصحح الأوضاعَ الدينية المتردِّية، فقويت الدرعية سياسيًّا ودينيًّا, ثم انطلقت منها الجيوشُ لتوحيد الأجزاء المتفَرِّقة من نجد وما حولها ونشْرِ الدعوة فيها."},{"id":4083,"title":"وفاة الشيخ محمد بن علي التهانوي .","date":["العام الهجري :1158","العام الميلادي :1745"],"text":"هو الشيخ الفاضل محمد بن علي بن حامد بن صابر بن الفاروقي التهانوي الهندي الحَنَفي: أحدُ رجال العلم، اشتُهر بكتابه الشهير: كشاف اصطلاحات الفنون. عاش التهانوي في عصر سلاطين الدولة المغولية في الهند، فأدرك طَرَفًا من عهد الإمبراطور أورنغ زيب عالمكير الذي عرفت الهندُ في عصره حركةً علمية ثقافية نَشِطةً بتشجيعه لها. وقد قيل: إن التهانوي كان قاضيًا في قريته تهانة في عصر هذا الإمبراطور. نشأ التهانوي في بيئة علمية، نهل من ينابيعها؛ إذ كان والده من كبار العلماء حتى لُقِّب بقطب الزمان، في هذا الجوِّ المفعم بالزاد والنشاط العلميين عاش التهانوي، فنهل من ينابيع المعرفة وبحار العلم. وجال على الحواضِرِ يلتقي العلماءَ ويستمع إليهم يأخُذُ عنهم وينكبُّ على بحثِه, فلا عجب أن أورد في تقديمه الكشاف قوله: \"لَمَّا فرغت من تحصيل العلوم العربية والشرعية من حضرة جناب أستاذي ووالدي، شمَّرت عن ساق الجِدِّ إلى اقتناء ذخائر العلوم الحكمية الفلسفية من الحكمة الطبيعية والإلهية والرياضية كعِلم الحساب والهندسة والهيئة والإسطرلاب ونحوها. فلم يتيسر لي تحصيلًا من الأساتذة، فصرفت شطرًا من الزمان إلى مطالعة مختصراتها الموجودة عندي، فكشفها الله عليَّ، فاقتبست منها المصطلحات وسطَّرتُها على حدة في كل بابٍ يليق بها\"  كان قرأ النحوَ والعربية على والده وتفَقَّه عليه, ثم طَفِق يقتني ذخائِرَ العلوم الحكمية، فجمع الكتب، ولم يتَّفِقْ له تحصيلُها على الأساتذة، فصرف شطرًا من الزمان في مطالعة الكتب الموجودة عنده, فجمع في مصنَّفِه الكشَّاف- الذي يعتبر معجمًا لغويًّا فنيًّا- مصطلحاتِ العلوم وتعريفَها، وشرَحَ الموضوعات العلمية الاصطلاحية حسب العلم ورتبه أبجديًّا. وقد فرغ من تصنيفه سنة 1158, وقد اختُلف في تاريخ وفاته، والمتَّفق عليه أنَّه توفي بعد سنة 1158."},{"id":4084,"title":"ابتدأ الصراع العسكري بين الدرعية والرياض .","date":["العام الهجري :1159","العام الميلادي :1746"],"text":"ظلَّت دعوة الشيخ محمد بن عبد الوهاب في نجد سلميةً دون الدخولِ مع خصوم الدعوة في أي صدامٍ عسكري منذ الاتفاق التاريخي بين أمير الدرعية والشيخ محمد بن عبد الوهاب عام 1157 إلى هذا العام، حين ابتدأ الصراع العسكري بين الدرعية والرياض، بعد انضمام منفوحة إلى دعوة الشيخ محمد بن عبد الوهاب في هذه السنة، حيث قام دهام بن دواس أميرُ الرياض بالهجوم على المنفوحة الذين لبَّوا دعوة الشيخ محمد بن عبد الوهاب ودخلوا في طاعة الأمير محمد بن سعود، فعدا عليهم صباحًا على غِرَّة ومعه بعض أهل الرياض وبعض سكان البوادي من آل ظفير، فكمن لهم قرب البلد وأمر البوادي والخيل أن تغير على زرعهم ونخلِهم في أطراف البلدة، فهبَّ المقاتلون من أهل المنفوحة مع أميرِهم علي بن مزروع وردُّوهم على أعقابِهم بعد مقاومةٍ عنيفة، جُرح فيها دهام بن دواس وقُتِل فرَسُه، كما قُتل أحد عشر رجلًا من رجالِه."},{"id":4085,"title":"وقعة العمارية بين جيش الرياض وجيش الدرعية .","date":["العام الهجري :1159","العام الميلادي :1746"],"text":"هاجم أميرُ الرياض دهام العماريةَ المواليةَ للدرعية وقتل أميرَها عبد الله بن علي وعقر إبِلَه، فلما بلغ ذلك الإمام محمد بن سعود جمع أهل الدرعية وعرقة، وأراد أن يرصد عودة جيش دهام من العمارية ويكمن له، وكان دهام بن دواس قد كمن في الموضعِ نفسه فالتقى الفريقان واقتتلوا قتالًا شديدًا انهزم فيه دهام، وجَدَّ أهل الدرعية في إثرِه ولكنهم فُوجئوا بخروج فرقة لابن دواس من جهة العمارية، فوقع القتل وانكسر جيشُ الدرعية."},{"id":4086,"title":"وقعة الشياب بين جيش الرياض وجيش الدرعية .","date":["العام الهجري :1159","العام الميلادي :1746"],"text":"أخذت الدرعية بثأرِها من دهام بن دواس بعد وقعةِ العمارية حينما قام الأميرُ محمد بن سعود بحملةٍ على دهام وجَرَت موقعةٌ في مكان يقال له الوشام، انهزمت فيها قوات الرياض، ودُعِيت بوقعة \"الشياب\" لأنه قتل فيها شايبان (أي شيخان مُسِنَّان) من آل شمس من أهل الرياض."},{"id":4087,"title":"وقعة العبيد بين جيش الرياض وجيش الدرعية .","date":["العام الهجري :1159","العام الميلادي :1746"],"text":"أراد الأميرُ محمد بن سعود أن يلاحِقَ دهامًا ويُلحِقَ به هزيمة منكرة، فقام بحملة أخرى على الرياض كانت نتيجتها هزيمة دهام مرة أخرى، وسميت هذه الوقعة \"وقعة العبيد\"؛ لأنَّ معظم من قُتِلَ من رجال دهام كانوا من العبيدِ."},{"id":4088,"title":"انتقام دهام بن دواس من الدرعية .","date":["العام الهجري :1159","العام الميلادي :1746"],"text":"جهَّز دهام بن دواس أميرُ الرياض جيشًا وهاجم الدرعية، ولما اندفعت نحوه قواتُها تظاهر بالتقهقر فظَنَّ جيش الدرعية أنَّ جيش دهام قد انهزم، إلا أن جيش الرياض كان قد نصب كمينًا لجيش الدرعية، فكانت الهزيمة لجيش الدرعية، وقُتِلَ فيها الأميران فيصل وسعود ابنا الإمام محمد بن سعود، وكل هذه الحروب كانت في هذه السَّنةِ، وذكر ابن بشر أنَّها كانت سنة 1160."},{"id":4089,"title":"أول غارة من الدرعية على قصر أمير الرياض .","date":["العام الهجري :1159","الشهر القمري : ربيع الأول","العام الميلادي :1746"],"text":"بعد أن جهر أميرُ الرياض دهام بن دواس بعداوتِه وانكشف غدرُه في هجومِه على المنفوحة، انتدب  الأمير محمد بن سعود جماعةً توجَّهت ليلًا إلى الرياض فدخلوها وأتوا باب القلعة التي فيها دهام، فشذبوا البابَ بالمنشار ودخلوا بيت ناصر بن معمر وتركي بن دواس، فعقروا فيهما إبلًا كثيرةً، ورموا بالرصاص دهام بن دواس وهو في عليَّة قصره ثم عادوا إلى الدرعية سالمين."},{"id":4090,"title":"غدر عثمان بن معمر أمير العيينة بأمير الدرعية وتراجعه عن نصرة الدعوة  .","date":["العام الهجري :1160","العام الميلادي :1747"],"text":"كانت وقعةُ دلقة من غير رضاء أمير العُيينة ابن معمر ولم يشاوَرْ فيها؛ لذلك لم يحضُرْها. يقول ابن غنام: \"لما رأى ابنُ معمر عودةَ الجماعة من الحرب خَشِيَ أن ينكشف نفاقُه وأن تظهر خيانته, فأرسل إلى الشيخ وإلى محمد بن سعود يستشفع إليهما, ويطلب منهما الصفحَ عن تخلُّفِه، فقبلا عذره رجاءً منهما ألا يعودَ إلى مكره, ثم قَدِمَ عليهما ومعه وجوهُ أهل حريملاء والعُيينة، وعاهدهما على الجهاد والقيام بنصرة الدين، ولو في أي مكان, فتوهَّما فيه الصدق والوفاء، فرأَّسوه ورفعوه على المسلمين وأمَّروه, وكان من أعظم ما أظهر نفاق عثمان بن معمر أنَّه أرسل إلى إبراهيم بن سليمان أمير ثرمداء وأمَرَه أن يركب إلى دهام بن دواس مع جماعتِه ويزين له الاتِّفاقَ مع عثمان والقدوم عليه إلى العُيينة على أن يُظهِرَ في أحاديثه بمجالِسِه أنه اهتدى وانضم إلى الجماعة, فقدم مع دهام مع إبراهيم بن عثمان، وكان ذلك من غير مشورة الشيخ وابن سعود، فحين رأى أهل العيينة  دهامًا وعَلِموا بما حدث شَقَّ عليهم ذلك واجتمعوا جميعًا وساروا إلى عثمان, فلما رأى حالَهم مَوَّه عليهم وقال لهم: ليس لي مرادٌ إلا الإرسال للشيخ ليحضُرَ عقد الصلح ويدخُلَ دهام في دائرة الإسلامِ، فاطمأنت نفوسُ القوم, ثم أرسل  إلى الشيخ وألحَّ عليه في القدوم، ولكن الله ألقى في رُوعِ الشيخ ما استبان به خيانةَ عثمان وغدره، فامتنع عن الذهاب فلمَّا رجع الرسول وأخبرهم بذلك عرف أهل البلد مكرَ عثمان، فحصروا ابن دواس في القصرِ وهَمُّوا أن يفتكوا به، لكن دهام هرب منهم تحت جنح الظلام، وعاد إبراهيم بن سليمان إلى ثرمداء وفارق منهج الحق, وكان هذا كلُّه قبل أن يفِدَ عثمان على الشيخ وابن سعود ويأخذ منهما العهد المجدد, ولكنه مع ذلك لم يخلِصِ النية ولم يعقِدْ على الوفاء، وسيتبين غدرُه \""},{"id":4091,"title":"نشوب موقعة الدلقة بين جيش الدرعية وجيش الرياض .","date":["العام الهجري :1160","الشهر القمري : ربيع الأول","العام الميلادي :1747"],"text":"قامت الدرعية بقيادة أميرِها محمد بن سعود بتجهيز جيشٍ قوي للهجوم على الرياض، ردًّا على هزيمة الدرعية في \"وقعة العبيد\"، إلَّا أن أحد أهالي بلدة حريملاء يقالُ له أبو شيبة من آل داود، ويدعى أبو شيبة كان قد أفشى للرياض سرَّ المعلومات التي هيأتها الدرعية لمهاجمة الرياض, فصَبَّحهم الأمير محمد بن سعود وجماعته فإذا هم مستعِدُّون والتقوا في جوف البلد فاقتتلوا قتالًا شديدًا، وحمي القتال عند باب القصر، وأصيب دهام حيث ضربه حمد بن محمد بن منيس في رأسه وجسده، حتى جاء موسى الحريصي من خلفِه فقتله فنجا دهام بعد أن أشرفَ على الموت, وكان جزاءُ الحريصي المعاقبة والتنكيل من دهام لأنَّه اهتدى بعد الوقعة وأراد الهجرةَ إلى الدرعية، فأمر دهام بقطع رجلِه وقدمِه، ثم نفاه إلى الدرعية، فلم يبرح إلَّا ثلاثة أيام مات بعدها."},{"id":4092,"title":"وفاة الملك نادر شاه مؤسسة أسرة الأفشار في إيران .","date":["العام الهجري :1160","الشهر القمري : جمادى الآخرة","العام الميلادي :1747"],"text":"هو الملك نادر شاه الأفشار التركماني، ويعرف كذلك باسم \"نادر قـُلي بگ\" ولد نادر شاه في محرم 1100هـ/ 22 نوفمبر 1688م وجلس على العرش في شوال 1148هـ وهو مؤسِّس الأسرة الأفشارية التي حكمت إيران. كانت قبيلةُ أفشار هي إحدى القبائل التركمانية التي فرَّت من وجه المغول تاركةً تركستان، واستقرت في أذربيجان، فأرسل الشاه إسماعيل الصفوي قِسمًا من هذه القبيلة إلى الجزء الشمالي من خراسان وأسكنهم فيها بالقرب من منبع نهر كوبكان. كان أول أمر نادر شاه من قطَّاع الطرق, ثم جمع رجاله ورأى من مصلحته العمل كقائد عسكر لطهماسب الثاني آخر شاهات الدولة الصفوية, كان لنادر شاه الفضلُ في حركة المقاومة العسكرية لتحرير إيران من الاحتلال الأفغاني، وبعد نجاحه أخذ اسمُه يصعد في إيران حتى انتهى به الأمر إلى أن نصَّب نفسه شاهًا لإيران بعد أن عزل طهماسب الثاني, وأعلن نهايةَ الدولة الصفوية في إيران. عُرف نادر شاه بأنه محارب عسكري مشهور بحملاته العسكرية, ويعدُّ واحدًا من أكبر الغزاة الفاتحين في تاريخ إيران الحديث، حيث قام بعدة حملات ناجحة في الهند وأفغانستان وضِد الدولة العثمانية وآسيا الوسطى، وحَسَبت له روسيا حسابه كقوَّة فتية في المنطقة، وتحالفت معه ضد العثمانيين. فلما زادت قسوةُ نادر شاه ورأى الناس ظلمَه وتعسُّفَه، خافه الأمراء فتآمروا على قتلِه، وفي جملتهم بعضُ القواد من الأفشار، وكان منهم رئيسُ الحرس الذي أعانهم فدخلوا عليه وهو نائم فقتلوه في سريره ليلة 11 من جمادى الثانية, ثم أرسلوا وراءَ علي شاه ابن أخي نادر شاه فحكَّموه على إيران، لكنه كان ضعيفًا خاملًا، فجاء أخوه إبراهيم الذي حكم العراق باسمه وعزله، وكان علي شاه قد قَتَل كل آل نادر عدا حفيدًا له اسمه شاه رخ ميرزا، وأما إبراهيم فلم يدُم طويلًا حتى قتله حرَّاسه وولَّوا مكانه شاه رخ الصغير، لكن قائد الجيوش ميرزا محمد أسَرَه وسمل عينيه وأعيد بعد فترة، حيث جاء علي خان رئيس جيش إيران فأخرجه من سجنه وأعاده، لكنه رضي ببلاد خراسان وحسبُ, وصارت إيران في قبضة كريم خان زند، وأخذت الولايات تستقِلُّ واحدة تلو الأخرى."},{"id":4093,"title":"حصول وقعة البنية ووقعة الخريزة بين جيش الدرعية وجيش الرياض .","date":["العام الهجري :1161","العام الميلادي :1747"],"text":"قام عثمانُ بن معمر أمير العيينة بمعاهدة الأمير محمد بن سعود على الحربِ معه، فقاد جيشُ الدرعية ضِدَّ جيش الرياض، وانهزم بعد قتالٍ شديد قُتِل فيه أناس كثيرون، ثم حدثت وقعة أخرى سار فيها عبد العزيز بن محمد بن سعود بأهل الدرعية وضرما، وتولى عثمان بن معمر قيادةَ قوات العُيينة وحريملاء، كما أنه كان الأمير عليهم جميعًا واشتبك مع جيش الرياض في مكان يدعى \"الخريزة\" قرب الرياض، وكانت النتيجة متكافئة، وتلت ذلك معاركُ كثيرة بين الدرعية والرياض، كان أسلوب الكرِّ والفر ونصْب الكمائن هو الفَنَّ القتاليَّ فيها."},{"id":4094,"title":"قيام دولة أمراء أفغانستان .","date":["العام الهجري :1161","العام الميلادي :1747"],"text":"برز أحمد خان الدوراني الذي كان يقود الأفغان والأوزبك في جيش نادر شاه، وعندما قُتل نادر شاه عام 1160هـ في شروان أسرعت الفرقة الأفغانية التي كانت معه عائدةً إلى بلادها واستقَرَّت في قندهار، ونادت بقائدها أحمد خان الذي كان قد تقاتل مع بقية القادة وهُزِمَ فانسحب إلى قندهار أيضًا، وأسس فيها مملكة الأفغان وعاصمتها قندهار، وبدأ أحمد خان شاه يوسِّع دولته؛ فقد ضم إليها كشمير ولاهور والملتان، وقاتل السيخ والهندوك."},{"id":4095,"title":"وفاة العلامة إسماعيل العجلوني .","date":["العام الهجري :1162","الشهر القمري : محرم","العام الميلادي :1749"],"text":"هو الشيخ العلامةُ الإمام العالمُ الهُمام الحجَّة الرُّحلة العمدة: أبو الفداء إسماعيل بن محمد بن عبد الهادي بن عبد الغني، الشهير بالجراحي- نسبة إلى أبي عبيدة بن الجراح- العجلوني الدمشقي، محدِّث الشام في أيامه. وُلِد بعجلون (بالأردن) سنة 1087 نشأ بدمشق وفيها توفي. كان عالِمًا بارعًا صالحًا مفيدًا محدِّثًا مبجَّلًا قدوة سندًا خاشعًا. له يدٌ في العلوم لا سيما الحديث والعربية، وكان شافعيًّا صوفيًّا، له مصنفات كثيرة، أشهرها: كشف الخفاء ومزيل الإلباس عما اشتهر من الأحاديث, وله عقد اللآلئ والزبرجد في ترجمة الإمام الجليل أحمد، وله شرح على البخاري، وغيرها."},{"id":4096,"title":"وقعة البطحاء بين جيش الدرعية وجيش الرياض .","date":["العام الهجري :1163","العام الميلادي :1749"],"text":"جرت وقعة البطحاء في الرياض، وذلك أن محمد بن سعود سار بجنودِه إلى الرياض ليلًا ووصل المكان المعروف بباب المروة ومعه رجال مشهورون بالشجاعة، منهم علي بن عيسى الدروع، وسليمان بن موسى الباهلي، ومحمد بن حسن الهلالي، وعلي بن عثمان بن ريس، وعبد الله بن سليمان الهلالي، وإبراهيم الحر، فخرج إليهم أهلُ الرياض ووقع قتال شديد، قُتل فيه من أهل الرياض سبعةُ رجال, واثنان من أهل الدرعية."},{"id":4097,"title":"أهل الدرعية بقيادة عبد العزيز بن محمد يغزون ثرمداء .","date":["العام الهجري :1163","العام الميلادي :1749"],"text":"سارت قوةٌ من أهل الدرعية وأميرُهم عبد العزيز بن محمد إلى ثرمداء، وكان النذيرُ قد جاء أهل ثرمداء بذلك، فاستعانوا بأهل وثيثيا ومرات، فالتقى بهم جيش الدرعية وهم مستعدون للقتال في موضع قريب من ثرمداء يسمى الوطية، وكان جيش الدرعية قد أعدوا كمينًا، فلما نشب القتال خرج عليهم الكمين فولَّوا مدبرين وقتل منهم خمسة وعشرون، منهم علي بن زامل أمير وثيثيا"},{"id":4098,"title":"وفاة عثمان بن معمر أمير العيينة .","date":["العام الهجري :1163","الشهر القمري : رجب","العام الميلادي :1750"],"text":"هو عثمانُ بن حمد بن عبد الله بن محمد بن حمد بن عبد الله بن محمد بن حمد بن حسن بن طوق بن سيف آل معمر، من العناقر، من بني سعد من بني تميم: أمير العيينة. تولى إمارتها خلفًا لأخيه محمد, وهو جدُّ سعود الكبير بن عبد العزيز بن محمد ثالث حكام الدولة السعودية الأولى. كان ابن معمر آوى الشيخ محمد بن عبد الوهاب في العيينة ووعد بنصره بعد خروجه من حريملاء، لكنه طرد  الشيخَ من العيينة بعد أن تلقَّى ابن معمر  تهديدًا من قائد الأحساء بشأن الشيخ يأمره أن يقتله، وقال: إن المطوع الذي عندكم بلغنا عنه كذا وكذا، فإما أن تقتله، وإما أن نقطع عنك خراجَك الذي عندنا. فقال للشيخ: إن هذا الأمير كتب إلينا وإنه لا يحسُنُ منا أن نقتلك، وإنا نخاف هذا الأمير ولا نستطيع محاربته، فإذا رأيتَ أن تخرج عنا فعلتَ، فنصحه الشيخ ورغَّبه في نصرة لا إله إلا الله، وأن من تمسك بهذا الدين ونصره وصدق في ذلك، نصره الله وأيَّده وولاه على بلاد أعدائه، فإن صبرتَ واستقمتَ وقبِلتَ هذا الخير، فأبشر فسينصرك الله ويحميك من هذا البدوي وغيره، وسوف يولِّيك الله بلاده وعشيرته, فقال: أيها الشيخ إنا لا نستطيعُ محاربته، ولا صبْرَ لنا على مخالفته. فخرج الشيخ عنده وتحوَّل من العيينة إلى الدرعية، ثم لَمَّا قَوِيَ شأن الدعوة وقَوِيت بسببها إمارة الدرعية، اضطر ابن معمر أن يدخل تحتَ لواء حكام الدرعية، وقد ظهرت منه أمور تدلُّ على عدم صدقه، ونفاقِه، حتى إنه تآمر مع دهام بن دواس على المكر بالشيخ محمد بن عبد الوهاب, ولما كثرت شكايةُ أهل العيينة من تآمرِه على الدعوة اتفقوا مع الشيخ المجدد على التخلُّص منه، يقول ابن غنام: \"لما تزايد شرُّ عثمان بن معمر على أهل التوحيد وظهر بغضُه لهم وموالاته لأهل الباطل، وتبيَّن الشيخ صدق ما كان يُروى عنه، وجاءه أهل البلاد كافة وشكوا إليه خشيتهم من غدره بالمسلمين، قال الشيخ حينئذ لمن وفد عليه من أهل العيينة: أريدُ منكم البيعةَ على دين الله ورسولِه، وعلى موالاة من والاه ومعاداة من حاربه وعاداه، ولو أنه أميركم عثمان, فأعطَوه على ذلك الأيمان وأجمعوا على البيعة, فملئ قلب عثمان من ذلك رعبًا, وزاد ما فيه من الحقد, وزيَّن له الشيطان أن يفتك بالمسلمين, ويُجليَهم إلى أقصى البلدان، فأرسل إلى ابن سويط وإبراهيم بن سلمان رئيس ثرمداء... يدعوهما إلى المجيء عنده لينفذ ما عزم عليه من الإيقاع بالمسلمين, فلما تحقق أهلُ الإسلام ذلك تعاهد على قتله نفرٌ، منهم حمد بن راشد, وإبراهيم بن زيد, فلما انفضَّت صلاة الجمعة قتلوه في مصلَّاه بالمسجد, فلما عَلِمَ بذلك الشيخ محمد بن عبد الوهاب عَجِل بالمسير إلى العيينة خشية اختلاف الناس وتنازُعِهم، فقدم عليهم في اليوم الثالث بعد مقتلِه، فهدأت النفوس فتجاذبوا عنان الرأي والمشورة فيمن يتولى الرئاسة والإمارة بعده، وأراد أهل التوحيد ألَّا يولى عليهم أحدٌ من آل معمر، فأبى الشيخ ووضَّح لهم طريقَ الصواب بالحجَّة ولمقنعة، وأمَّر عليهم مشاري بن معمر\""},{"id":4099,"title":"غزو منطقة سدير لضمها تحت لواء دولة الدرعية الناشئة .","date":["العام الهجري :1164","العام الميلادي :1750"],"text":"قامت دولةُ الدرعية الناشئة بعدة غزوات ضد بلدان منطقة سدير التي رفضت الدعوة، ورفضت الانضواءَ تحت لواء الدولة الناشئة. والتي بدأت غزواتُها للمنطقة في هذه السنة، واستمرت حتى عام 1177هـ. وفي هذه الفترة استطاعت نشرَ مبادئ الدعوة في كلٍّ من الزلفي وجلاجل والحوطة والجنوبية والروضة والتويم والغاط والداخلة والعودة وحرمة، وغيرها من المدن والبلدان، في هذه المنطقة."},{"id":4100,"title":"نقض أهل حريملاء عهدهم مع دولة الدرعية .","date":["العام الهجري :1165","العام الميلادي :1751"],"text":"بعد أن أعلنت حريملاء خضوعَها لدولة الدرعية في أوَّلِ الأمر، ثم قام بعض أهلها في هذه السنة بتحريضٍ من قاضيها سليمان بن عبد الوهاب شقيق الشيخ محمد بن عبد الوهاب الذي كان معارضًا لآراء أخيه، قاموا بنقضِ عَهدِهم مع الدعوة والدولة، وأخرجوا من البلدة من لم يستجِبْ دعواهم، ومن بينهم الأمير محمد بن عبد الله بن مبارك، وأخوه عثمان، فقصد هؤلاء المطرودون بلدة الدرعية ونزلوا ضيوفًا على أميرها، ولما خَشِي المتمردون في حريملاء من ردِّ الدرعية عليهم، أرسلوا وفدًا لاسترضاء المطرودين واسترجاعهم إلى بلدتهم. فلما عادوا إليها إذا بقبيلة آل راشد من أهل حريملاء تهجم على هؤلاء العائدين وتفتكُ ببعضِهم، فقتلوا الأمير محمد بن عبد الله وثمانية من أتباعه، وكان من الناجين مبارك بن عدوان الذي فرَّ وطلب النجدة من الدرعية."},{"id":4101,"title":"عدوان أهل سدير والوشم على أتباع دعوة التوحيد .","date":["العام الهجري :1165","العام الميلادي :1751"],"text":"اجتمع أهلُ سدير والوشم ومعهم آل ظفير، واتجهوا إلى رغبة، وكان أهلها قد اهتَدَوا إلى التوحيد, فحصرتهم تلك الجموعُ في البلد أيامًا، فجنح بعض أهلها إلى الضَّلالِ فأدخلوا تلك الأجناد فنَهَبوا  جميع الأموال، ولكِنَّ الله حقن دماء المسلمين, ثم اتجهت تلك الجموع ومعهم جلوية ضرمى إلى ضرمى- الذين دخل أهلها في طاعة الدرعية- فحصَروا أهلها أيامًا ونصبوا السلالم على أسوارها، وصعد منهم السور نحو ثلاثين رجلًا قُتلوا جميعًا, ثم رجعوا بعد ذلك خائبين."},{"id":4102,"title":"رجوع أهل منفوحة عن تأييد دعوة التوحيد متابعتها .","date":["العام الهجري :1166","العام الميلادي :1752"],"text":"رجع أهلُ المنفوحة عن تأييد دعوة التوحيد، ونبذوا عهدَهم مع الدرعية وطردوا إمامَهم محمد بن صالح, وخرج معه سبعون رجلًا من المؤيدين لها, ثم تلاحق الناسُ بعد ذلك فارِّين بدينهم."},{"id":4103,"title":"وفاة أسعد أفندي  شيخ الإسلام في الدولة العثمانية .","date":["العام الهجري :1166","الشهر القمري : شوال","العام الميلادي :1753"],"text":"هو شيخُ الإسلام أسعد أفندي بن أبي إسحاق إسماعيل أفندي، رئيسُ المشيخة في الدولة العثمانية. وكان قد تولَّى المشيخة في رجب 1161هـ، ولكنَّه لم يستمر في منصبه طويلًا. وللشيخ مؤلَّفات وبحوث في اللغة التركية، من أشهرها: معجم تركي بعنوان: \"لهجة اللغات\"."},{"id":4104,"title":"موقف الشيخ محمد بن عبد الوهاب وكبار أنصاره من خصوم الدعوة .","date":["العام الهجري :1167","العام الميلادي :1753"],"text":"اجتمع في الدرعية الشيخ محمد بن عبد الوهاب والإمام محمد بن سعود، بالإضافة إلى كبار أنصار الدعوة الذين قدموا من مختلف البلدان للتباحث في شؤون الدعوة والمواقف اللازم اتخاذها ضد أعدائها، وكان دهام بن دواس قد تضجَّر من الحرب مع آل سعود، فلما سمع بهذا التجمع مال إلى المهادنة، وطلب من الشيخ محمد بن عبد الوهاب والإمام محمد بن سعود عقدَ صُلحٍ بينه وبين الدرعية، وتعهد باعتناق مبادئ الدعوة السلفية، إلَّا أنه نكث هذا العهد في العام التالي سنة 1168 هـ، وسانده على ذلك محمد بن فارس رئيس منفوحة، وهكذا تجددت الاشتباكاتُ بين الدرعية والرياض."},{"id":4105,"title":"وفاة السلطان العثماني محمود الأول وقيام أخيه عثمان الثالث خلفًا له .","date":["العام الهجري :1168","الشهر القمري : صفر","العام الميلادي :1754"],"text":"هو الخليفةُ العثماني محمود الأول ابن السلطان مصطفى الثاني ابن السلطان محمد الرابع بن إبراهيم الأول بن أحمد الأول بن محمد الثالث بن مراد الثالث بن سليم الثاني بن سليمان القانوني بن سليم الأول. وُلِدَ في 4 محرم سنة 1108هـ 3 أغسطس سنة 1696 تولى السلطان محمود السلطنة بعد ثورة على السلطان أحمد الثالث الذي كان يميل إلى مصالحة الدولة الصفوية, فثار عليه الانكشارية في  15 ربيع الأول 1143 فقتلوا الصدرَ الأعظم والمفتي وقبوادان باشا أميرال الأساطيل البحرية؛ بحجة أنَّهم مائلون لمسالمة العجم، ثم أعلنوا عزل السلطان أحمد ونادوا بابن أخيه محمود الأول خليفةً للمسلمين وأميرًا للمؤمنين، فأذعن السلطان أحمد الثالث وتنازل عن الملك بدون معارضة, ولما تولى السلطان محمود لم يكن له إلا الاسم فقط، وكان النفوذ لبطرونا خليل, يولِّي من يشاء ويعزل من يشاء، حتى عِيلَ صَبرُ السلطان محمود من استبداده فتخلص من الانكشارية لتعدِّيهم وتجاوزهم حدودَهم, وفي عهد السلطان محمود استأنفت الدولة الحربَ مع مملكة الفرس، وتغلبت الجيوش العثمانية على جنود الشاه طهماسب في عدة وقائع انتهت بصلح بين الدولتين، الذي عارضه نادر شاه أكبر ولاة الدولة الصفوية، والذي قام بعد ذلك بعزل الشاه طهماسب، ثم أنهى حكم الدولة الصفوية في بلاد فارس، وتولى هو عرش إيران، ودخل في صراع مع الدولة العثمانية. ولحُسن حظِّ الدولة في عهد السلطان محمود أن تقلَّدَ منصب الصدارة رجل محنك اشتهر بحسن السياسة وسمو الإدراك هو الحاج محمد باشا الذي لم يغفل طرفة عين عن جمع الجيوش وتجهيز المعدات، حتى تمكَّن من إيقاف تقدُّم الروس في بلدان الدولة العلية, وانتصرت جيوشُها على النمسا التي طلبت الصلحَ بواسطة سفير فرنسا. توفِّي السلطان محمود الأول يوم الجمعة 27 صفر عن عُمرِ ستين سنة مأسوفًا عليه من جميع العثمانيين؛ لاتصافه بالعدل والحِلمِ ومَيلِه للمساواة بين جميع رعاياه بدون نظرٍ لفئة دون أخرى، وكانت مدة حكمه 25 سنة، وفي أيامه السعيدة اتسع نطاقُ الدولة بآسيا وأوروبا، ثم قام بعده أخوه عثمان الثالث خلفًا له، وبويع في جامعِ أبي أيوب الأنصاري، وهنَّأه سفراء أوروبا."},{"id":4106,"title":"السلطان العثماني عثمان الثالث يضيق الخناق على الذميين .","date":["العام الهجري :1168","الشهر القمري : صفر","العام الميلادي :1754"],"text":"كان من أوائل ما قام به السلطان عثمان الثالث بعد توليه السلطنةَ مَنْعُ كلِّ ما يخالف الشرعَ، سواء كان ما يفعله النصارى واليهود أو غيرُهم، فشَدَّد بذلك الخناقَ على أهل الذمَّةِ الذين كانوا قد توسَّعوا أكثر من حقوقِهم، وخاصة تحت اسم الحماية التي كانت عليهم من قِبَل دولهم النصرانية الأوربية تحت ظلِّ البابوية. كما اهتم بالإصلاحاتِ الداخلية، وأُسِّسَت في عهده مطبعة, وقمَعَ كثيرًا من الثورات الداخلية."},{"id":4107,"title":"انضمام بلدة حريملاء إلى دعوة الشيخ محمد بن عبد الوهاب .","date":["العام الهجري :1168","الشهر القمري : جمادى الأولى","العام الميلادي :1755"],"text":"سار الأميرُ عبد العزيز بن محمد في نحو 800 رجل ومعهم من الخيل 20 فرسًا، فأناخ شرقيَّ البلد ليلًا، وكمن في موضعين، فصار عبد العزيز ومعه عِدَّةٌ من الشجعان في شعيب عوجا، وكمن مبارك بن عدوان مع 200 رجل في الجزيع، فلما أصبحوا شنُّوا الغارةَ، فخرج أهل حريملاء واشتد القتالُ حتى فرَّ أهل حريملاء في الشعاب والجبال بعد أن قُتِلَ منهم 100 رجل، وغنم جيش الدرعية منهم كثيرًا من الذخائر والأموال، وقُتل من جيش الدرعية سبعةُ رجال, ودخلوا البلدةَ وأعطى الأميرُ عبد العزيز بقيةَ الناس الأمان, وفرَّ في هذه الواقعة قاضي البلدة الشيخُ سليمان بن عبد الوهاب أخو الشيخ محمد إلى سدير، وولى الأميرُ عبدُ العزيز مباركَ بن عدوان أميرًا على حريملاء"},{"id":4108,"title":"نقض دهام بن دواس أمير الرياض العهد مع الدرعية .","date":["العام الهجري :1168","الشهر القمري : شعبان","العام الميلادي :1755"],"text":"نقض دهام بن دواس عهدَه مع الأمير محمد بن سعود أمير الدرعية، فعدا على أهل أبي الكباش، ثم رجع فلمَّا تبيَّنَ منه أهلُ الدِّينِ في الرياض المكرَ والغدرَ تركوا أموالَهم وبلدهم وهاجروا إلى منفوحة، ثم هاجروا إلى الدرعية، لما تبين لهم أن رئيس المنفوحة محمد بن فارس قد انضمَّ مع دهام بن دواس في نقضِ العَهدِ."},{"id":4109,"title":"حدوث موقعة الدار بين دهام بن دواس وحلفائه وجيش الدرعية .","date":["العام الهجري :1168","الشهر القمري : ذي القعدة","العام الميلادي :1755"],"text":"تجهَّز دهام بن دواس لمحاربة الدرعية الحربَ الثانية، فاجتمع معه محمد بن فارس رئيس المنفوحة وإبراهيم بن سليمان رئيس ثرمداء، ومعهم أناسٌ مِن أهل سدير وأهل ثادق وجلوية حريملاء، واتجهوا إلى بلدة حريملاء فوصلوها ليلًا، ودخلوا محلة بأعلى البلد تسمَّى الحسيان، وكان الناس وأغلب الحرسِ نائمين، فلم يشعر بهم أحدٌ حتى ملكوا المحلَّةَ وبساتينها, فلما علم أميرُ البلدة مبارك بن عدوان  نهض مع جماعتِه في الليل وقاتلوهم، إلا أنهم لم يستطيعوا فرجَعوا, وفي الصباح شدَّ عليهم ابنُ عدوان وحمي بينهم القتالُ، فخرج أكثر المعتدين هاربين، وبقيت طائفة منهم محصورين في البيوت نحو خمسة أيام- أغلبهم من جلوية حريملاء- وكانوا يرمون أهل البلد، فقَتَلوا منهم 18 رجلًا، ثم تسوَّر رجال ابن عدوان عليهم الدارَ وشَدُّوا عليهم حتى قتلوهم وأخذوا ما معهم من السلاحِ، وكان جملةُ من قُتل من هؤلاء الأحزاب في هذه الوقعة 60 رجلًا. وكان ابن عدوان قد دعا المحصورين إلى التسليم، وأعطاهم الأمان فخرج منهم 10 رجال فقَتَل منهم ستةً، ولم يكن الشيخُ محمد وابن سعود يعلمان بذلك، فلما علما أنكرا ما فعل ونَقَموا عليه لِغَدرِه بالعَشرةِ بعد أن أعطاهم الأمانَ."},{"id":4110,"title":"استقرار أسرة الصباح في حكم الكويت وتولي الشيخ صباح الأول حكم البلاد .","date":["العام الهجري :1169","العام الميلادي :1755"],"text":"سعى المستوطِنون الأولون آلُ الصباح من العتوب في الكويت، إلى تأمين مركزِهم في إمارتهم الناشئة، وذلك بالاعترافِ بشيء من الولاء للدولة العثمانية. فأوفدوا زعيمَهم الأول، صباح بن جابر، إلى الوالي العثماني في بغداد؛ ليطلب منه تأييدَ الدولة العثمانية لهم، وإقرارها لاستقرارهم وأمنهم، فضلًا عن إظهارِ رغبتِهم في العيش في سلامٍ، وتعهُّدهم بحفظ الأمن والاستقرار في المنطقة، وقد نجح زعيمُ أُسرة الصباح في مسعاه وبذلك اعترفت الكويت بنوعٍ مِن التبعية الدينية للدولة العثمانية من دون تدخُّل استانبول في شؤونها الداخلية. فتجنَّبت الأخطارَ التي كان يمكِنُ أن تأتيها من جانب الدولة العثمانية، بل استغَلَّ شيوخها في بعض الفترات علاقتَهم بالدولة العثمانية؛ لتحقيق مصالح كويتية خاصة, ولقد كانت الرابطةُ الدينيةُ هي أساس تبعية الكويت الاسمية للدولة العثمانية خلال تلك الفترة؛ لكونها دولة الخلافة الإسلامية؛ إذ كانت الرابطةُ الدينية هي المصدرَ الأساسي لاكتساب الشرعية. ولا شكَّ في أن نمط تبعية الكويت للدولة العثمانية كان مختلفًا عن أنماط التبعية لسائر ولايات الدولة العثمانية؛ فقد كان هناك: نمط التبعية الفعلية، ونمط السيادة القانونية، والنمط الأقرب إلى علاقة التحالف. وقد حمل الكويتَ على الإقرار بالتبعية الاسمية للدولة العثمانية عوامِلُ عِدَّةٌ أبرزها: سعيُ أهل الكويت إلى تحقيق نوع من التوازن في علاقاتهم بين الدولة العثمانية وبني خالد الذين كانوا يسيطرون على الأحساء والقطيف؛ تفاديًا للوقوع تحت سيطرة أي من القوَّتين. حِرصُ حكام الكويت على تدعيم شرعية كيانهم السياسي بالارتباط بالمصدر الديني الذي تجسده دولة الخلافة. اطمئنانُ شيوخ الكويت خلال هذه الفترة إلى أن التبعيةَ الاسمية للدولة العثمانية لن تتحوَّل إلى تبعية فعلية نتيجة حالة الفوضى والاضطراب التي كان يمر بها العراق العثماني؛ بسب ظروف سياسية."},{"id":4111,"title":"انضمام بلدة القويعية إلى دعوة الشيخ محمد بن عبد الوهاب .","date":["العام الهجري :1169","العام الميلادي :1755"],"text":"انضمَّت بلدة القويعية في منطقة الوشم إلى دعوة الشيخ محمد بن عبد الوهاب، وأعلن أهلُها الطاعةَ وبايعوا الشيخَ محمد بن عبد الوهاب والإمامَ محمد بن سعود, والتزموا بالسَّمع والطاعة، وصَدَقوا ووفَوا فلم ينخلعوا منها ولم يَنقُضوا عهدهم, وكان أول مَن وفد منهم على الشيخ والأميرِ: ناصِرُ بن جماز العريفي وسعود بن حمد."},{"id":4112,"title":"السلطان عثمان الثالث يقتل الصدر الأعظم بعد أن تبين له ظلمه للرعية .","date":["العام الهجري :1169","الشهر القمري : محرم","العام الميلادي :1755"],"text":"كان السلطان عثمان الثالث بعد توليه الخلافة قد عيَّن في منصب الصدارة العظمى نشانجي علي باشا بدلًا من محمد سعيد باشا, فاعتمد علي باشا هذا على ميلِ السلطان إليه, فسار في طريقٍ غيرِ حميدٍ، حتى أهاج ضِدَّه الأهالي أجمعين، ولكون السلطان كان من عادته المرور ليلًا في الشوارع والأزقة متنكرًا لتفَقُّدِ أحوال الرعية والوقوف على حقيقة أحوالِهم، سمع أثناء تَجوالِه بما يرتكبه وزيرُه من أنواع المظالم والمغارم، وبعد أن تحقَّق ما نُسِب إليه بنفسِه، أمر بقَتلِه جزاءً له, ثم وضع رأسه في صحنٍ من الفضة على باب السراي عبرةً لغيره. قُتِلَ الوزيرُ  في 16 محرم, وعُيِّن مكانَه مصطفى باشا."},{"id":4113,"title":"هجوم أهل الوشم وسدير على شقراء  .","date":["العام الهجري :1170","العام الميلادي :1756"],"text":"تجمَّع أهلُ الوشم وسدير في بلدة القرين في ناحية الوشم يريدون غزوَ أهل شقراء بعد أن انضمَّ أهلها للدعوة, فبَقُوا في القرائن ثلاثة أيام وهم يناوشون أهل شقراء الحربَ، فلما علم بذلك الأمير محمد بن سعود- وكان أهل شقراء من السابقين في متابعةِ دعوة الشيخ محمد بن عبد الوهاب- طلب منهم أن يخرُجوا إليهم ويشاغلوهم حتى يأتيَهم المددُ، ثم أرسل ابنَه الأمير عبد العزيز مع جنوده، الذي تمكن من هزيمة أهل الوشم وسدير، واضطرهم إلى الهروب إلى بلدة القرائن والاحتماء بها بعد أن قتلَ منهم 15 رجلًا، ثمَّ حصرهم في القرائن 20 يومًا حتى أيقنوا الهلاكَ، فخرجوا منها هاربين."},{"id":4114,"title":"انضمام بلدة ثادق إلى دعوة الشيخ محمد بن عبد الوهاب .","date":["العام الهجري :1170","العام الميلادي :1756"],"text":"غزا الأمير عبد العزيز بن محمد بقوَّاته أهل ثادق فنازلوهم وقطعوا شيئًا من نخلهم وتراموا بالرصاص من بعيدٍ، حتى قتلوا منهم 8 رجال وحاصروهم زمنًا، فطلب أهل ثادق المصالحةَ وأقبلوا على دعوة الشيخ محمد بن عبد الوهاب، ووفدوا عليه في الدرعية وأمَّرَ عليهم دخيلَ بن سويلم، وأرسل معهم أحمد بن سويلم يعلِّمُهم التوحيدَ والأحكام."},{"id":4115,"title":"عزل مبارك بن عدوان عن إمارة حريملاء ثم تمرده عن الطاعة .","date":["العام الهجري :1171","العام الميلادي :1757"],"text":"عزل الشيخُ محمد بن عبد الوهاب والأميرُ ابنُ سعود مباركَ بنَ عدوان عن إمارةِ حريملاء؛ وذلك لأنهما تخوَّفا على أهل حريملاء منه لأمورٍ صدرت ونُسِبت إليه وأمَّرا مكانه أحمد بن ناصر, فاستأذن ابن عدوان من الشيخ ومن الأمير أن يذهَبَ إلى عُيينة ثم يعود اليهما في الدرعية، فأذنا له فلما خرج متظاهِرًا بالذهاب إلى العيينة التقى في الطريق بأناسٍ من أهل حريملاء فأغراهم بالرجوعِ عن طاعة الشيخ والأمير، فأطاعه فريقٌ منهم، ثم سار يريد الاستيلاءَ على حريملاء، فاستولى على قصرِ الإمارة، ثم دعا أهل البلد لنصرتِه ومعونته فلم يجِبْه أحدٌ فولى هاربًا."},{"id":4116,"title":"وفاة السلطان العثماني عثمان الثالث وتولية مصطفى الثالث خلفًا له .","date":["العام الهجري :1171","الشهر القمري : صفر","العام الميلادي :1757"],"text":"هو السلطانُ العثماني عثمانُ الثالث ابن السلطان مصطفى الثاني بن محمد الرابع بن إبراهيم الأول بن أحمد الأول بن محمد الثالث بن مراد الثالث بن سليم الثاني بن سليمان القانوني بن سليم الأول. وُلِدَ السلطان عثمان سنة 1110هـ سنة 1696م وبعد أن تقلَّدَ السيف في جامعِ أبي أيوب الأنصاري على حَسَبِ العادة القديمة وأبقى كبار الموظفين في وظائفهم عيَّن في منصب الصدارة العظمى نشانجي علي باشا بدلَ محمد سعيد باشا ثم أمرَ بقَتلِه بعد أن تبين له أنه كان يرتكِبُ أنواعًا من المظالم والمغارم في حَقِّ الرعية، وعين مكانه مصطفى باشا، ثمَّ عزله وعيَّن مكانه محمد راغب باشا الشهير، وكان من فحول الرجال الذين تقلَّبوا في المناصب على اختلافها. توفِّي السلطان عثمان في السادس عشر من صفر بعد أن حكم مدة ثلاث سنين قضى فيها على الثورات والانتفاضات التي قامت في أنحاء الدولة، وخاصة ثورات الأكراد، ويُذكَر عنه أنه كان يتحسَّس أحوال الرعية ليلًا متنكِّرًا، وتولى بعده ابنُ عمه مصطفى الثالث بن أحمد الثالث."},{"id":4117,"title":"تولي محمد الأول بن عبد الله ملك العلويين في المغرب خلفا لأبيه  .","date":["العام الهجري :1171","الشهر القمري : صفر","العام الميلادي :1757"],"text":"تولى محمَّدٌ الأول بن عبد الله بن إسماعيل ملك العلويين في المغربِ الأقصى الفرعَ الحسني خلفًا لأبيه عبد الله, في 20 صفر, فجدَّد للدولة قوَّتَها بعد تلاشيها، وأحياها بعد خمود جمرتها وتمزيقِ حواشيها، بحُسن سيرتِه ويُمن نقيبتِه."},{"id":4118,"title":"هجوم زعيم بني خالد مع حلفائه على حريملاء والجبيلة .","date":["العام الهجري :1172","العام الميلادي :1758"],"text":"عزم الحاكِمُ الخالدي عريعر بن دجين وحلفاؤه الهجومَ على الدرعية والقضاء على دعوة الشيخ محمد بن عبد الوهاب التي كانت تحت حمايةِ محمد بن سعود أميرِ الدرعية. فأمر الشيخُ والأمير جميعَ أتباعِهم في بلدان نجدٍ بالاستعداد والتحصُّن، وبنى عبد العزيز بن محمد على الدرعية سورينِ عليهما البروج, فلمَّا بدأ عريعر بالخروجِ ومعه أهل الأحساءِ وبنو خالد وأهل سدير والوشم والرياض والخرج، ويعاوِنُهم في ذلك كلُّ من ناصب الدَّعوةَ أو دولةَ الدرعية العداءَ، فأناخ أهلُ الوشم وسدير والمحمل ورئيسُهم ابن عدوان على حريملاء، وأخذوا يقاتلون أهلها ثلاثة أيام، فقُتِل منهم رجال ولم ينالوا أيَّ نصر, فرحلوا عنها وطلبوا من عريعر أن يمدَّهم بجيوش من عنده فأمَدَّهم بآل عبيد الله من بني خالد وبفريقٍ من عنزة ورئيسهم ابن هذال، فأناخوا جميعًا على حريملاء مرة أخرى وأحاطوا بها ودخَلَها منهم ثلاثُ فِرَقٍ، فخرج إليهم أهل البلد وقاتلوهم وطردوهم مهزومين، وقتلوا منهم عشرة رجالٍ، وأصابوا كثيرين بجراحٍ، ولحقوهم بعد هذا النصر إلى حيث كانوا مُنيخين، فلما رأوهم مُقبلين عليهم ولَّوا على الأعقاب مُدبرين إلى أن وصلوا إلى عريعر بن دجين وجماعته, ثم هجموا جميعًا على الجبيلة فجاء المددُ من الدرعية للجبيلة، وأحاطوا بالمتحالفين حتى ألجؤوهم إلى الفرار بعد أن قتلوا منهم 60 رجلًا، بينما قُتل من أهل الجبيلة والمدد 10 رجال فقط."},{"id":4119,"title":"انضمام ثرمداء إلى دعوة الشيخ محمد بن عبد الوهاب .","date":["العام الهجري :1173","العام الميلادي :1759"],"text":"انضمَّت ثرمداء في منطقة الوشم إلى دعوة الشيخ محمد بن عبد الوهاب، وأصبحت خاضعةً للدرعية، وذلك بعد أن قاد الأمير عبد العزيز بن محمد عِدَّةَ حملات عسكرية ضِدَّها بداية من عام 1161هـ."},{"id":4120,"title":"عزل أمير العيينة مشاري بن معمر .","date":["العام الهجري :1173","العام الميلادي :1759"],"text":"عزل الشيخُ محمد بن عبد الوهاب والأميرُ ابن سعود مشاري بنَ معمر عن إمارة العُيينة؛ لأمور كثيرة ثبتت عليه، وأمَّر عليها سلطان بن محيسن المعمري، وأمَرَ الشيخ بهدم قصر آلِ معمر."},{"id":4121,"title":"انضمام بلدتي الفرعة وأشيقر إلى دعوة الشيخ محمد بن عبد الوهاب .","date":["العام الهجري :1175","العام الميلادي :1761"],"text":"سار الأميرُ عبد العزيز ومَن معه إلى بلدة الفرعة في منطقة الوشم، فخرج أهلُها لقتال عبد العزيز، فلما ظهر عليهم كمينٌ أعده عبد العزيز انهزموا وقُتِلَ منهم سبعة رجال، وبعد أيام وفد أهل الفرعةِ على الشيخ محمد وبايعوه على السمعِ والطاعة، ورئيسُهم منصور بن حمد بن إبراهيم بن حسين، واستقاموا على البيعة، ثم حارب أهل الفرعة مع قواتِ الدرعية أهلَ أشيقر سبعَ سنوات حتى استولوا على أبراجِها, فدخل أهل أشيقر بسبب ذلك في دعوة الشيخ محمد بن عبد الوهاب، وأصبحت أشيقر خاضعةً لإمارةِ الدرعيَّة، وذلك بعد قيامِ عِدَّةِ حملاتٍ عسكرية ضدَّهما."},{"id":4122,"title":"وفاة الشيخ صباح الأول الصباح أمير الكويت, وتولى ابنه عبد الله .","date":["العام الهجري :1175","العام الميلادي :1761"],"text":"هو الشيخُ صباحُ الأول بن جابر الصباح في الكويت، وهو من عشيرة الشملان من بني عتبة من جُميلة من عنزة من ربيعة: جد أمراء آل الصباح؛ حُكَّام الكويت، وأولُ من حكم الكويت بعد تأسيسها. يُرَجَّح أنَّ أصله من الهدار من منطقة الأفلاج في نجدٍ، وقد بُنِيت الكويت في عهده، وفي مذكرات خالد الفرج: أنَّ الكويت حديثةُ البناء، كان موضِعُها يسمى \"القرين\"، وكانت السلطة في القرين لبني خالد، ورئيسُهم في أواخر القرن الحادي عشر للهجرة براك بن غرير الحميدي، فبنى براك قصرًا في القرين، والقصر في اصطلاح ذلك الزمن هناك يسمى \"الكوت\". وقد خلَّف صباح الأول خمسةَ ذكور، هم: عبد الله (وهو الذي حكم الكويت بعده)، وسلمان، ومالج، ومحمد، ومبارك."},{"id":4123,"title":"تولي الشيخ عبد الله الأول بن صباح الأول الحكم في الكويت .","date":["العام الهجري :1175","العام الميلادي :1761"],"text":"تولَّى حكمَ الكويت الشيخُ عبد الله الأول بن صباح الأول بن جابر، وكان ذلك بعد وفاة أبيه، وقد حَسُنت سيرته، وكان عاقلًا يوصَفُ بالشجاعة والكرم، وانتعشت الكويتُ في عهده، واستمَرَّ في الحكم إلى أن توفي، وفي أيامه هاجَرَ آل خليفة (حكام البحرين) إلى الكويت."},{"id":4124,"title":"وفاة العلامة شاه وَليُّ الله الدهلوي .","date":["العام الهجري :1176","العام الميلادي :1762"],"text":"هو العلامةُ كوكب الديار الهندية شاه وَليُّ الله أبو عبد العزيز قطبُ الدين أحمد بن عبد الرحيم الفاروقي الدهلوي، من علماءِ الهند البارزين, وهو فقيهٌ حنفي من المحدِّثين من أهلِ دهلي بالهند، ولِدَ سنة 1110هـ  زار الحجاز سنة 1143 - 1145هـ. قال صاحب فهرس الفهارس: \"أحيا الله به وبأولاده وأولاد بنتِه وتلاميذِهم الحديثَ والسنَّةَ بالهند بعد مواتهما، وعلى كتبه وأسانيده المدارُ في تلك الديار\" كان فصيحًا باللغتين العربية والفارسية، له مصنَّفات عديدة تدلُّ على غزارة علمه ووفرة عقله، أشهرها \"حجة الله البالغة\" وله: الإنصاف في بيان أسباب الاختلاف، والفوز الكبير في أصول التفسير، وشرح تراجم أبواب صحيح البخاري، وعقد الجيد في أحكام الاجتهاد والتقليد، وشرح الموطأ، وغيرها من المصنفات، وقيل إنه توفي سنة 1179هـ."},{"id":4125,"title":"غزو الأمير عبد العزيز بن محمد الأحساء ديار بني خالد .","date":["العام الهجري :1176","العام الميلادي :1762"],"text":"غزا الأميرُ عبد العزيز بن محمد الأحساءَ ديارَ بني خالد خصومِ الدَّعوةِ، وكانت خيلُهم نحو 30 فرسًا، فأناخ عبد العزيز في مكانٍ يسمى المطيرفي، وهجم على من كان فيه من أهلِها، فقتل منهم سبعين رجلًا، وأخذوا منهم كثيرًا من الأسلحة والأمتعة والدواب. فلما أرادو الرجوعَ إلى نجد أغاروا على المبرز، ونالوا من أهلها."},{"id":4126,"title":"أمير الرياض دهام بن دواس يطلب الصلح من أهل الدرعية .","date":["العام الهجري :1177","العام الميلادي :1763"],"text":"طلب أميرُ الرياض دهـام بن دواس الصلحَ من الشيخ محمد بن عبد الوهاب والإمـام محمد بن سعود، ومع علمِهما بأنَّه لا يفي بوعده إلَّا أنهما وافقا بشروط، منها: أن يقبَلَ دهام بعودة أنصار الدعوة إلى الرياضِ بعد أن كان قد اضطرَّهم إلى الهجرةِ منها, وأن يردَّ دهام إلى المهاجرين الأموالَ التي صادرها منهم في الرياض حين هجرتِهم منها, وأن يسوقَ إلى الدرعية ألفَي (ريال) أحمر معجَّلة, فالتزم دهام بهذا الصلحِ إلى وفاة الإمام محمد بن سعود عام 1179هـ, وحضر مع الإمام عبد العزيز بن محمد الحربَ التي شنَّتْها الدرعية ضِدَّ عشائر الظفير في وقعة \"جراب\" بالقرب من سدير، وكانت هذه أول غزوة ينضمُّ فيها دهام إلى لواءِ الدرعية."},{"id":4127,"title":"شركة الهند الشرقية الهولندية تسيطر على البصرة .","date":["العام الهجري :1178","العام الميلادي :1764"],"text":"استطاع الهولنديون أصحابُ شركة الهند الشرقية الهولندية أن يدخُلوا الخليج العربي عن طريقِ تحالُفِهم مع الإنكليز، ثم إن الهولنديين أرادوا التوغُّلَ بتجارتهم وأطماعِهم أكثَرَ من ذلك، فاستطاعوا الظهورَ في البصرة بعد أن عرفوا أنَّ التجارةَ فيها رابحةٌ، فمدُّوا نشاطَهم إلى العراق، وأرسلوا سفُنَهم إلى البصرة، واستطاعوا أن يأخذوا السوقَ من الإنكليز وخاصة بوجود الامتيازات الممنوحة لهم من قِبَل علي باشا من أسرة آفراسياب، ووصل أمرُ الهولنديين في البصرةِ إلى أن أصبحوا يمنَعون الإنكليز والبرتغاليين من الوصولِ إلى البصرة بالقوة، حتى انسحبت مضطرةً شركةُ الهند الشرقية الإنكليزية تاركةً الساحةَ أمام الهولنديين الذين أصبحوا هم المسيطرين على البصرةِ تجاريًّا وعسكريًّا."},{"id":4128,"title":"غزو عريعر بن دجين الدرعية بمساندة خصوم الدرعية في نجد .","date":["العام الهجري :1178","العام الميلادي :1764"],"text":"بعد هزيمةِ جيش الدرعية في وقعةِ الحاير أرسل عريعر بن دجين حاكمُ بني خالد في الأحساءِ إلى الحسن هبة الله المكرمي يدعوه إلى البقاءِ في نجد حتى يقدَمَ عليه بجيوشِه ليشتركوا في قتال الدرعية, لكِنَّ المكرمي كان قد كاتب حُكَّام الدرعية بعد واقعة الحاير على تبادُلِ الأسرى، فلما أطلق الأسرى من الجانبين عاد إلى بلادِه، بعد أن مكث في نجد 15 يومًا. خرج عريعر مع بني خالدٍ كافةً وأهل الأحساء، فلم يصل الدهناء حتى بلغه خبر ارتحال رئيس نجران إلى بلادِه، فلما وصل عريعر نجدًا وانضمَّ إليه خصوم الدعوة والدولة، وعلى رأسهم دهام بن دواس الذي نقض عهدَه مع الدرعية، ثم استشار عريعر ذوي المعرفة من أهل نجدٍ في المنزل الذي ينزِلُه من الدرعية مع أعرابِه، بحيث يتسِعُ للحضر والبدو من أهلِ الأحساء ومن انضم إليهم من أهل نجد، فنزلوا بين قرى القصير وقرى عمران، ومعه المدافع والقنابر- قنبلة المدفع- فامتلأت قلوبُ أهل البلاد رعبًا، لكنَّهم عزموا على القتال والتوكُّل على الله, فبدأ عريعر برمي أسوار المدينة وأبراجِها بالمِدفَع، وتتابع الرميُ لكن لم يسقُطْ من السور أيُّ لبنة، واشتدت عزائِمُ أهلِ الدرعية فخرجوا من أسوار المدينة بأمرٍ من الأمير عبد العزيز، ففرح جنود عريعر بخروجِهم فهجموا عليهم، ثم تراجعوا إلى داخل السور واستجروا معهم عددًا من جنود عريعر فنشب بينهم القتالُ حتى تمكنوا من قَهرِهم، وقتلوا منهم رجالًا, أعاد الأمير عبد العزيز ما تهدَّم من السور وأقام عريعر ومن معه على حالهم أيامًا، حتى اشتد عليهم الضيقُ، وخاصة الظمأُ، إلى أن جاء عريعر بعضُ أهل الحريق وحرَّضوه على القتال واتفقوا على أن يبدؤوا الحرب في اليوم التالي، لكنَّ خبَرَهم بلغ الأمير عبد العزيز، فاستعدوا لقتالهم، فلما بدأت المدافع تُصلي الحصنَ والسور بنار عظيمةٍ، وصار المهاشير ومن معهم على الزلال، وبنو خالد وأهل الأحساء على سمحان، وأهل الحريق والوشم وابن دواس وابن فارس قصدوا قصير وأحاطوا بالدرعية كإحاطة السِّوارِ بالمِعصَم، ثم احتدم القتال إلى أن شاء الله أن ينصُرَ أهل الدرعية عليهم، فانهزم التحالف وقُتِل منهم 50 رجلًا، وانهزم رئيس المدفع بعد قطع يمينِه, وكان جملةُ مَن قتل من أهل المدينة ستةَ رجال."},{"id":4129,"title":"دمج \"مجلس أحكام العدلية\" أعلى مؤسسة في الدولة العثمانية .","date":["العام الهجري :1178","الشهر القمري : محرم","العام الميلادي :1764"],"text":"تم دمج \"مجلس عالي تنظيمان\"- الذي كان يعدُّ أعلى مؤسسة في الدولة العثمانية، والذي تم إنشاؤه في عام 1854م- في مجلس \"والا\" أو \"مجلس أحكام العدلية العالي\" الذي أنشأه السلطان محمود الثاني في إبريل 1838م."},{"id":4130,"title":"هزيمة جيش الدرعية في وقعة الحاير على يد رئيس نجران .","date":["العام الهجري :1178","الشهر القمري : ربيع الآخر","العام الميلادي :1764"],"text":"جرت الوقعةُ المشهورة بوقعة الحاير- وهو مكان يُعرَف بحاير سبيع، بين الرياض والخرج- وكانت هذه الوقعة ابتلاءً لأهل التوحيد أتباع الدرعية, وكان سببُ هذه الوقعة أن العجمان بعد أن هزمهم عبد العزيز بن محمد في قذلة عام 1177هـ وقتل منهم فريقًا وأسر فريقًا آخر، استنجدوا برئيس نجران وقبائل يام، فاستجاب صاحبُ نجران الحسنُ بن هبة الله المكرمي لشكواهم، وأعدَّ العدة لذلك، وأبلغ صاحِبَ الأحساء عريعر بن دجين عدو ابن سعود بعزمِه على السير لقتال الدرعية، وعقد معه اتفاقًا للتعاون والاشتراك بقتالها، وضرب له موعدًا للقاء عند الحاير، فلما وصل المكرمي الحاير بقي أيامًا يحارب أهلَها حتى وصل جيش الدرعية الذي قيل إنه كان معتدًّا بنفسه ومُعجبًا بقوَّتِه وكثرة عددِه، فلمَّا وصَلوا قرية الحاير التقى الجيشان واشتَدَّ القتال بينهما حتى انهزمت قوات الدرعية، وقُتِلَ منها 400 وأُسر 300، وتم الاتفاق على تبادُلِ الأسرى وانسحاب جيش نجران, ثم أرسل دهام بن دواس أمير الرياض هدايا يستميلُه لمحاربة بقية أتباع الدرعية، ويَعِدُه بكثيرٍ من الأموال والفوز وفتحِ البلدانِ وحُكمِها."},{"id":4131,"title":"برد شديد في نجد قضى على الزرع والثمار .","date":["العام الهجري :1179","العام الميلادي :1765"],"text":"أتى على نجدٍ في هذا العام بردٌ شديدٌ لم يُعهدْ مِثلُه أذهب الزرعَ والثمار"},{"id":4132,"title":"وفاة الأمير محمد بن سعود آل مقرن وتولي ابنه عبد العزيز من بعده .","date":["العام الهجري :1179","الشهر القمري : ربيع الأول","العام الميلادي :1765"],"text":"هو الأميرُ الإمامُ محمَّدُ بنُ سعود بن محمد بن مقرن بن مرخان بن إبراهيم بن موسى بن ربيعة بن مانع بن ربيعة المريدي الدرعي العدناني، مؤسِّسُ الدولة السعودية الأولى، وكان الإمامُ محمد بن سعود آل مقرن قد انطلق من مدينة الدرعية (المنطقة الوسطى بجانب مدينة الرياض، العاصمة الحالية). وكان شجاعًا حازمًا، وقد التقى بالإمام محمد بن عبد الوهاب الذي كان يطلب حمايةَ الدعوة من الإمام محمد بن سعود. وتوافق الاثنان على كثيرٍ من الأمور واتفقا على إقامة دولة مسلِمة تطبِّق الإسلام وتعيدُه إلى أصولِه الصافية بعد ما دخله من الدَّجَل والكهانة, وتحمي الدعوةَ إليه؛ ولتأكيد الصلة بينهما تزوج ابنُ الإمام محمد بن سعود بابنةِ الإمام محمد بن عبد الوهاب, وانطلقت جيوشُ إمارة الدرعية لتوحيدِ الأجزاء المتفَرِّقة في نجدٍ، فضمت كل بلاد العارض (عدا الرياض) وأغلب منطقة الخرج والحاير والوشم والمحمل وسدير، ونشرت الدعوة فيها. وكانت إمارةُ الدرعية تسمي بدولةِ آل مقرن نسبةً إلى جدهم مقرن بن مرخان؛ لأن الناس لم يسمُّوا العائلة الحاكمة للدرعيَّة بآل سعود إلَّا في عهد الإمام الثالث سعود الكبير بن عبد العزيز بن محمد بن سعود. وقد خَلف الإمامُ محمد بعد وفاته ابنَه الإمام عبد العزيز بن محمد بن سعود, فبايعه الناسُ بالإمامة بعد أبيه, يقول ابن غنام: \"كان الشيخُ محمد بن عبد الوهاب هو رأسَ النظام المُحْكم لعقده, فأسقط الإمامُ عبد العزيز جميع المظالم والمغارم، وارتفع الحق وأقبلت الدنيا على رعيته، وسارت بفتوحه الركبان, وطارت قلوب أهل الضلال فزعًا\"."},{"id":4133,"title":"نقض أمير الرياض دهام بن دواس عهده مع الدرعية .","date":["العام الهجري :1179","الشهر القمري : ربيع الأول","العام الميلادي :1765"],"text":"نقض أميرُ الرياض دهام بن دواس وأبدى الخيانة، فسار هو وزيد بن زامل رئيسُ الدلم وعدا على الصبيحات في المنفوحة، وأخذا منها سائمةً كثيرة، فخرج أهل منفوحة فقاتلوهما، فقتل من الطرفين عدةُ رجال، فثارت الحرب بين الطرفين، وكان دهام هو الذي فتح باب القتال بنقضِه العهد، وكانت هذه الحرب سببًا لهلاكه وخروجِه من الرياض."},{"id":4134,"title":"انضمام بلدة العودة في سدير لحكم الدرعية .","date":["العام الهجري :1181","العام الميلادي :1767"],"text":"غزا جيشٌ من الدرعية العودة في سدير, وأميرهم هذلول بن فيصل، ومعه سعود بن عبد العزيز- وهذه أول غزوة غزاها سعود بن عبد العزيز- فدخلوا البلدة ليلًا وأعدوا كمينًا لم يشعُرْ به أحدٌ، فلما أصبحوا غار جيش الدرعية على أطراف البلد، فخرج أهلها إليهم ليقاتلوهم، فدخل الكمين البلدة، فلما علم الذين خرجوا من أهل البلدة بذلك عادوا إليها، وأرادوا دخول القلعة, فوجدوا جيشَ الدرعية قد استولَوا عليها، فجرى بينهم قتال حتى تمكَّن هذلول بن فيصل من السيطرة على البلدة، ونودي فيها بالأمان، واستعملَ الأميرُ عبد العزيز بن محمد منصورَ بنَ حماد أميرًا على بلدةِ العودة."},{"id":4135,"title":"ارتفاع الأسعار في نجد في سنة سوقة .","date":["العام الهجري :1181","العام الميلادي :1767"],"text":"ارتفعت الأسعارُ في نجد ونَفِدَ الزاد، وقاسى الناس ألوانَ الضيق, واستمَرَّ غلاء الأثمان إلى السنة التالية، وزاد ما كان يلقاه الناسُ مِن مشقة وضيق، حتى سميت هذه السنة سنة سوقة أو قحط سوقة"},{"id":4136,"title":"وفاة العلامة الشيخ عمر بن علي الطحلاوي المالكي الأزهري .","date":["العام الهجري :1181","الشهر القمري : صفر","العام الميلادي :1767"],"text":"هو الشيخُ الإمام الثبت العلامة الفقيهُ المحدِّث الشيخ عمر بن علي بن يحيى بن مصطفى الطحلاوي المالكي الأزهري، تفقه على الشيخ سالم النفراوي وحضر دروس الشيخ منصور المنوفي، والشهاب ابن الفقيه، والشيخ محمد الصغير الورزازي، وغيرهم، وسمع الحديثَ عن الشهابين أحمد البابلي والشيخ أحمد العماوي، وأبي الحسن علي بن أحمد الحريشي الفاسي، وتمهَّر في الفنون ودرَّس بالجامع الأزهر وبالمشهد الحُسيني، واشتهر أمرُه وطار صيته، وأشير إليه بالتقدُّمِ في العلوم، وتوجَّه إلى دار السلطنة في قضاء مهمة لأمراء مصر، فقوبل بالإجابة وألقى هناك دروسًا في الحديث في آيا صوفيا، وتلقى عنه أكابرُ العلماء هناك في ذلك الوقت، وصُرف معزَّزًا مقضيًّا حوائجه، وذلك سنة 1147. ولما تمم عثمان كتخدا القزدغلي بناء مسجده بالأزبكية في تلك السنة عيَّن الطحلاوي للتدريس فيه، وذلك قبل سفره إلى الديار الرومية، وكان مشهورًا في حسن التقرير وعذوبة البيان وجودة الإلقاء، وقرأ الموطأ وغيرَه بالمشهد الحسيني، وأفاد وأجاز الأشياخ, وكان للناس فيه اعتقادٌ حسنٌ، وعليه هيبةٌ ووقار وسكونٌ، ولكلامه وقْعٌ في القلوب. توفي ليلة الخميس حادي عشر صفر من هذه السنة، وصُلي عليه في الأزهر في مشهد حافل."},{"id":4137,"title":"وفاة الشيخ محمد الحفناوي الشافعي شيخ الطريقة الخلوتية الصوفية .","date":["العام الهجري :1181","الشهر القمري : ربيع الأول","العام الميلادي :1767"],"text":"هو الشيخُ محمد بن سالم الحفناوي الشافعي الخلوتي الصوفي, شيخُ الأزهر, وهو شَريفٌ حُسيني من جهة أم أبيه، وهي السيدة ترك ابنة السيد سالم بن محمد بن علي بن عبد الكريم بن السيد برطع, وينتهي نسَبُه إلى الإمام الحسين رضي الله عنه، وكان والده مستوفيًا عند بعض الأمراء بمصر، وكان غايةً من العفاف، ولِدَ على رأس المائة بعد الألف ببلده حفنا بالقصر, وهي قريةٌ من أعمال بلبيس، وبها نشأ، والنسبةُ إليها حفناوي، وغلبت عليه النسبة حتى صار لا يُذكَرُ إلا بها، وقرأ بها القرآن إلى سورة الشعراء، ثم حجزه أبوه بإشارة الشيخ عبد الرؤوف البشبيشي وعمره أربع عشرة سنة بالقاهرة، فأكمل حفظ القرآن، ثم اشتغل بحفظ المتون، فحفظ ألفية ابن مالك، والسلم، والجوهرة، والرَّحَبية، وغير ذلك. وأخذ العلم عن علماء عصره، واجتهد ولازم دروسهم حتى تمهَّر، وأقرأ ودرَّس وأفاد في حياة أشياخه وأجازوه بالإفتاء والتدريس، فأقرأ الكتب الدقيقة كالأُشموني، وجمْع الجوامع، والمنهج، ومختصر السعد، وغير ذلك من كتب الفقه والمنطق والأصول والحديث, وأصبح شيخًا للطريقة الخلوتية يقصده المريدين, كما تولى مشيخةَ الأزهر عشر سنوات. توفي يوم السبت الموافق 27 من ربيع الأول عام 1181هـ، عن عمر يناهز الثمانين عامًا، ودُفن في اليوم التالي بعد الصلاةِ عليه في الجامع الأزهر في مشهد حافل."},{"id":4138,"title":"ثورة علي بك الكبير والي مصر  .","date":["العام الهجري :1182","العام الميلادي :1768"],"text":"كان الخليفةُ العثماني مصطفى الثالث قد طلب من والي مصر حمزة باشا اثني عشر ألف مقاتل لمحاربة الروس، فأوقعت المماليكُ والباشا الفِتَنَ بحَقِّ علي بك متولي المشيخة، وقد ورد فرمانٌ في قتله وإرسال رأسِه إلى السلطان غيرَ أنَّ علي بك عَلِمَ بذلك وتربَّص بالرسل وقتلهم، وأعلن استقلاله بمصر بدَعمٍ مِن الروس؛ من أجل إضعاف الدولة العثمانية. كتب علي بك إلى الشيخ (ظاهر) ظاهر العمر أمير عكا يُعلِمُه بذلك، فعلم الخليفةُ بذلك فأرسل إلى والي دمشق للسيرِ بخمسة وعشرين ألف جنديٍّ لمنع جنود عكا من مساعدة علي بك، فسار والي دمشق، غير أن الظاهر لاقاه في ستة آلاف في موقع ما بين جبل النيران وبحيرة طبرية، وردَّه على أعقابه، ثم أرسل علي بك محمد بك أبا الذهب لمحاربة الشيخ هامان وقبيلته بالحجاز، وتغلَّب عليهم، وقد كَلَّفت هذه التجريدة قرابة 26 مليون فرنك."},{"id":4139,"title":"غزو الأمير سعود بن عبد العزيز عنيزة .","date":["العام الهجري :1182","العام الميلادي :1768"],"text":"قاد الأميرُ سعود بن عبد العزيز حملةً عسكرية ركابُها نحو مائة من الإبل ضد عنيزة، فأغار عليها فخرج عليهم أهلها، وكان عِدَّتُهم مئات، ونشب بينهم القتال إلى أن انهزم أهلُ عُنيزة وقُتِلَ منهم نحو عشرةٍ مِن الرجال."},{"id":4140,"title":"إعلان بريدة ولائها لدولة الدرعية، وتبني دعوة الشيخ محمد بن عبد الوهاب .","date":["العام الهجري :1182","العام الميلادي :1768"],"text":"أعلنت بُريدة بقيادة أميرِها حمود الدريبي آل عليان ولاءَها لدولة الدرعية وتبنِّي دعوة الشيخ محمد بن عبد الوهاب، وذلك حين دَعَمت حكومةُ الدرعيةِ أميرَها حمود الدريبي ضدَّ أمير عنيزة عبد الله بن أحمد بن زامل، بقوَّاتٍ قادها الأميرُ سعود بن عبد العزيز, لكنَّ بريدة لم يستقِرَّ ولاؤها للدرعية إلَّا سنة 1189."},{"id":4141,"title":"إعلان الدولة العثمانية الحرب على روسيا .","date":["العام الهجري :1182","الشهر القمري : ربيع الآخر","العام الميلادي :1768"],"text":"نشبت الحربُ بين الدولة العليَّة وروسيا؛ وذلك أنه لما توفِّيَ أوغست الثالث ملك بولونيا سعت كاترين الثانية إمبراطورة روسيا في تعيين أحد أتباعها مَلِكًا على بولونيا خلافًا لِما تعهَّدت به روسيا للدولة العلية؛ ولذلك تنبهت الدولة العلية إلى نتيجةِ هذه السياسة وعَلِمَت أنها إن لم تضَعْ حدًّا لتقدم نفوذ روسيا في بولونيا، فلا تلبث بولونيا أن تُمحى من العالم السياسي بانضمامها لروسيا أو بتجزئتِها بينها وبين مجاوريها، لكن كان تنبُّه الدولة هذا بعد فوات الوقت المناسب، فإنه كان يجِبُ عليها مساعدة السويد وبذْل النفس والنفيس في حفظ ولايتها الواقعةِ على البلطيق من الوقوع في أيدي روسيا، ومع كل هذا فقد أرادت الدولة العليَّةُ استدراك ما فات وأوعزت إلى كريم كراي خان القرم أن يعلِنَ الحرب على روسيا، فأغار بخيله ورَجِلِه على إقليم سربيا الجديدة الذي عمرته روسيا، مع أن المعاهدات التي بينها وبين الدولتين تنصُّ على منع وصول المساعدة من خان القرم إلى بولونيا, وكانت نتيجةُ إغارة كريم كراي على هذه الولاية خرابًا كثيرًا من المستعمرات الروسية، وعودته بكثير من الأسرى، وتوفِّي قبل أن تنتهي الحرب التي استمرت حتى عام 1187هـ."},{"id":4142,"title":"وفاة العلامة الأمير محمد الصنعاني .","date":["العام الهجري :1182","الشهر القمري : رمضان","العام الميلادي :1769"],"text":"هو العلامةُ المجتهد السيد الحسني صاحب التصانيف: الأمير محمد بن إسماعيل الكحلاني، ثم الصنعاني. ولِدَ ليلة الجمعة نصف جمادى الآخرة سنة 1099هـ بكحلان ثم انتقل مع أسرته إلى صنعاء سنة 1107هـ وأخذ عن علمائها، ووالده كان من الفضلاء الزاهدين في الدنيا الراغبين في العمل، وله شعر جيد، مات في ثالث شهر ذي الحجة سنة 1142هـ. رحل الصنعاني إلى مكة وقرأ الحديث على أكابر علمائها وعلماء المدينة، وبرع في جميع العلوم، وفاق الأقران، وتفرد برئاسة العلم في صنعاء، وأظهر الاجتهاد وعَمِل بالأدلة، ونفر عن التقليد وزيَّف ما لا دليلَ عليه من الآراء الفقهية، وجرت له مع أهل عصره خطوبٌ ومِحَنٌ، منها في أيام المتوكل على الله القاسم بن الحسين، ثم في أيام ولده الإمام المنصور بالله الحسين بن القاسم، ثم في أيام ولده الإمام المهدى العباس بن الحسين، وتجمع العوامُّ لقتلِه مرة بعد أخرى، وحفظه الله من كيدهم ومكرهم، وكفاه شرهَّم، وولاه الإمامُ المنصور بالله الخطابةَ بجامع صنعاء، فاستمر كذلك إلى أيام ولده الإمام المهدي، واتفق في بعض الجمع أنَّه لم يذكر الأئمة الذين جرت العادة بذكرِهم في الخطبة الأخرى، فثار عليه جماعةٌ من آل الإمام الذين لا أنسةَ لهم بالعلم، وعضَّدهم جماعة من العوام وتواعدوا فيما بينهم على قتلِه في المنبر يوم الجمعة المقبلة، ولم يفلحوا، واستمر ناشرًا للعلم تدريسًا وإفتاءً وتصنيفًا، وما زال في محَنٍ من أهل عصره، ووقعت له فِتَن كبار وقاه الله شَرَّها, وكان الصنعاني قد بدأ بعقد حلقات العلم ولَمَّا يُتِمَّ الرابعة والعشرين من عمره, فقد كان بارعًا في الفقه والأصول، ومؤلفاته تنمُّ عن سعة علمه وجودة ذهنه، واستحضاره للأدلة ومناقشتها، واستخراج الأحكام الفقهية، وكان يدعو إلى تجديد الدين والعودة إلى أصوله وحقيقته كدعوة الشيخ محمد بن عبد الوهاب؛ ولذلك لَمَّا بلغته دعوةُ الشيخ المجدد أيَّدَها وأرسل للشيخ قصيدةً يثني فيها عليه وعلى دعوته، ومما قاله فيها: سلامي على نجدٍ ومن حلَّ في نجـدِ وإن كان تسليمي على البعدِ لا يُجدي وقد صدرت من سفحِ صنعا سقى الحيا رباهـا وحـياهـا بقهقهة الرعـدِ سرت من أسير ينشد الريح أن سرت ألا يا صبا نجـدٍ متى هِجتَ من نجـدِ قفي واسألي عن عالمٍ حَـَّل سوحها به يهتدي من ضَلَّ عن منهج الرشدِ محمَّـد  الهـادي  لسنة أحمـد فيا حبذا الهادي ويا حبذا المهدي لقد أنكرَت كلُّ  الطوائف  قولَهبلا صدَرٍ في الحقِّ منهم ولا وردِ وللإمام الصنعاني مؤلفات كثيرة، منها: التحبير لإيضاح معاني التيسير، وهو شرح كتاب تيسير الوصول لابن الديبع, والتنوير شرح الجامع الصغير، وتوضيح الأفكار لمعاني تنقيح الأنظار, وثمرات النظر في علم الأثر, والعدة على شرح العمدة، وهو مليء بالفوائد الفقهية والأصولية، وتطهير الاعتقاد من أدران الإلحاد, وحاشية على البحر الزخار في الفقه الزيدي, وسبل السلام اختصره من البدر التمام للمغربي, ومنحة الغفار جعلها حاشية على ضوء النهار للجلال, وشرح التنقيح في علوم الحديث للسيد الإمام محمد بن إبراهيم الوزير، وسماه التوضيح, ومنظومة الكافل لابن مهران في الأصول وشرحها شرحًا مفيدًا, وله مصنفات غير هذه، وقد أفرد كثيرًا من المسائل بالتصنيف بما يكون جميعه في مجلدات، وله شعر فصيح منسجم، جمعه ولده العلامة عبد الله بن محمد في مجلد، وغالبه في المباحث العلمية والتوجع من أبناء عصره والردود عليهم، وبالجملة فهو من الأئمة المجدِّدين لمعالم الدين. أما وفاته فقد أصيب بالحمى والإسهال الشديد حتى توفي في الثالث من شعبان من هذا العام, وقد بلغ من العمر ثمانين سنة. ونظم بعضُهم تاريخه، ورثاه شعراءُ العصر وتأسَّفوا عليه."},{"id":4143,"title":"هجوم خان القرم التابع للدولة العثمانية على أوكرانيا .","date":["العام الهجري :1182","الشهر القمري : رمضان","العام الميلادي :1769"],"text":"استطاع خان القرم التابعُ للدولة العثمانية أن يقوم بهجوم شتوي مفاجئ على أوكرانيا أثناء الحرب الروسية - العثمانية، فنجح ملِكُ القرم في غارتِه، وهدم عددًا من الضِّياعِ وحمل الآلافَ من الأسرى."},{"id":4144,"title":"محاصرة الجيش الروسي قلعة خوتين التابعة للحكم العثماني .","date":["العام الهجري :1182","الشهر القمري : ذي الحجة","العام الميلادي :1769"],"text":"حاصر الجيشُ الروسيُّ قلعة خوتين الواقعةَ على نهر دنيسنز، والتي تعدُّ المدخَلَ الرئيسيَّ لبولونيا التي كانت تابعةً للدولة العثمانية، بَيْدَ أنَّ الجيشَ العثماني استطاع تشتيتَ الجيشِ الروسي بعد يومٍ مِن الحصار."},{"id":4145,"title":"انضمام أهل القصيم لدعوة الشيخ محمد بن عبد الوهاب .","date":["العام الهجري :1183","العام الميلادي :1769"],"text":"غزا الإمامُ عبد العزيز بن محمد بأهل الدرعية وقراها بلدةَ الهلالية وهي مِن قرى القصيم، فوصلها ليلًا وأعدَّ لها كمينًا، فلما أصبحوا حاربَ أهلَها حتى هزموهم, وقُتِل منهم رجالٌ، ثم دخل عبد العزيز الهلاليةَ وأقام فيها أيامًا، فوفد إليه أهلُ القصيم يعلنون له السمع والطاعة، فأخذ عليهم العهدَ ووضع عندهم معلِّمين يعلمونهم التوحيدَ والشَّرائعَ والأحكامَ."},{"id":4146,"title":"حج طائفة من أهل الدرعية وأتباع الدعوة .","date":["العام الهجري :1183","العام الميلادي :1769"],"text":"في هذه السَّنةِ غَزَت جماعةٌ من الدرعية، فصادفت الشريف منصورًا فأسَرَتْه مع ركبٍ كان معه، فمَنَّ الإمامُ عبد العزيز وأطلقه دون فداءٍ, فلما عاد الشريف منصور إلى مكةَ استأذن من شريفِ مكَّةَ ليَسمحَ لأتباع الدرعية بالحَجِّ، فحجَّت طائفةٌ منهم آمنة وقضت فرضها بعد أن كان الحجُّ متعسرًا على أتباع الدعوة بسبَبِ الشائعات التي لدى أشرافِ مكَّةَ ضِدَّ أتباع دعوة الشيخ محمد بن عبد الوهاب."},{"id":4147,"title":"تجدد قتال العثمانيين مع الروس .","date":["العام الهجري :1183","الشهر القمري : ربيع الآخر","العام الميلادي :1769"],"text":"كان السلطانُ مصطفى الثالث يرى أنَّ الخطرَ الدَّاهِمَ على الدولة العثمانية يتمثَّلُ في ظهورِ القوة الروسية الجديدة، ويبدو أنَّه اطَّلع على المخطط الأسود الروسي لتفتيت الدولة العثمانية الذي وضعه بطرس الأكبر في وصيَّتِه؛ ولذلك أعدَّ السلطان مصطفى الثالث لحرب روسيا، فخاضت الدولةُ العثمانية حربًا مع روسيا بسبب اعتداءات القوزاق التابعين لروسيا على مناطق الحدود، فنجح ملِكُ القرم في غارته وهدم عددًا من الضِّياع وحمل كثيرًا من الأسرى، وذلك عام 1182هـ، ثم سار الصدرُ الأعظم الوزير نشانجي محمد أمين باشا بجيوشِه للدفاع عن مدينة شوكزيم التي حاصرها الروسُ، فلم ينجح لعدمِ اتِّباعِه الأوامر العسكرية الواردة إليه من السلطانِ المهتمِّ بنفسِه بأمور الحرب، ولو لم يقد الجيوشَ بذاتِه، فكان جزاءَ هذا القائد أن قُتِلَ بأمر السلطان وأُرسِلَ رأسُه إلى الأستانة عبرةً لغيره من القوَّاد, وهُزِمَ الصدر مولدواني على باشا- الذي أتى بعد نشانجي أيضًا- وهو يجتاز بجيشِه نهر الدينستر بالفيضانِ؛ حيث غرق عددٌ كبير من الجند والمراكب، وبعد هذا الانهزامِ الذي لم يكن فيه للروس من فخرٍ, التزم مولدواني باشا بالتقهقرِ بعد إخلاء مدينة شوكزيم، فاحتلَّ الروسُ إقليمي الأفلاق والبغدان، ثم أخذوا يثيرون النصارى من الروم الأرثوذكس للقيام بثوراتٍ ضِدَّ الدولة العثمانية، فأثاروا نصارى شبه جزيرة المورة فقاموا بثورة غيرَ أنَّ ثورتَهم أُخمِدَت."},{"id":4148,"title":"قتال بين الأسطول الروسي والأسطول العثماني في أكثر من موقع .","date":["العام الهجري :1184","العام الميلادي :1770"],"text":"لَمَّا كانت روسيا ليس لها عمارةٌ بالبحر الأسود استقدمت أساطيلَها من بحر البلطيك واستعانت بسفن من إنكلترا والفلمنك والبنادقة، واستأجرت ضباطًا ورجالًا لها، فأقبل هذا الأسطول إلى البحر الأبيض ومَرَّ بسواحل مورة، وأمَدَّ رجال الثورة هناك بالمال والسلاح. فلما رأت فرنسا تغلغل روسيا في البحر الأبيض كرهت ذلك جدًّا، وعرضت على الدولة العثمانية النجدةَ فقَبِلتْها، فحضر أحد مهندسيها واسمه البارون (توت) ليساعد مهندسي الترك على ترميم القلاع وبناء الاستحكامات، وعرضت إسبانيا مساعدتها على أن تمنَحَها امتيازات تجارية، فأبى الترك ذلك، وظهر عجز الجيش العثماني في تعليماته ونظاماته أمامَ الجيوش الأوروبية التي كانت قد خطت خطواتٍ واسعةً في سبيل النظام العسكري. أما الأسطولُ الروسي بالبحر الأبيض المتوسط فإن خطره لَمَّا استشرى هناك أرسلت إليه الدولةُ أسطولها تحت قيادة حسين باشا الجزائري ففاز عليه، ثم تقدَّمت سفينتُه لأسرِ سفينة الأميرال الروسي الذي كان يعاونُه كبار رجال البحر من الإنكليز، فأسرع الأميرال بالانتقال إلى سفينة أخرى وأشعل في السفينةِ التي تركها النارَ فاحترقت، وأصيب القبودان حسين باشا بجروجٍ اقتضت أن يُنقَلَ إلى البر، ثم إن القائد العام حسام الدين باشا أمر أن تدخُلَ العمارة إلى ميناء جشمة، وكانت ميناء ضيقة، فنصحه القبودان حسين باشا بأن ذلك لا يجوزُ وربما أفضى إلى ضياع الأسطول كله فلم يُصْغِ إليه. فلما رأى قواد الأسطول الروسي أنَّ العمارة العثمانية دخلت ذلك الميناء حصروها وصَفُّوا بقيةَ السفن وأمروها بالضرب، وساقوا الحرَّاقات للهجوم على السفن العثمانية، فوقعت العمارة العثمانية في حالةٍ سيئة فأُحرِقَت جميعُها إلا سفينتين كبيرتين وخمس سفن صغيرة. فلما شفي حسين باشا الجزائري من جراحِه عاد إلى الأستانة، وطلب من الصدر أن يأذن له في فتح جزيرة ليمنوس التي استولى عليها الروسُ برجال ينتخِبُهم من الفدائيين، فأذن له فانتخب أربعة آلاف رجل، فذهب بهم ونزل في سفن مأجورة حتى نزلوا جميعًا بالجزيرة، فأوقعوا بالروس حتى أجلَوهم عنها. وانتصرت الجيوشُ العثمانية على الروس أيضًا عند طرابزون وكرجستان. ثم أُسندت قيادة السفن لحسين باشا الجزائري لِما اشتُهِر عنه من الحزم والدربة، فأخذ الأسطولَ العثماني وخرج لقتال الأسطولِ الروسي في البحر الأبيض فاضطره للهربِ. أما عساكر روسيا فقد تقدمت بعد أن انتصرت على الجيوش العثمانية في عِدَّة مواقِعَ، واستولت على قلاع إسماعيل وكلي وبندر وآق كيرمان. فاضطرت الدولةُ للجِدِّ في حشد الجنود، ولكن كانت النمسا وبروسيا أسرعَ منها في الوساطة، فرفضت روسيا هذه الوساطةَ وطلبت أن تتفِقَ مع الأتراك مباشرةً، وعرضت مطالِبَ فرفضتها تركيا، فرجعت الحرب إلى ما كانت عليه فاستولت روسيا على قلاع ماجين وطولجي وإيساقجي، ودخلت جنودُها بلاد القرم واستولت على قلاع طومان وكرج وكفه وكرزلوه، فهاجر كثير من التتار إلى الأناضول."},{"id":4149,"title":"سقوط البصرة في أيدي الإنجليز واستخدامها لأغراض تجارية .","date":["العام الهجري :1184","العام الميلادي :1770"],"text":"كانت التجارة في البصرة قد تدهورت وخاصةً بعد ظهور مرضِ الطاعون في المدينة فتوقَّفَت الحركة التجارية وسُحِب المركز الإنكليزي المقيم فيها مؤقتًا، ثم لم تلبَثْ أن مرت سنتان حتى أتى الحصارُ والاحتلال الفارسي للعراق، فأصيبت البصرة بالشَّلَلِ التِّجاري، لكن الأمرَ لم يدُمْ طويلًا؛ حيث تخلَّت إيران عن البصرة، فأعاد الإنكليز فورًا فتح مركزهم بدرجة مقيمٍ، وقطع ارتباطه بمقيمه بوشهر في إيران، وأصبحوا تحت إمرةِ مقيمي بومباي مباشرةً، فعادت أهميةُ البصرة تحت نفوذ الإنكليز إلى أهميتها التجارية؛ حيث أصبح يستعمِلُها الإنكليز أيضًا كقاعدة لنقل بريد الشركة من الهند إلى إنكلترا وبالعكس."},{"id":4150,"title":"الروس يستولون على نهر الدانوب ويشعلون الأسطول العثماني .","date":["العام الهجري :1184","الشهر القمري : ربيع الأول","العام الميلادي :1770"],"text":"كانت الدولةُ الروسيةُ طامحةً إلى بولونيا، وكان ذلك ضِدَّ مصلحة فرنسا, فحرَّضت فرنسا تركيا على محاربة روسيا، وكان الصدر إذ ذاك محسن زاده محمد باشا فعارض هذا الأمرَ أشَدَّ المعارضة؛ لعلمه بضعف تركيا إذ ذاك وعدَمِ استعدادها لإعلانِ حربٍ كبيرة كهذه على روسيا، فعزله السلطان وعيَّنَ بدله سلحدار ماهر حمزة باشا فأعلن الحربَ على روسيا، وقاد باغلقجي محمد أمين باشا جيشًا تركيًّا وتصدى به لعبورِ نهر الدانوب وفي أثناء ذلك عبرت روسيا نهر الدنييستر وحاصرت (خوتن) ولكن مولدواني باشا وخان القرم تمكَّنا من طرد الروس من هناك، وفي هذا الحين وُشِيَ بالصدر فعُزل وقُتل وعُيِّن مكانه مولدواني علي باشا، فتقدم لعبور نهر الدنييستر فنُصِب عليه حرس من السفن، وبينما هو يستعد لمقاتلة الأعداء في أثناء ذلك فاضت مياه النهر فجأةً، فخاف الجنود أن ينكَسِرَ الجسران فمرُّوا بدون نظام وتراكموا على الجسرين فانقلبا في النهرِ وغرق أكثَرُ من كان عليهما. وكان القائدُ التركي قد وضع ستة آلاف جندي في الضفة الأخرى فدافعوا عن أنفسهم حتى قُتلوا جميعًا. ثم إن هذا القائد أخلى خوتين بعد أن جرَّدها من جميع الذخائر فاستولى عليها الروس. أما الجيوش الروسية التي كانت على حدود آسيا فكانت ظافرةً أيضًا فإنها استولت على قبارطاي وكرجستان وجزءٍ كبير من أرمنستان. وكانت روسيا أرسلت رجالَها لإثارة نصارى اليونان والصرب الجبل الأسود وغيرهم في الجهات التي يكثر فيها العنصر الأرثوذكسي، وبذلك صارت تركيا مغلولةَ إحدى اليدين عن مقارعة خصيمتِها؛ فإنها أرسلت جيوشًا كثيرة لقمعِ هذه الثورات الداخلية وأبقتها في تلك البلاد لعدمِ عودةِ أهلها إلى التمرُّد."},{"id":4151,"title":"محاولات روسيا السيطرة على بلاد القرم .","date":["العام الهجري :1185","العام الميلادي :1771"],"text":"هاجم الروسُ مدينةَ طرابزون وفشلوا في احتلالِها، ولكِنَّهم نجحوا في اقتحامِ بلاد القرم والسيطرة عليها, ثم جَرَت مفاوضات الصلحِ، ولكنَّها فَشِلت بسبب مطالبِ روسيا التعسُّفية، وعادت الحربُ وانتصر العثمانيون, وأثناء  الحرب القائمة بين الروس والعثمانيين بعثت روسيا البرنس دلفوروكي بجيشٍ لفتح بلادِ القرم، فقابله السلحدار (رتبة عسكرية) إبراهيم باشا وهزمه، فعمد الروسُ إلى إثارة أهل القرم بأنَّها إنما تريد أن تساعِدَهم على استقلالهم عن الأتراك الذين جعلوا أنفُسَهم سادةً عليهم، مع أنهم أعرقُ منهم في السيادة؛ إذ هم أحفادُ جنكيزخان إلى غير ذلك من الأضاليل، فحلَّت هذه الأقوال عروةَ الوَحدةِ بين الترك وبين أهل القرم، ففترت عزائمُهم وقصَّروا في الدفاع عن بلادِهم سنة 1185 هـ"},{"id":4152,"title":"رسول من الدرعية يلتقي بشريف مكة  .","date":["العام الهجري :1185","العام الميلادي :1771"],"text":"أرسل الشيخُ محمد بن عبد الوهاب والإمام عبد العزيز إلى والي مكة الشريفِ أحمد بن سعيد رسولًا بهدايا, وكان الشريفُ قد كاتبهما وطلب منهما أن يرسِلَا إليه فقيهًا وعالِمًا من جماعتهما يُبَيِّن حقيقة ما يدعونَ إليه من الدِّينِ، ويناظر علماءَ مكةَ، فأرسلا إليه الشيخ عبد العزيز بن عبد الله الحصين، ومعه رسالة منهما, يقول ابن غنام: \"لما وصل الشيخُ عبد العزيز الحصين على الشريفِ الملقب بالفعر، واجتمع هو وبعض علماء مكة عنده، وهم يحيى بن صالح الحنفي، وعبد الوهاب بن حسن التركي- مفتي السلطان- وعبد الغني بن هلال، وتفاوضوا في ثلاث مسائل وقعت المناظرة فيها: الأولى: ما نُسِبَ إلينا من تكفير العموم، والثانية: هدمُ القبابِ التي على القبور، والثالثة: إنكار دعوة الصالحين للشَّفاعة. فذكر لهم الشيخ عبد العزيز أنَّ نسبة التكفير بالعموم إلينا زورٌ وبهتان علينا, وأمَّا هدم القباب التي على القبورِ فهو الحقُّ والصوابُ، كما هو وارد في كثيرٍ مِن الكتب، وليس لدى العلماء فيه شَكٌّ, وأما دعوة الصالحين وطلب الشفاعة منهم والاستغاثة بهم في النوازل، فقد نص عليه الأئمة والعلماء وقرَّروا أنَّه مِن الشرك الذي فعله القدماء، ولا يجادِلُ في جوازه إلا ملحِدٌ أو جاهِلٌ, فأحضروا كتب الحنابلة فوجدوا أنَّ الأمر على ما ذكر فاقتنعوا, واعترفوا بأنَّ هذا دينُ الله، وقالوا هذا مذهب الإمام المعظَّم، وانصرف الشيخ عنهم مبجَّلًا معزَّزًا\""},{"id":4153,"title":"تجدد القتال مع الروس .","date":["العام الهجري :1185","العام الميلادي :1771"],"text":"حاولت روسيا أن تعقد مع تركيا عهدًا مقتضاه استقلالُ القرم وأن تستولي روسيا على قلعة كرتس وبناء قلعة في مدخل بحر أزوف، وأن تكون الملاحةُ حرَّةً لروسيا في جميع موانئ الدولة التركية في البحر الأسود، وأن يكون لتلك الدولةِ حَقُّ حماية المسيحيين الأرثوذكس في تركيا، فرفضت تركيا هذا الشرطَ الأخير، فعاد الجفاء بين الدولتين على ما كان عليه، فتقدَّم الصدر الأعظم محسن زاده باشا وانتصر على الروسِ بجوار بزارجق ووارنة، وصَدَّهم أيضًا علي باشا الداغستاني أمام روسجق، ودحرهم عثمان باشا دحورًا عظيمًا، وقتل منهم تسعة آلاف وأسرَ الجنرال وينين، وقُتل الجنرال واسمان من جرحٍ أصابه."},{"id":4154,"title":"تمرد محمد بيك أبو الذهب على أستاذه علي بيك بعد دخوله الشام  .","date":["العام الهجري :1185","الشهر القمري : ربيع الأول","العام الميلادي :1771"],"text":"جهَّز حاكِمُ مِصرَ علي بك تجريدةً عظيمة لضَمِّ الشام لحُكمِه، وجعل أميرَها محمد بك أبو الذهب زوج بنته, وأرباب المناصب ومماليكهم وطوائفهم وأتباعهم وعساكر كثيرة من المغاربة والترك والهنود واليمانية والمتاولة، وخرجوا في استعدادٍ عظيم ومعهم الطبول والزمور والذخائر. فلما وصلوا إلى الديار الشامية حاصروا يافا حتى ملكوها، ثم حاربوا نواب وولاة الدولة العثمانية، فهزموهم وقتلوهم وفرُّوا من وجوههم، واستولوا على الممالك الشامية إلى حد حلب، ووردت البشائرُ بذلك لمصر، فنودي بالزينة ثلاثة أيام بلياليها، وذلك في شهر ربيع أول من هذه السنة. وتعاظم علي بك في نفسِه ولم يكتَفِ فأرسل إلى محمد بك يأمرُه بتقليد الأمراء والمناصب والولايات على البلادِ التي افتتحوها وملكوها، وأن يستمِرَّ في سيره ويتعدى الحدودَ ويستولي على الممالك إلى حيث شاء، وهو يتابِعُ إليه إرسال الإمدادات واللوازم والاحتياجات. عند ذلك جمع محمد بك أمراءَه وخشداشيته الكبار في خلوةٍ وعرض عليهم الأوامِرَ فضاقت نفوسُهم وسَئِموا الحرب والقتال، فتعاهدوا على خلافِ رأي علي بك والعودة إلى مصر وترْك الغربة والحرب، فلما عادوا إلى مصر دبَّرَ علي بيك مؤامرةً لقتل أبو الذهب, فلما اكتشفها أبو الذهب جمع أمراءَه وخشداشيته الكبار واتَّفقوا على قتال علي بك، ثم أقبل على محمد بك أبو الذهب الأمراء والأجناد المتفرقون بالأقاليم لَمَّا تحققوا الخلافَ بينه وبين سيِّده، كما حضر إليه جميعُ المنفيين وأتباع القاسمية والهوارة الذين شرَّدهم علي بك وسلَب نعمتَهم، فأنعم عليهم أبو الذهب وأكرمهم وتلقَّاهم بالبشاشة والمحبة، واعتذر لهم وواساهم وقلَّدهم الخدم، وبذلوا جهدهم في طاعته. فعند ذلك نزل بعلي بك من القَهرِ والغيظ المكظوم ما لا يوصَفُ، وشرع في تجهيزِ تجريدة عظيمة، وأمَّر عليها إسماعيل بك، وأمَر بجمعِ أصناف العساكر واجتهد، فلما التقى الجمعان خامر إسماعيل بك وانضمَّ بمن معه من الجموع إلى محمد بك، وصاروا حزبًا واحدًا، ورجع الذين لم يميلوا وهم القليل إلى علي بك."},{"id":4155,"title":"وقوع خسائر فادحة في الجيش الروسي .","date":["العام الهجري :1185","الشهر القمري : جمادى الأولى","العام الميلادي :1771"],"text":"تعرَّض الجيش الروسي المكون من 200 ألف جندي لخسائِرَ فادحة أثناء عبوره نهر الطونة للسيطرة على مولدافيا ورومانيا."},{"id":4156,"title":"علي بك الكبير يعود ويأخذ مناطق من بلاد الشام بدعم من الروس .","date":["العام الهجري :1186","العام الميلادي :1772"],"text":"بعد هزيمةِ علي بك أمام أبي الذهب محمد بك اتَّجه علي بك إلى الشامِ، فاتفق مع (ظاهر) ظاهر العمر فاستطاعا أن يسيطرا على صفد، ثم ينطلق منها إلى الجهات الثانية فدخل عكا وتسلَّم ولايتها، واضطر السلطان أن يعترف بذلك لانشغاله بالحربِ مع الروس التي دعمت علي بك وظاهر العمر لمحاربة العثمانيين، فسارا إلى صيدا لاحتلالها والتقيا بالعثمانيين خارجها وانتصرا على جيوش الدولة العثمانية بدعمٍ مِن  الأسطول الروسي في البحر المتوسط يتابعُهم ويدعمهم ويضربُ القوات العثمانية حتى ضربت بيروت وخربت جزءًا منها، ثم عاد علي بك إلى مصرَ ليتخلص من أبي الذهب محمد بك، وبذلك يحمي ظهرَه ليتابع مسيرته إلى الأناضول، فسار إلى مصر ومعه أربعمائة جندي روسي، وذلك في مطلع عام 1187هـ فالتقى الطرفان وانتصر أبو الذهب وقَتَل كلَّ من كان مع علي بك الذي توفِّيَ فيما بعد متأثرًا بجراحِه."},{"id":4157,"title":"استيلاء روسيا على بلاد القرم\n  .","date":["العام الهجري :1186","العام الميلادي :1772"],"text":"أخذت روسيا تبث رجالها في بلاد القرم لإثارة المشاغب الداخلية بها، وبالتالي لابتلاعِها وضَمِّها إلى أملاكها؛ حيث لم يكن قَصدُها من استقلالها السياسي وقطعِ روابط تبعيتها للدولة العثمانية إلا الوصولَ لهذه الغاية، وما زالت مستمرةً في إلقاء الدسائس ونشر الفتن بين الأهالي، حتى عزلوا أمير بلاد دولت كراي الذي انتخبه الأهالي بمقتضى نصوصِ معاهدة كاينارجي، وأقاموا جاهين كراي مكانه، فلم يقبل تعيينَه فريقٌ عظيم من الأعيان، وخيفَ مِن وقوع حروب داخلية؛ ولذا أمرت روسيا الجنرال بوتمكين باحتلالِها، فدخلها بسبعين ألف جندي كانوا منتظرين على الحدودِ لهذه الغاية فتَمَّ لها مقصِدُها الذي كانت تسعى وراءه من مدة، وهو امتلاكُ كافة سواحل البحر الأسود الشمالية في غضون هذه السنة، فهاجت الدولةُ العثمانية وأرادت إشهارَ الحرب على روسيا لإلزامِها باحترام معاهدة كاينارجي القاضية باستقلال بلاد القرم استقلالًا سياسيًّا تامًّا، لكن حوَّلت أنظارَها ثانيًا عن الحرب بمساعي فرنسا التي أقنعتها بأنَّ هذه الحرب مع استعداد كاترين وتأهُّبِها لها لا يكون وراءها إلا الخرابُ والدمار."},{"id":4158,"title":"نهاية حركة علي بك الكبير في الخروج على دولة الخلافة العثمانية .","date":["العام الهجري :1186","الشهر القمري : محرم","العام الميلادي :1772"],"text":"بعد أن تمكَّن محمد بك أبو الذهب من مصرَ على إثرِ هزيمة قوات أستاذه علي بك، اشتدَّ الأمر بعلي بك ولاحت على دولتِه لوائح الزوالِ، وكاد يموتُ من الغيظ والقهر, ثم شرع في تجهيزِ تجريدةٍ أخرى وأميرُها علي بك الطنطاوي, ووقعت بينهم معركةٌ قوية هُزِمَت فيها عسكر علي بك, فرَكِبَ إلى داره وحمل حمولَه وأمواله وخرج من مصر وذهب إلى جهة الشامِ، وذلك ليلة الخامس والعشرين من شهر المحرم، وبصحبته علي بك الطنطاوي وباقي صناجقه ومماليكِه وأتباعه وطوائفه. فلما أصبح يوم الخميس سادس عشريه عدَّى محمد بك إلى برِّ مصر، وأوقدوا النارَ في ذلك اليوم في الدير بعد ما نهبوه، ودخل محمد بك إلى مصرَ وصار أميرها."},{"id":4159,"title":"استيلاء الجيش الروسي على قلعة \"بندر\" العثمانية .","date":["العام الهجري :1186","الشهر القمري : جمادى الآخرة","العام الميلادي :1772"],"text":"كانت قلعة بندر قلعةً عثمانية مهمةً على الساحل الجنوبي من تورلا قربَ مدينة كيشنيف، انهزم الصدر الأعظم والسردار الأكرم عوض خليل باشا أمام رومانزوف في موقع كارتال قرب أيساكجي. فتمكَّن الجيش الروسي من الاستيلاء على القلعة، وقد ذبح الروس ُكافة المسلمين الموجودين في القلعة بالسيف، بلغ عددهم 50 ألف جندي عثماني، تمت مطاردتُهم بعد تركهم القتالَ والهروب من القلعة، فذبحهم الروس- الذين تكبدوا خسائر كبيرة على يد هؤلاء الجنود الأتراك- يقول يلماز: \"كانت روسيا هي المنتصرةَ في الحرب في بداية خريف هذا العام، وهذه نقطة تحول في التاريخ؛ فلأولِ مرة في التاريخ تغلبُ دولة أوربية لوحدها في حربٍ شاملة مع الدولة العثمانية. إنَّ تركيا كانت حتى هذا التاريخ الدولةَ الأولى في العالَم، سقطت من حيث القدرةُ إلى الدرجة الرابعة بعد إنكلترا وفرنسا وروسيا بالتسلسل\"."},{"id":4160,"title":"تحالف روسي نمساوي لطرد الدولة العثمانية من أوروبا .","date":["العام الهجري :1187","العام الميلادي :1773"],"text":"أبرمت روسيا مع النمسا اتفاقًا سِريًّا تمَّ بين كاترين الثانية وبين الإمبراطور جوزيف الثاني عند مقابلتهما بمدينة كرزن، قاضيًا بمحاربة الدولة العثمانية لإنشاءِ حكومةٍ مُستقلةٍ تكون حاجِزًا بينهما وبين الدولة العثمانية، مكوَّنة من الفلاخ والبغدان وإقليم بساربيا يكون اسمُها مملكة داسي، ويعَّين لها ملكٌ من المذهب الأرثوذكسي، وتأخذ روسيا ميناء أوتشاكوف (مدينة أوزي) وبعض جزائر الروم، وتأخذ النمسا بلادَ الصرب وبوسنه وهرسك من أملاك الدولة العثمانية، وبلاد دلماسيا من أملاك البندقية وتعطيها عِوَضًا عن ذلك بلاد مورة وجزيرتي كريد وقبرص، وأن تعطي باقيَ دول أوروبا أجزاءً أخرى يُتَّفق عليها فيما بعد، وإذا أتيح لهم النصرُ ودخلوا مدينة الأستانة، فيعيدون مملكة بيزانطة الأهلية كما كانت قبل الفتح العثماني، ويعَيَّن الغراندوق الروسي قسطنطينُ بن بولص ملكًا عليها بشَرطِ أن يتنازلَ عن حقوقِه في مملكة روسيا؛ حتى لا يتَّفِقَ وجودُ المملكتين الروسية والبيزنطية الوهمية في قبضة ملكٍ واحدٍ, وخوفًا من وقوع الحرب بسبب القرمِ، مع عدم استعداد الدولة العثمانية في ذاك الوقت على مقاومة روسيا, ففضَّلت قبولَ مشورة فرنسا والاعتراف بضمِّ القرم لروسيا، على أن تتعرَّض لحَربٍ تكونُ عاقبتها وخيمةً، واعترفت بذلك في سنة 1774م."},{"id":4161,"title":"طاعون في بغداد والبصرة .","date":["العام الهجري :1187","العام الميلادي :1773"],"text":"وقع طاعونٌ عظيم في بغداد والبصرة ونواحيهما، ولم يبق من أهل البصرةِ ونواحيها إلَّا القليل, وقيل: مات منهم 350 ألفًا، ومن أهل الزبير ستة آلاف."},{"id":4162,"title":"زيد بن زامل رئيس بلد الدلم يؤلب على الدرعية .","date":["العام الهجري :1187","العام الميلادي :1773"],"text":"بعد دخولِ الإمام عبد العزيز بن محمد الرياضَ، أرسل إلى زيد بن زامل رئيس الدلم يذكِّره الالتزامَ بالعهد الذي بينهم, فلم يلتفِتْ زيد لهذا العهدِ، وأخذ يؤلِّبُ على الدرعية، فأرسل إلى المكرمي رئيسِ نجران يستحِثُّه على حرب الدرعية ويبذلُ له المالَ، ولم يستجب له، حتى طلب منه مزيدًا من المالِ، فبذل له زيدٌ كُلَّ ما طلب مقابِلَ أن يرسِلَ له رهائِنَ مِن قومِه إلى أن يتِمَّ مقصودُه، فأرسل النجراني رؤساءَ قَومِه رهائِنَ."},{"id":4163,"title":"وفاة علي بك الكبير حاكم مصر .","date":["العام الهجري :1187","الشهر القمري : صفر","العام الميلادي :1773"],"text":"هو علي بك الكبير مملوكي حكم القاهرة كشيخ البلد أيام الدولة العثمانية, وكغيره من المماليك، لا تُعرف أصولُهم وإنما يُشتَرَون صغارًا، ثم يُجلبون لتركيا فيعتنقون الإسلام ثم يتربَّون تربية عسكرية صارمة، ويبدؤون في الصعود إلى مناصِبَ عليا والسيطرة على مقاليد الأمور، ويقال إن علي بك ابن قسيس رومي أرثوذكسي من قرية أماسيا في الأناضول. ولد سنة1140 ثم خُطِفَ وهو في الثالثة عشرة من عمره وبيع في القاهرة، فاشتراه الأمير إبراهيم كتخدا وبدأ معه رحلة التدريب والتعلُّم، حتى ظهرت عليه علامات النجابة وقوة الشخصية، حتى فاق أقرانَه في ركوب الخيل، والضربِ بالسيف، والطعنِ بالرمح، واستخدام الأسلحة النارية، وهو ما جعل سيِّدَه يعتقه وهو لم يتجاوز العشرين، وولَّاه بعضَ المهام الإدارية، إلى أن توفي أستاذه إبراهيم كتخدا سنة 1167هـ فخلفه في مناصبه الإدارية, وهو يتطلَّع إلى منصب مشيخة البلد، فأخذ يعدُّ العدة بشراء أعداد كبيرة من المماليك ويدرِّبُهم على الفنون العسكرية إلى أن جاءت سنة 1177 حيث تبوأ منصِبَ مشيخة البلد بالقاهرة، لكنَّ خصومَه أجبروه على الفرارِ إلى الصعيدِ ثم الحجاز وتارة إلى الشام، ثم عاد لمنصب مشيخة البلد عام 1181 وهو أعظم قوةً وأكثرُ عددًا، ولما استتَبَّ له الأمر تخلَّص من خصومه، فصادر أموالهم، وقتل بعضَهم ونفى البعض الآخر، ولم يسلَمْ من هذه الإجراءات حتى من قدَّموا له العونَ والمساعدة، فبطش ببعضهم ونفاهم إلى خارج البلاد. ثم ثار عليه تلميذُه وزوجُ بنته محمد بك أبو الذهب الذي تمكن من السيطرة على مصر وحكَمَها بعد فرارِ علي بك إلى الشام, ولَمَّا عاد علي بك في مطلع عام 1187هـ سار إلى مصر ومعه أربعمائة جندي روسي، فالتقى الطرفان وانتصر أبو الذهب عليهم في معركة بالصالحية بمصر، وقتل كلَّ من كان مع علي بك، الذي توفي فيما بعد متأثرًا بجراحِه بعد أن سعى للانفصال عن الدولةِ العثمانيةِ بدعمٍ وتأييدٍ من روسيا العدو اللَّدود للدولة العثمانية, فأرسل أبو الذهب رأسَ علي بك والضباط الروس إلى الوالي العثماني خليل باشا، فقام بدوره بإيصالها إلى السلطان في إستانبول, وتولى الحكم مكانَه محمد أبو الذهب الذي لم يلبث في الحكم سوى عامين ثم توفي."},{"id":4164,"title":"وفاة السلطان العثماني مصطفى الثالث وتولي أخيه عبد الحميد .","date":["العام الهجري :1187","الشهر القمري : ربيع الأول","العام الميلادي :1773"],"text":"هو الخليفة العثماني مصطفى الثالث بن أحمد الثالث بن محمد الرابع بن إبراهيم الأول بن أحمد الأول بن محمد الثالث بن مراد الثالث بن سليم الثاني بن سليمان القانوني بن سليم الأول، ولِدَ عام 1129. ولِيَ الحُكمَ بعد ابنِ عَمِّه عثمان الثالث، وكان عمُرُه حينذاك 42 عامًا. كان ميالًا للإصلاح محبًّا لتقديم بلاده، خصوصًا وزيره الأول الصدر الأعظم راغب باشا الذي أخذ في إصلاحِ بعضِ الشؤون بمساعدة السلطان وتعضيدِه له، فعَهِد بإدارة الأوقاف العمومية إلى أحد أغوات السراري قيزار أغاسي، وأسَّس مستشفيات للحجر على الواردات الخارجية؛ إذ كانت الأوبئة منتشرة في الخارج؛ لعدم تعديها إلى الممالك المحروسة، وأنشأ مكتبة عمومية على مصاريفه الخاصةِ، وفكَّر في طريقة غريبة لتسهيل المواصلاتِ داخِلَ المملكة منعًا لحصول الغلاء والمجاعات في إحدى الولايات، وذلك أن يصِلَ بين نهر دجلة وبوغاز الأستانة بخليج عظيم تستعمل الأنهار الطبيعية مجرى له على قدر الإمكان، فيسهُل نقلُ الغلالِ مِن أطراف المملكةِ إلى الأستانة فيمتَنِع عنها الغلاء كليةً، وهو مشروعٌ جليلٌ يَقدُره العارفون حقَّ قَدرِه. توفي مريضًا من حزنِه في حروب روسيا، في ربيع الأول بعد أن دام في الملك ست عشرة سنة وثمانية أشهر، وتولى بعده أخوه عبد الحميد الأول الذي كان محجوزًا في قصرِه مدَّةَ حكم أخيه مصطفى الثالث."},{"id":4165,"title":"استسلام الرياض ودخولها تحت حكم الدرعية وهروب أميرها دهام .","date":["العام الهجري :1187","الشهر القمري : ربيع الآخر","العام الميلادي :1773"],"text":"غزا الإمامُ عبد العزيز بن محمد بن سعود الرياضَ في صفَر, فنازل أهلَها أيامًا عديدة وضيَّق عليهم واستولى على بعضِ برودِها وهدم أكثَرَها وهدم المرقابَ، وحصل بينهم قتالٌ قُتِل فيه عددٌ من أهل الرياض، وكانت هذه الغزوةُ. يقول ابن بشر: \"بعد هذه الوقعة دخل قلبَ دهام الرعبُ والخجَلُ، ودخله الخوفُ والوجَلُ، فلم تستقرَّ له عينٌ, وقام يحاول الانهزامَ، وجمع رؤساءَ بلَدِه وأخبَرَهم بحقيقة مقصِدِه وأنه ملئَ خوفًا ورعبًا، فصاحوا عليه بأجمَعِهم وقالوا: خذ منا العهدَ والميثاقَ، فقال لهم: دعوني، فليست هذه البلدُ لي وطنًا، ولا أجد لي بها أنسًا ولا سكنًا\" فلما انتصف ربيع الثاني من هذا العام سار عبد العزيز للمرَّةِ الثانية في هذا العام لغزوِ الرياضِ، فلمَّا قَرُب منها جاءه البشير بأنَّ ابنَ دواس قد هرب من الرياض، فحَثَّ عبد العزيز السيرَ إليها فدخلها بعد أن ألقى اللهُ في قلب دهام  الرعبَ، فخرج منها هو ونساؤه وعياله وأعوانه. يصف ابنُ بشر خروجَ ابن دواس من الرياض ودخولَ الإمام عبد العزيز بن محمد بقوله: \"وهذا شيء حدث، فإنَّه ما خاف من أهل بلدِه خيانةً، بل كلُّهم صادقون معه، ولا حصل عليه تضييقٌ يُلجِئه إلى ذلك، والحرب بينه وبين المسلمين له وعليه، ولكنَّ الله سبحانه جعلها آيةً لِمن افتكر، وعبرةً لمن اعتبر. قيل إنه انتفخ سَحرُه وطاش قلبُه ولبُّه، فقام فزعًا مرعوبًا وركب خيلَه وركابَه، فلما ظهر من القصر، قال: يا أهل الرياض، هذا لي مدة سنين أحارب ابنَ سعود، والآن سئمت من الحرب، فمن أراد أن يتبعني فليفعَلْ, ففَرَّ أهل الرياض في ساقتِه الرجال والنساء، هربوا على وجوههم إلى البَرِّ، وقصدوا الخرجَ، وهلك منهم خلقٌ كثير عطشًا وجوعًا.. والرجل من أهل الرياض يأخذُ الغرب- نوع من الدلو كبير-يجعل فيه ماء ويحمله على ظهرِه، والغرب لا يمسِكُ الماء، والإبل عنده لا يركَبُها، وتركوها خاويةً على عروشها: الطعام واللحم في القدور، والسواني في المناحي، والأبواب لم تغلق, وفي البلدِ مِن الأموال ما يعجِزُ عنه الحصر, فلما دخل عبد العزيز الرياضَ نادى فيها بالأمانِ، فرجع كثيرٌ منهم وسكنوها، وحاز عبد العزيز ما فيها من أموالِ الهاربين من السلاحِ والطعام والأمتعة وغير ذلك، ومات ممَّن مع دهام في هزيمتِه أربعمائة..  وقد أقام هذه الحرب سبعة وعشرين سنة، وذكر لي أنَّ القتلى في هذه المدة نحو أربعة آلاف رجل: من أهل الرياض ألفان وثلاثمائة, ومن المسلمين ألف وسبعمائة\". وقد ترتَّب على خروج دهام بن دواس نهائيًّا من الرياض منهزمًا, وقُضِيَ على أعتى خصوم الدعوة في نجدٍ, ودخول الرياض تحتَ حُكمِ دولة الدرعية."},{"id":4166,"title":"الدولة العثمانية وتوقيع معاهدة كوجك قاينارجة مع روسيا .","date":["العام الهجري :1187","الشهر القمري : جمادى الأولى","العام الميلادي :1773"],"text":"كانت الدولة العثمانية قد دخلت في حرب طاحنة دامت ست سنوات مع روسيا من 1181 إلى 1187هـ/ 1768 – 1774م، مُنِيَت فيها الدولة العثمانية بهزائِمَ أليمة، أجبرتها على عَقدِ معاهدة مخزية في 13 من جمادى الأولى من هذه السنة, وهي المعروفة باسم معاهدة كيتشوك كاينارجي، أو \"كوجك قينارجه\" في مدينة قينارجة في بلغاريا على البحر الأسود، استطاعت روسيا من خلالِ هذه المعاهدةِ أن تحقِّق نصرًا عظيمًا على العثمانيين؛ حيث حقَّقت فيه آمالَها بأن يتحوَّل البحرَ الأسودَ مِن بحيرة عثمانية خالصة إلى بحيرة عثمانية روسية، أصبحت الملاحةُ الروسيةُ تتمتع بحُرِّية التنقُّل في البحر الأسود دون قيدٍ أو شرط. وقد تضمَّنت المعاهدة 28 مادة، ومادتين منفصلتين، وعدة شروط، منها: أن يحصُلَ الروس على حَقِّ رعاية السكان الأرثوذكس في البلاد العثمانية، وكان من شأنِ هذا البند أن تتدخَّل روسيا في شؤون الدولة العثمانية بصورة مستمرة. في لقاءِ قيصر روسيا والسفير الإنجليزي، لم تكتف روسيا بما حصَلَت عليه من مكاسِبَ من الدولة العثمانية، وإنما امتَدَّ بصرها إلى تمزيق الدولة، وتوزيع ممتلكاتها, ومن بنود المعاهدة إزالةُ العداوة بين الدولة العثمانية وروسيا، وحلولُ الصلح، وصيانةُ الاتفاقات من التغيير، والعفوُ عن الجرائم التي اقترفها رعايا الطرفين. عدمُ حماية الرعايا الملتَجِئين أو الفارِّين أو الخَوَنة ضمِن الشروط. اعتراف الطرفين بحرية بلاد القرم بلا استثناءٍ واستقلالها، ولهم الحريةُ التامة بانتخاب خان لهم دون تدخُّل، ولا يؤدون ضريبة. وباعتبارهم مسلمين فإنَّ أمورهم المذهبية تُنَظَّم من قبل السلطان بمقتضى الشريعة الإسلامية. سحب القوات العثمانية من القرم وتسليم القلاع، وعدم إرسال جنودٍ أو محافظ عسكريٍّ. حرية كل دولة في بناء القلاعِ والأبنية والتحصينات وإصلاحِ ما يلزم منها. تعيينُ سفير روسي في الأستانة من الدرجة الثانية، والاعتذارُ له رسميًّا عما يحدث من خلل. تعهُّد الدولة العثمانية بصيانةِ الحقوق والكنائس النصرانية في أراضيها، ومنح الرخصة من الخَلَل. حرية زيارة رُهبان روسيا للقُدسِ والأماكن الأخرى التي تستحِقُّ الزيارة مُرَخَّصٌ بها دون دفع جزيةٍ أو خراجٍ، ويُعطَون التسهيلات والحماية أثناء ذلك. حريةُ الملاحة للرُّوس في كافة الموانئ العثمانية في البحرين الأبيض المتوسط والأسود مضمونةٌ، وكذلك حريةُ تجارة الرعايا الروس في البلاد العثمانية برًّا وبحرًا مكفولةٌ، وللتجارِ الروس حريةُ الاستيراد منها والتصدير إليها والإقامة فيها. ويحقُّ لروسيا تعيينُ القناصل في كافة المواقع التي تراها مناسبة. يجب على الدولة العثمانية التعهُّدُ ببذل جهدِها في كفالة حكومات الولايات الإفريقية إذا ما رغب الروسُ بعقد معاهدات تجارية فيها. يحقُّ للروس بناء كنيسة على الطريق العام في محلةٍ بكل أوغلي في غلطة بإستانبول غير الكنيسة المخصِّصة، وتكون تحت صيانة سفير روسيا، وتؤمَّنُ الصيانة الكاملة لها والحراسةُ التامة خوفًا من التدخل. إعادةُ بعض المناطق للدولة العثمانية من روسيا بشروط: منها العفوُ العام عن أهاليها، وحريةُ النصارى منهم من كافةِ الوجوه، وبناءُ كنائس جديدة، ومنح امتيازات للرهبان، وحرية الهجرة للأعيان، وعدم التعرُّض لهم، وإعفاؤهم من تكاليف الحرب والجزية. يرُدُّ الروس جزائر البحر الأبيض المتوسط التي هي تحتَ حُكمِهم للدولة العثمانية التي يجِبُ أن تعفو عن أهلِها وتعفيهم من الرسومِ السنوية وتمنَحَهم الحرية الدينية وترخِّصَ لِمن يريد منهم ترك وطنهم. كما ذُكِرَت بنود أخرى تتعلَّقُ ببعض المناطق في القرم، وبتدابير الانسحاب، وإخلاء الأفلاق والبوجاق والبغدان، وبتسريح الأسرى، وتعيين السُّفراء من أجل المصالحةِ، وتعهدت الدولة العثمانية بتأدية خمسة عشر ألف كيسًا لروسيا في مدة ثلاث سنين يُدفَعُ منها في كل سنة قِسطٌ، وهو خمسة آلاف كيس!!"},{"id":4167,"title":"القضاء على ثورة ظاهر العمر الذي استولى على فلسطين .","date":["العام الهجري :1188","العام الميلادي :1774"],"text":"بعد أن استطاع أبو الذهب محمد بك أن يقضيَ على فتنة علي بك ومَن معه من الروس، وكان ظاهر العمر من شركاء علي بك، لكنه كان في عكا متملكًا لها، فأمر السلطانُ عبد الحميد واليَه أبا الذهب محمد بك بملاحقة ظاهر العمر والقضاء عليه فهرب ظاهر إلى صفد فارًّا من محمد بك الذي بقي محاصِرًا له في جبال صفد إلى أن استطاع أن يقتُلَه في هذا العام."},{"id":4168,"title":"هجوم خالد بن عريعر على منطقة القصيم .","date":["العام الهجري :1188","الشهر القمري : ربيع الأول","العام الميلادي :1774"],"text":"شَنَّ خالدُ بن عريعر هجومًا عاصفًا على منطقة القصيم، وركز هجومَه على بلدة بُريدة، ونجح في إقصاء أميرِها عبد الله بن حسن وأسرته الموالين للدرعية، وعيَّن عليها راشِدًا الدريبي المناهض لإمارة الدرعية ودعوة الشيخ، وتشجَّع عريعر على مهاجمة الدرعية نفسِها، إلا أنَّه توفي في الخابية قرب النبقية بعد شهرين من انسحابِه مِن بُريدة."},{"id":4169,"title":"محاصرة الفرس للبصرة واحتلالهم إياها .","date":["العام الهجري :1189","العام الميلادي :1775"],"text":"حاصر الفُرسُ البصرة واحتلوها لمدة أربع سنوات، وأسهم هذا الاحتلال في إضعافِ السُّلطات العثمانية في العراق، وتحوُّل حركة التجارةِ مِن البصرة إلى الكويت."},{"id":4170,"title":"تحالف بقيادة المكرمي رئيس نجران يغزو نجد  .","date":["العام الهجري :1189","العام الميلادي :1775"],"text":"أقبل أهلُ نجران وجميعُ قبائل يام ومعهم أهلُ الوادي وغيرُهم بقيادة رئيس نجران المكرمي, وكان حويل الودعاني مع زيد بن زامل قد بذلوا له الأموال سنة 1187 ليغزو نجدًا؛ وذلك لما عهدوا منه قُوَّته حين هزم جيش الدرعية في الحاير سنة 1178 فسار معه أهل الخرج ومن حولهم، واجتمع مع المكرمي جموعٌ تضيقُ بها القِفارُ ولا تسقيهم الآبارُ والأنهار, وأرسل إليه بطين بن عريعر من النقدِ ما يزيد على ستة آلاف مشخصٍ، وأحمالًا من الطعام، فأقبل بجنوده ونزل الحاير المعروفَ بحاير سبيع، وتلاحقت باقي جنوده عليه، وحصل قتالٌ مع أهل الحاير أيامًا، ثم هجم على ضرما، وكان الإمام عبد العزيز أرسل مددًا إلى الرياض لحمايتِه، وأرسل ابنُه سعود بمددٍ لدعم أهل ضرما، فلما قصد النجراني ضرما ودخل بعض نخيلها حاربه أهلُها حربًا شديدةً وقتلوا من رجاله عددًا كثيرًا حتى خذله الله وارتحل هو ومن معه من الحلفاءِ راجعين إلى أوطانهم، وتفَرَّقوا ولم تقم لهم قائمةٌ، وندموا على ما بذلوا من الأموالِ العظيمةِ!"},{"id":4171,"title":"غزو مدينة بريدة وتعيين عبد الله بن حسن أميرا على بلدان القصيم .","date":["العام الهجري :1189","العام الميلادي :1775"],"text":"سار سعودُ بن عبد العزيز وقَصْدُه بريدة، ومعه آل عليان الذين خرجوا منها سنة 1188 عندما أخذها عريعر بن دجين عنوةً, وفرض عليها حصارًا وبنى تجاهها حِصنًا جعل فيه عدَّةَ رجال عبد الله بن حسن أميرًا عليهم يواصِلُ منه الحصارَ على بريدة، فلما اشتد الأمر بأهل بريدة أرسل أمير البلد راشد الدريبي إلى عبد الله بن حسن الأمانَ لنفسه وأن يخرجَ لوحده فأعطاه الأمان وخرج إليه راشد، ثم دخل عبد الله ومن معه البلد وملكوها، وقُتل في ذلك الحصار 50 رجلًا من قوم الدريبي، واستولى عبد الله على ما فيها من الأموالِ، وبعد هذه الواقعة انقاد أهلُ القصيم وبايعوا على السَّمعِ والطاعة، ووفد عبد الله ومعه رجالٌ من رؤساء القصيم على الشيخِ والإمام عبد العزيز فبايعوهما على السمع والطاعة، واسُتعمل عبد الله بن حسن أميرًا على جميع بلدانِ القصيم."},{"id":4172,"title":"دخول زيد بن زامل رئيس الدلم في طاعة الدرعية  .","date":["العام الهجري :1189","العام الميلادي :1775"],"text":"قَدِمَ رئيس الدلم زيدُ بن زامل ومعه أناسٌ من أعيان قومِه على الإمام عبد العزيز في الدرعية فجأةً، فبايعوا على الإسلامِ والسمع والطاعة، والالتزام بإقامة الشريعة في بلادِهم، فطلب منه عبد العزيز أنواعًا من السلاح والخيل, فلما أرسله أخذ عبد العزيز البعضَ منه وردَّ له البعض الآخرَ ترغيبًا له وتأليفًا. لكنَّه نقض العهدَ في السنة التالية."},{"id":4173,"title":"وفاة الشيخ صباح بن جابر حاكم الكويت .","date":["العام الهجري :1190","العام الميلادي :1776"],"text":"هو الشَّيخُ صُباح الأولُ بن جابر بن سَلمان بن أحمد العتبي. في سنة 1129هـ اتفق ثلاثةٌ من رؤساء القبائل التي سكَنَت الكويت وهم: صُباح بن جابر بن سلمان بن أحمد، وخليفةُ بن محمَّد، وجابر بن رحمة العتبي رئيس الجلاهمة، على أن يتولَّى صُباح الرئاسةَ وشؤونَ الحُكمِ، وأن يتشاورَ معهم، ويتولَّى خليفة شؤونَ المال والتجارة، ويتولى جابر بن رحمة شؤونَ العمل في البحرِ، وتقسَّم جميعُ الأرباح بينهم بالتساوي, ثم حاول صُباح أن يقوِّيَ مركزَه في الكويت فتمكَّن من حصولِ اعتراف الوالي العُثماني في بغداد، ومنَحَه لقبَ قائم مقام سنة 1130هـ، كما اعترف له أمير الأحساء سعدون بن غرير بحُكم الكويت، بحيث لا ينضَمُّ لخصومه وأن ينفِّذَ جميعَ أوامره وأوامِر من سيأتي بعده, وتوفِّي صباح في هذا العام وتَرَك من الأبناء سلمان ومحمد ومبارك وعبد الله الذي خلَفَه في الحُكم."},{"id":4174,"title":"حاكم الدرعية يسند إمارة بريدة إلى حجيلان العليان .","date":["العام الهجري :1190","العام الميلادي :1776"],"text":"أسندت الدرعيةُ إمارةَ بُريدة وما يتبعها إلى حجيلان بن حمد العليان بعدَ مقتَلِ أميرها عبد الله بن حسن في وقعةِ مخيريق, فنجح حجيلان في توطيدِ حُكم الدرعية هناك، وقام بكثيرٍ مِن الغزوات لمصلحةِ ذلك الحُكمِ، ومَدَّ رقعتَه، وظلَّ أميرًا نَشِطًا في غزواته حتى قضى إبراهيم باشا على الدولة السعودية الأولى، فأُخِذَ حجيلان إلى المدينة النبوية عام 1234هـ، وتوفِّيَ فيها بعد وصولِه إليها بقليل."},{"id":4175,"title":"هزيمة جيش الدرعية في وقعة مخيريق  .","date":["العام الهجري :1190","العام الميلادي :1776"],"text":"سار الإمام عبد العزيز بجنودِه، وقصد عربان آل مرة في أرض الخرجِ, وكانوا قد اجتمعوا فيها وتأهَّبوا للحرب والقتالِ، فشَنَّ عليهم عبد العزيز غارةً في الصباح الباكر، فتفازع العربان وحصل قتالٌ شديد، وكانت الغارة على العربان في شعبٍ ضَيِّق، فأمسك العربان مدخَلَ الشِّعبِ ولم يكن لعبد العزيز مصدرٌ غيرُه، فوقعت الهزيمةُ على عبد العزيز وألجأهم العُربان إلى عقبة وعرة تسمى مخيريق الصفا، فوقع فيها كثيرٌ مِن الركاب والرجال، وقُتِل منهم خمسون رجلًا، منهم أمير القصيم عبد الله بن حسن."},{"id":4176,"title":"فشل الحملة الأسبانية للسيطرة على الجزائر .","date":["العام الهجري :1190","الشهر القمري : جمادى الأولى","العام الميلادي :1776"],"text":"فشلت الحملة الأسبانية، التي انعقد لواؤها للسيطرة على الجزائر، وكانت الحملةُ تتكوَّن من 22 ألف جندي، وخَسِرَ الأسبان في هذه الحملة 7 آلاف قتيل، وهو ما أثار استياءَ الملك كارلوس الثالث في مدريد، في حين أقام العثمانيون الأفراحَ في إستانبول بهذا النصر."},{"id":4177,"title":"غزو سعود بن عبد العزيز حرمة  .","date":["العام الهجري :1191","العام الميلادي :1777"],"text":"أجمع أهلُ حرمة- وهي بلدة في المجمعة- الغدرَ بأميرهم عثمان بن عبد الله، وكان رئيسُهم في الغدر جويسرَ الحسيني الذي اتَّفَق مع سويد بن محمد صاحب جلاجل وأحمد بن عثمان أمير المجمعة على الغدر بأتباع الدعوة في بلدانِهم, فلمَّا أجمعوا على إنجازِ ما اتَّفَقوا عليه، أرسلوا إلى كبار أتباع الدعوةِ في المجمعة ليأتوا إلى حرمة؛ ليُعَلِّموا أهلَها، فلما جاء بعضُهم حرمة، كان أمير حرمة عثمان في نخلٍ له خارِجَ البلدةِ، فأرسل جويسر من يخبِرُه بقدوم ضيوفٍ مِن المجمعة، فلما رجع اجتمع عليه ستةُ رجال منهم أخوه خضير بن عبد الله، وابن عمه عثمان بن إبراهيم، فقَتَلوه، ثم بادروا لمن جاء من المجمعة فحَبَسوهم, ثم ساروا إلى المجمعة ليستولوا على قلعتِها وقَتل من فيها من أتباع الدعوة، لكِنَّ أهل المجمعة تنبَّهوا لهم فتحصَّنوا في القلعة، فلم يستطيعوا اقتحامَها، فرجعوا خائبين, ثم أرسلَ أهل المجمعة إلى عبد العزيز لإخبارِه بما وقع لهم على يدِ أهل حرمة, فأمرَ ابنَه سعودًا أن يسيرَ إلى حرمة، فسار معه جميعُ أهل البلدان من العارض، فنزل بالهضبة المحيطة بحرمة، وبقي يقاتل أهلَها ليلًا ونهارًا مدَّةَ أيام، وقُتِلَ من الفريقين رجالٌ, فلما أجهد الحصارُ أهل حرمة طلبوا الصلحَ مِن سعود فقَبِلَ بشرط أن يُطلِقوا الأسرى الذين عندهم من أهلِ المجمعة وأن يرحَلَ جويسر الحسيني عن البلدة, فأطلقوا سراح المحبوسين ورحل جويسر إلى بغداد، ثم انتقل إلى مكة بعد أن ظهر ابنُ سعود في نجدٍ وما حولها، وصار جويسر مدافعًا عن الشيخ محمد بن عبد الوهاب ودعوتِه عند شريفِ مكة. واستعمل عليهم الأميرَ ناصر بن إبراهيم.  ثم اتَّجه سعود إلى المجمعة واستلحق أحمدَ بن عثمان ورحل به وبعيالِه واستعمل على المجمعة أميرًا هو عثمان بن عثمان، ولما وصل جلاجل استلحقَ سويدًا بعياله، وأمر الجميع أن يقصدوا بلدَ القصب ثم نزلوا شقراء إلى أن أمَرَهم الإمام عبد العزيز أن ينزلوا جميعًا الدرعية بعيالهم."},{"id":4178,"title":"وفاة الشيخ أحمد الدمنهوري شيخ الأزهر .","date":["العام الهجري :1192","العام الميلادي :1778"],"text":"هو الشيخُ الإمام أبو العباس أحمد بن عبد المنعم بن يوسف بن صيام الدمنهوري، شيخ جامع الأزهر، وأحد عُلماء مصر المُكثرين من التصنيف، ولِدَ بدمنهور سنة 1101هـ - 1589م. تعلَّم في الأزهر حتى تولى مشيخَتَه. فقد اشتغل بالعلمِ، وجدَّ في تحصيلِه، واجتهد في تكميلِه، وأجازَه علماء المذاهب الأربعة، وسمحوا له بتدريسِ الفِقهِ على المذاهب الأربعة, حتى سُمِّي بالمَذهبي. كانت له حافظةٌ وذاكرةٌ عجيبة, قيل عنه إنه: \"أعلمُ أهل عصره بالديار المصريةِ في جميع الفنون النَّقلية والعقلية, وإنه بحرٌ لا ساحِلَ له\" كان مُهابًا لدى الأمراء؛ لكونه قوَّالًا للحق، أمَّارًا بالمعروف، سمحًا بما عنده من الدنيا، وقَصَده الملوك والولاة من كلِّ حَدبٍ مِن طَرفِ الدولة, وله مصنَّفات كثيرة، منها: النفع العزيز في صلاح السلطان والوزير، ونهاية التعريف بأقسام الحديث الضعيف، والفيض العميم في معنى القرآن العظيم، ومنهج السلوك في نصيحة الملوك، ومشاركات في الطب والكيمياء. توفي في القاهرة."},{"id":4179,"title":"أغا محمد يؤسس الدولة القاجارية  .","date":["العام الهجري :1193","العام الميلادي :1779"],"text":"كان أغا محمد خان- أغا أي: مَخْصِي- وهو من قبيلة قاجار المشهورة التي سكنت استراباد شمالي إيران، وهم من الشيعة الاثني عشرية، كان مستشارَ كريم خان الزندي، وقيل: إنه لَمَّا توفي كريم خان فرَّ أغا محمد خان من شيراز إلى طهران، وأعلن استقلالَه، ثم لَمَّا وصل إلى بلاده الأصلية جمع حولَه القاجارية وضمَّ إليه أيضًا بعض القبائل المجاورة وتصالحَ مع الأفشار، فأصبح هو صاحِبَ الأمر والنهي في شماليَّ إيران، وكان منافسُه لطف علي خان صاحبَ إيران الجنوبية وقاعدته شيراز، وحصلت بينهما حروبٌ كثيرة إلى أن قام وزيرُ لطف علي واسمه إبراهيم بتسليمِ مدينة شيراز لأحد قوَّاد أغا محمد عندما غاب لطف علي عنها، ثمَّ ملك أغا محمد كرمان، واستطاع أن يقضيَ على لطف علي، حيث سلَّمه بعضَ القبائل الذين قَبَضوا عليه لأغا محمد، ففقأ عينيه وقتله، فأصبحت إيران كلُّها في قبضته، وانتهت دولة الزنديين، وبدأت دولة القاجاريين على إيران."},{"id":4180,"title":"أهل حرمة ينقضون العهد ويغزون المجمعة .","date":["العام الهجري :1193","العام الميلادي :1779"],"text":"نقض أهلُ حرمة عهدَهم مع الأمير سعود بن عبد العزيز وتواعَدوا مع أهل الزلفي وأرسلوا إلى سعدون بن عريعر حاكِمِ الأحساء وأتباعِه مِن العربان أنَّهم يريدون أن يَسطُوا على بلدة المجمعة، وكان فيها مرابط وضباط من جهة الإمام عبد العزيز بن محمد، وقد تحقَّق عند أهل حرمة أنَّهم إن لم يأخُذوا المجمعة ويضبطوها لم يكن لهم في بلدهم قرار, فسار رجالٌ مِن أهل حرمة في زيِّ النساءِ وأمسكوا بروجَ النخيل، ثمَّ قَدِم عليهم أهلُ الزلفي بشوكتِهم، ثم قدم سعدون بالجموعِ العظيمة من بني خالد وغيرهم، فاجتمعت تلك الجموعُ ونزلوا وسطَ النخيل وحصروا أهل المجمعةِ في بلدتهم أيامًا حتى ضاق عليهم الأمرُ، فهمُّوا بالمصالحة وأرسلوا إلى سعدون يطلبون مهلةَ يومين يرجون وصولَ المدد لهم من جهة عبد العزيز, كان حسنُ بن مشاري بن سعود يدبِّرُ الأمر من جلاجل لدَعمِ أهل المجمعة، وتمكن مع بعض رجاله من أهل العارض وسدير من دخول المجمعة ليلًا على الرغم من شدة الحصار عليها. فلما عَلِمَ ابن عريعر وأتباعُه بذلك عرفوا أنهم ممتنعون، وقد كانت صدورُ البوادي ضاقت من طولِ الحصارِ، فرحلوا من المجمعة منصرفين، ورجع أهل الزلفي إلى بلَدِهم، واستقَرَّت الحرب بين أهلِ الجمعة وأهل حرمة، فجهز عبد العزيز أخاه عبد الله بالجنودِ، فنازل أهلَ حرمة ووقع بينهم قتالٌ شديدٌ قُتِل فيه عددٌ مِن رجال حرمة، ثم رحل عنهم عبد الله بعد أن ترك لأهل المجمعة خيلًا ورِجالًا، واستمَرَّت الحربُ بينهم أيامًا."},{"id":4181,"title":"الأمير سعود يغزو بلدة حرمة والإمام عبد العزيز يأمر بتدميرها .","date":["العام الهجري :1193","العام الميلادي :1779"],"text":"غزا سعودُ بن عبد العزيز حرمة واستنفر معه أهلَ البلدان مشاةً وركبانًا، ونزل على بلدة حرمة وحصرها حصارًا شديدًا، وقطع نخلَ قاضيها عبد الله بن المويس- ابن عم الشيخ المجدِّد، لكنه من ألدِّ أعداء الدعوة (ت1175)- ومَلَك الأمير سعود أكثَرَ نخلها وأقام عليها أيامًا يباكرهم القتالَ، فلما اشتد عليهم الحصارُ ألقى الله الرعب في قلوبهم، فأرسلوا إلى سعود وطلبوا الصلحَ فأبى إلا أن تكون بلدتُهم فيئًا، أو يزيل ما في البلدِ مِن المحذورِ ومِن الرجالِ وغيرِهم، فصالحهم على ذلك, ولَمَّا كتب لوالده الإمام عبد العزيز كتب إليه أنَّ أهلَ هذه القرية تكرَّر منهم نقضُ العهد، وهي محذورةٌ كلُّها، فاهدِمْها ودمِّرْها، فأمر سعود بهدمِها، فهدم سورَها وبعض بيوتِها، وأمَر على أناس من أهلِها ممن أثار الشرَّ على المسلمين أن يرحَلوا عنها، فارتحل كثيرٌ منهم المجمعة، والبعض الآخر إلى الزلفي."},{"id":4182,"title":"اتفاق بين الدولة العثمانية ومدينة تفليس الفارسية في رسم الحدود .","date":["العام الهجري :1194","الشهر القمري : جمادى الأولى","العام الميلادي :1780"],"text":"توصَّلت الدولةُ العثمانية في تلك الفترة إلى توقيعِ اتِّفاقٍ مع نادر شاه، أكبر ولاة فارس في مدينة تفليس، وكان الغرضُ منه هو تحديدَ الحدودِ بينهما."},{"id":4183,"title":"حرب مقاطعة ميسور بين مسلمي الهند والإنجليز .","date":["العام الهجري :1195","العام الميلادي :1780"],"text":"تعتبرُ حربُ مقاطعة ميسور من أشهر الحروبِ بين الإنكليز والمسلمين في الهند، وهذه المقاطعةُ كانت فيها المرازبة الهندوك تحت سيطرةِ المسلمين، فلما ضَعُفت الدولةُ المغوليةُ المُسلِمةُ المركزية في الهند استبَدَّ المرازبةُ بما تحت أيديهم، وكان حيدر علي خان بن فتح علي خان أحدَ قادتِهم، فخافه وزراؤهم وأرادوا البطشَ به، فلما أحسَّ بما يدبَّرُ له تسلَّمَ السلطةَ بالقوة ووسَّع مُلكَه؛ إذ استولى على أكثَرِ بلاد المهراتا وبلاد مدراس، فخاف منه الإنكليز وحاربوه وضمُّوا المهراتا إليهم، ثم استولى حيدر علي خان على جزءٍ من أراضيهم، وكان يعمَلُ على أن يوسِّعَ أملاكَه على حساب مقاطعة ميسورٍ، إلَّا أنَّه في الوقتِ نفسِه عرف أنَّ الصمودَ أمام الإنكليز والانتصارَ عليهم لا يكونُ باتِّباع الطرق التقليدية والأسلحة القديمة؛ إذ لا بدَّ من استعمال الأساليب الحديثة والأسلحة المتطورة، فاستخدم الفرنسيين لتحقيق هدفِه، وقد كانوا يومَها في حربٍ ضِدَّ الإنكليز، ولكنَّ الصليبيةَ هي هي؛ فبعد أن انتهت الحربُ بين الفرنسيين والإنكليز تخلَّت فرنسا عن حيدر، فانتصر عليه الإنكليز، ثم توفِّي حيدر عام 1196هـ وخلَفَه ولدُه فتح علي المعروف باسم تيبو، الذي تابع قتالَ الإنكليز وهُزم أيضًا فأجبِرَ على توقيع معاهدة سرنغا باتام التي خسر بموجِبِها كثيرًا من أملاكه، ودفع غرامةً حربية، وكان هذا في عام 1207هـ."},{"id":4184,"title":"إجماع أكثر بلدان القصيم على نقض عهدهم مع الدرعية .","date":["العام الهجري :1196","العام الميلادي :1781"],"text":"أجمع أهلُ القصيمِ عدا بريدة والرس والتنومة على نقضِ عَهدِهم مع الدرعية، وأعلنوا الحربَ ضِدَّها، وتزعمت مدينةُ عنيزة هذا العصيانَ، وتعاهدوا أنَّ كلَّ أهلِ بلدٍ يقتلون في يومٍ محدَّدٍ مَن عندهم مِن الدعاةِ والمعلِّمين الذين أوفدَتْهم الدرعية للإرشادِ, وأرسلوا إلى صاحِبِ الأحساءِ سعدون بن عريعر يخبرونَه بأمرهم ويستحِثُّونه للقدومِ عليهم, فاستنفر في الحالِ العربان، فلما قرُبَ من القصيم قام كلُّ أهلِ بلدٍ وقتلوا مَن عندَهم من المعلِّمين والدُّعاة."},{"id":4185,"title":"وفاة ضاهر العمر حاكم عكا  .","date":["العام الهجري :1196","العام الميلادي :1781"],"text":"هو ضاهر (ظاهر) بن عمر بن أبى زيدان. وُلِد في صفد سنة 1106هـ كان داهيةً شجاعًا. يقال: إنَّ أصله من المدينة، هاجر أحدُ أجداده إلى فلسطين،  وكان والدُه وجدُّه وأعمامُه حكامًا في صفد وعكا. تولى إدارة عكَّا وصفد، فأقام إمارةً قوية تمثِّل مصدرَ قلقٍ للدولة العثمانية في شماليَّ فلسطين، ضمَّت صفد وطبرية والجليل الأعلى والناصرة ونابلس وعكا، فقاتله سليمان باشا والي دمشق العثماني سنة 1150هـ، فتحصَّن في طبرية إلَّا أن موت سليمان باشا المفاجئ أدَّى إلى استفحال أمر ظاهر وازدياد نفوذه، فقام بتحصين عكا وبناء سورِها، وضَمَّها إلى إمارته واتخذَها عاصمةً لها، وانتعشت التجارةُ في عهده، واستقَّر الأمن، ولكِنَّ طموحَ ظاهرِ العمر دفعه إلى التوقف عن دفع الضرائب للعثمانيين، وتحالفَ مع على بك الكبير حاكمِ مصرَ واتفقا على عصيان العثمانيين، فحاربا الواليَ العثماني في الشام عثمان باشا الصادق، واضطرت الأستانة إلى الاعتراف بولاية ظاهر العمر، ولكِنْ سرعان ما ضَعُف أمرُه بعد مقتل علي بك الكبير، فأصدرت الدولة العثمانية أوامرها إلى حسن باشا الجزائري أمير البحر بالقضاء على ظاهر العمر واحتلال عكَّا، فاغتاله رجل مغربي من رجالِه وهو يستعِدُّ لمقاومة العثمانيين، فانهارت دولتُه بمقتَلِه."},{"id":4186,"title":"سعدون بن عريعر يغزو بريدة بتحريض من أهل القصيم .","date":["العام الهجري :1196","العام الميلادي :1781"],"text":"قدم أميرُ الأحساء سعدون بن عريعر القصيمَ لِمساندة أهلِها في الغدر بأتباعِ دعوة الشيخ محمد بن عبد الوهاب وأنصار الدرعية، وكان معه بنو خالد، وقد استنفر الظفير وعربان شمر ومن حضَر من عربان عنزة، فنزلوا بريدةَ وأحاطوا بها، فبادر رجالٌ منهم للقتال، فظهر أهلُ البلد فقتلوهم وأرسلوا برؤوسِهم لسعدون فامتلأ غيظًا وغضبًا، فهدد باستئصالهم إن ظفر بهم، فزحف على البلدة فوقع قتالٌ شديدٌ ولم ينَلْ منهم بشيءٍ، فحمل عليهم في الغدِ، وأراد جنودُه أن يتسوَّروا السورَ، لكن أهلَ بُريدة دافعوا عنه فانهزم جندُ سعدون وتركوا قتلاهم عند السور، فاستشار أهلَ القصيم في مكيدةٍ يكيد بها أهلَ بُريدة، فأشاروا أن يصنعَ مِدفَعًا كبيرًا يرمي به سور البلدِ وأبراجَه، لكنَّه لم يفلِحْ في صناعتِه على الرغم من دَعمِ أهل القصيم له بالموادِّ اللازمة، واستمرَّ القتالُ عدة أيام والنصرُ فيه حليفٌ لأهل بريدة، ثم بنى قصرًا أمام البلدة وضع فيه رجالًا، فتمكن أهل بريدة مِن قَتلِهم وهدم القصرِ، وأثناء الحصار تعرَّض سارحة سعدون إلى النَّهبِ مِن أهل الرَّس، وقُتل عددٌ من رجاله، وكان رئيس بريدة وبطلُها الذي يدير الحربَ ضِدَّ سعدون وأتباعه هو حجيلان بن حمد من رؤساء آل أبي عليان، فلما مضى خمسة أشهر وضاقت صدورُ العربان من الحربِ، حمل سعدون وجموعُه حملةً هائلة على الأسوار والبرج وقاتلهم أهلُ البلد قتالًا شديدًا حتى ردُّوهم على أعقابهم وقتلوا منهم عدَّةَ قتلى، فداخلهم بعد ذلك الفشلُ، فقرَّروا الرحيلَ، ولما رحلوا تفرَّق أهل القصيم وعادوا إلى أوطانهم, فخرج حجيلان بأهلِ بريدة فدخل الشماسَ وقتل من وجدَ فيها، وهربَ أهلُها فانزعجت قلوبُ أهل القصيم بعد ذلك، فأرسلوا إلى حجيلان يطلبون منه الأمان فطلب عليهم النَّكالَ مِن الأموالِ فوَفَوا له بها."},{"id":4187,"title":"قحط دالوب في نجد   .","date":["العام الهجري :1197","العام الميلادي :1782"],"text":"هذه السَّنةُ هي أوَّلُ القحط المسمَّى دالوب، قلَّ فيه المطرُ وغلت الأسعارُ واشتَدَّ الغلاء والقحطُ والجوعُ، ومات أناسٌ جوعًا من النساء والرجال والأطفال والبهائم، فأمر الإمامُ عبد العزيز بصَدَقاتٍ للضعفاء من أهل البلدانِ، وفرَّق عليهم شيئًا كثيرًا."},{"id":4188,"title":"وفاة الأمير زيد بن زامل أمير الخرج  .","date":["العام الهجري :1197","العام الميلادي :1782"],"text":"هو الأميرُ زيد بن زامل بن عثمان الديلمي من عائذ من الصقر من عبيدة من قحطان، أمير الخرج، أعلن عداءَه لدعوة الشيخ ودولة الدرعية من بداية الدعوةِ، وخاض معها عدةَ معاركَ، وشارك في عدةِ أحلافٍ تشكَّلت ضِدَّ الدرعية, وقد دخل في صلحٍ مع أميرِ الدرعية وبايع الشيخَ والأميرَ عِدَّةَ مراتٍ، لكنه سرعان ما ينقُضُ العهدَ ويرجِعُ عن بيعتِه لهم. إلى أن كانت نهايتُه  كقاطع طريقٍ، عندما أغار على عربان سبيع وأخذ من إبِلِهم, فأمر الإمامُ عبد العزيز بن محمد بالقبضِ عليه لقطعِه الطريقَ، فتمكَّنت فرقة بقيادة سليمان بن عفيصان مِن قَتلِ زيدِ بنِ زامل أثناء عودتِه مِن غزو قبيلة سبيع, وخَلَفه في إمارةِ الخرج ابنُه براك بن زيد."},{"id":4189,"title":"انتزاع آل خليفة حكم البحرين من آل مذكور التابعين لحكام فارس .","date":["العام الهجري :1197","الشهر القمري : شعبان","العام الميلادي :1783"],"text":"تعرَّض وفدٌ من آل خليفة (عتوب الزبارة) في البحرين إلى اعتداءٍ أدى إلى وقوعِ قتال بين أتباعِ آل خليفة والبحارنة, فقُتِل أحد أتباع الخليفة، فغَضِب أهلُ الزبارة نتيجةً لذلك فأرسلوا سفينةً صغيرة للبحرين؛ للأخذ بثأر القتيل، فتمكنوا من قتلِ غريمِهم وقتلوا معه خمسةَ أشخاص, فجهَّز ناصِرُ آل مذكور- التابع لحكم الزنديين في بوشهر- سفُنًا حربية تحتوي على خمسة آلاف مقاتلٍ، وتولى ابنُ أخيه محمد بن سعدون آل مذكور القيادةَ، فحاصروا الزبارةَ لمدة شهر، انتهت بمعركةٍ حاميةِ الوطيسِ، فانهزمت قواتُ الشيخ ناصر، واضطروا إلى الانسحابِ، وقُتل في تلك الوقعةِ الشيخُ محمد آل مذكور قائد الحملة، وكان ذلك في 18 جمادى الآخرة 1197هـ ما إن انهزمت قوات آل مذكور عن الزبارة حتى انضمَّت قبائل قطر إلى العتوب، وهي الجلاهمة، وآل مسلم، وآل بنعلي، وآل سودان، وآل مرة، وآل بوعينين، والقبيسات، وآل سليط، والمنانعة، والسادة؛ حيث شرع أحمد آل خليفة بتنظيمِ صفوف قواتِه لاحتلال البحرين وأخذِها من آل مذكور. ثم بادر عتوب الكويت بالتوجُّه إلى البحرين في قوةٍ مكونة من ستة جلابيت وعددٍ من القوارب المسلحة أرسلها الشيخ عبد الله الصباح لدَعمِ أقاربه العتوب, تدفَّقت تلك الجموع إلى البحرين وأجبروا حاميَتَها على الاستسلام يوم 28 شعبان 1197 هـ/ 28 يوليو 1783م. حاول الشيخ ناصر آل مذكور استرجاع جزيرة البحرين بعد استيلاء العتوب على جزيرة البحرين بدعمٍ مِن العثمانيين، حاول إقناع الحكومة الفارسية في بوشهر أهمية استرجاع جزيرة البحرين من يدِ العتوب التابعين لحاكم الكويت الشيخ عبد الله بن صباح بن جابر آل صباح، ولكِنَّ انشغال الحكومة الفارسية بالحروبِ والفِتَن التي أعقبت مقتل كريم خان زند حالت دون ذلك."},{"id":4190,"title":"إحباط البحرية العثمانية محاولة الأسبان لاحتلال الجزائر .","date":["العام الهجري :1197","الشهر القمري : شعبان","العام الميلادي :1783"],"text":"تمكَّنت البحريةُ العثمانية في موانئ الجزائرِ بنجاحٍ مِن مهاجمةِ وتشتيت 75 سفينةً حربيةً إسبانيةً كانت تحاوِلُ إنزالَ قواتها في موانئ الجزائر؛ وذلك تمهيدًا منها للقيام باحتلالِها."},{"id":4191,"title":"ضياع القرم من المسلمين واستيلاء الروس عليها  .","date":["العام الهجري :1198","العام الميلادي :1783"],"text":"أرسلت روسيا قوةً كبيرةً إلى فارنا من بلغاريا على البحر الأسود ولم تستَطِع القواتُ العثمانية صَدَّها، فاضطرت لعقدِ الصلحِ مع روسيا، فتَمَّ الصُّلحُ في مدينة قينارجة في بلغاريا، اعترفت فيه الدولةُ العثمانيةُ باستقلالِ تتار القرم ومنطقة بسارابيا في رومانيا وقوبان في القفقاس، على أن تكونَ للدولة العثمانيةِ المرجعيةُ الدينيةُ، وتدفَعَ لروسيا مبلغًا ماديًّا كغرامةٍ حربيةٍ، وتكون لها حريةُ الملاحة في البحر الأسود، ويكون للروسِ حَقُّ حماية النصارى الأرثوذكس، وتُعتبَرُ هذه المعاهدة من أسوأ ما مرَّ على الدولة العثمانية ممَّا يدُلُّ على شدة تدهورها وضَعفِها؛ حيث اعترفت الدولةُ العثمانيةُ بانضمامِ القرم نهائيًّا إلى روسيا, وكانت القرم تابعةً للعثمانيين فترةً تزيد على 296 عامًا."},{"id":4192,"title":"عمليات الأمير سعود بن عبد العزيز العسكرية ضد الأحساء .","date":["العام الهجري :1198","العام الميلادي :1783"],"text":"بدأت العملياتُ العسكريةُ لدَولةِ الدرعية ضِدَّ الأحساء على يدِ الأمير سعود بن عبد العزيز، وذلك ردًّا على العداءِ السَّافِرِ من بني خالد لدولةِ الدرعية، فسار الأميرُ سعود بقواتِه حتى وصل قرية العيون في الأحساءِ، فغَنِمَ جَيشُه غنائمَ كثيرةً، ثم قفل راجعًا إلى بلادِه."},{"id":4193,"title":"قدوم وفد من وادي الدواسر عليهم ربيع بن زيد .","date":["العام الهجري :1199","العام الميلادي :1784"],"text":"في هذه السنة قَدِمَ ربيع وبدن ابنا زيد الدوسري رئيس المخاريم من وادي الدواسِرِ، ومعهما رجالٌ من رؤساء قومِهما على الشيخ محمد والإمام عبد العزيز، وبايعوا على دين اللهِ ورَسولِه والسَّمعِ والطاعة, ثم أقاموا في الوادي أتمَّ القيامِ بأمرِ الدعوةِ، وهدى الله بهم أناسًا كثيرًا."},{"id":4194,"title":"انضمام الأفلاج لدولة الدرعية  .","date":["العام الهجري :1199","العام الميلادي :1784"],"text":"وفد إلى الدرعية أهلُ الأفلاج وبايعوا الشيخَ والإمامَ عبد العزيز على دينِ اللهِ والسَّمعِ والطاعةِ."},{"id":4195,"title":"الأمير سعود يخضِع منطقة الخرج لسلطان الدرعية .","date":["العام الهجري :1199","الشهر القمري : ذي الحجة","العام الميلادي :1785"],"text":"شنَّ الأميرُ سعود هجومًا على الدلم من منطقةِ الخرج، فحاصرها وقطع نخلَها حتى أخذَها عَنوةً وقَتَل أميرها تركي بن زيد بن زامل، واستعمل عليها سليمانَ بن عفيصان، ثم أذعن له جميعُ أهل بلدان الخرج وحوطة بني تميم والحريق واليمامة والسلمية وغيرها، وطلب سعود منهم نكالًا مِن النقد وغيرِه، فصَبَروا له بذلك وبايعوه كلُّهم على دينِ الله ورسولِه والسَّمعِ والطاعة."},{"id":4196,"title":"احتلال الروس بلاد القرم  .","date":["العام الهجري :1200","العام الميلادي :1785"],"text":"سمَحت معاهدةُ كيتشوك كاينارجي للروسِ بالحصول على الامتيازات ضِمنَ البلاد العثمانية، تشمل الأرثوذكس في الأفلاق والبغدان وجزر بحر إيجة، وبالتالي تحوَّلت روسيا إلى حماية الأرثوذكس في أي مكان في الدولةِ العثمانية, ولم يكتَفِ الروس الصليبيون بذلك، بل واصلوا تآمُرَهم، وفاجؤوا الدولة العثمانية بدخولِ قواتهم بلادَ القرم- وهي جزءٌ من ولايات الدولة العثمانية- بسبعين ألف جندي، غيرَ مبالين بمعاهدة كاينارجي, وانبهرت ملكتُهم كاترين الثانية بهذا النصرِ، وطافت ربوعَ القرم وأُقيمت لها الزيناتُ وأقواس النصر التي كُتِب عليها (طريق بيزنطة), وأثارت الدولةَ العثمانيةَ مِن جديدٍ فأرسل الباب العالي مذكرةً إلى السفير الروسي بالأستانة، وذلك في صيف عام 1200هـ فيها عدة مطالب، منها: التنازل عن حماية بلاد الكرج التي تخضع للسيادة العثمانية، وتسليم حاكم الفلاح العاصي للدولة، ورفضت روسيا المذكرة، فأعلن الباب العالي الحربَ، وسجَنَ السفيرَ الروسيَّ."},{"id":4197,"title":"إعلان الدولة العثمانية الحرب على روسيا .","date":["العام الهجري :1200","العام الميلادي :1785"],"text":"عَلِمت الدولةُ العثمانية أنَّ روسيا تريدُ الحربَ؛ لذا أرادت أن تبدأ هي بالحربِ قبل أن يستعِدَّ خصومُها؛ ولإيجاد سبب لذلك فقد طلبَت من السفير الروسي إبلاغَ حكومته عدَّة طلبات، وهي: تسليم حاكم الأفلاق الذي أعلن العصيان على الدولة العثمانية والتجأ إلى روسيا، التنازل عن حماية بلاد الكرج؛ لأنها تحت سيادة الدولةِ العثمانية، عزلُ القناصل الذين يثيرون السكانَ، وقَبولُ قناصِلَ عثمانيين في موانئ البحرِ الأسود، مِن حقِّ الدولة العثمانية تفتيشُ المراكب الروسية التجارية خوفًا من نقلها الأسلحة. وقد رفضت روسيا هذه الطلباتِ، فأعلنت الدولةُ العثمانية الحربَ عليها وطلب القائِدُ الروسي من الإمبراطورة كاترين الثانية الانسحابَ مِن بلاد القرم نتيجةَ عدَمِ الاستعداد، ولكنَّها رفضت ذلك، وأمرَتْه بالتقدُّمِ فامتثل وتمكَّنَ مِن أن يحتلَّ ميناء أوزي عام 1203هـ وأعلنت النمسا الحربَ على الدولةِ العثمانية تضامنًا مع روسيا."},{"id":4198,"title":"وقعة جضعة ولجوء سعدون بن عريعر للدرعية .","date":["العام الهجري :1200","العام الميلادي :1785"],"text":"اتَّفق رؤساء المهاشير من بني خالد وآل صبيح مع عبد المحسن بن سرداح آل عبيد الله ودويحس بن عريعر على عداوةِ سعدون بن عريعر رئيس بني خالد، وحَربِه، واستنجدوا بثويني بن عبد الله شيخ المنتفق، فتنازلوا مع سعدون في قتالٍ، وقُتِل بينهم كثيرٌ من القتلى، وصارت الكرَّةُ على سعدون ومن معه، فانهزموا وفرَّ سعدون إلى الدرعية وطلَبَ الأمانَ من عبد العزيز لكنَّه لم يجِبْه إلى طلَبِه؛ بسبب هُدنةٍ بينه وبين ثويني شيخ المنتفق، فعزم سعدون دخولَ الدرعية بدون أمانٍ، فشاور الأميرُ الشيخَ فأشار إليه أن يأذَنَ له بالدخولِ، فدخل وأكرمَه عبد العزيز، فلما علم ثويني بذلك تعاظم الأمرَ فاستعطَفَه عبد العزيز فلم ينجَحْ، فقام ثويني بالكيدِ للدرعية وأتباعِها."}]
